window.__CHRONICLE_CHUNK["wd-05"] = [
  {id:"world--1800--m01",track:"world",year:1800,yearApprox:false,dim:"military",weight:4,title:"马伦哥战役",summary:"拿破仑以援军反攻击败奥军，奠定法国打赢反法同盟战争。",detail:{background:"第二次反法同盟战争中，拿破仑任第一执政后率预备军团越过阿尔卑斯山进入意大利，意图解马塞纳在热那亚之围。",process:"1800年6月14日，法军与梅拉斯率奥军在皮埃蒙特马伦哥村一带交战。法军左翼先被击溃、阵线后撤，拿破仑整收残部；傍晚德赛率援军赶到反攻，缪拉骑兵冲垮奥军炮兵阵地，奥军溃退，梅拉斯负伤后同意停战。",impact:"此役使法国保住意大利北部，直接促成1801年吕内维尔和约与1802年亚眠和约，并巩固拿破仑作为第一执政的个人威望。",figures:["拿破仑·波拿巴","梅拉斯","路易·德赛","若阿基姆·缪拉","安德烈·马塞纳"],place:"意大利皮埃蒙特马伦哥（今斯皮诺莱马里奥附近）",state:"法兰西第一共和国／奥地利",sources:["钱乘旦主编《世界现代化历程·西欧卷》","David Bell, The First Total War (2007)"],tags:["反法同盟","战役","拿破仑"]},related:[]},
  {id:"world--1800--m02",track:"world",year:1800,yearApprox:false,dim:"military",weight:3,title:"霍恩林登战役",summary:"莫罗率法军在巴伐利亚雪夜大破奥军，逼奥地利求和。",detail:{background:"1800年春法国与奥地利在德意志战场对峙，拿破仑计划由莫罗与麦克唐纳两路钳击蒂罗尔方向的奥军。",process:"12月3日夜，莫罗率莱茵军团在慕尼黑东南霍恩林登林地雪道中遭遇约翰大公指挥的奥军。法军利用林间空隙分纵队穿插、以白刃突击，奥军纵队互相阻塞而崩溃，法军缴获火炮数十门。",impact:"此役与马伦哥共同摧毁奥地利继续作战的能力，直接导致1801年吕内维尔和约，神圣罗马帝国在莱茵左岸的支配权让与法国。",figures:["让-维克多·莫罗","奥地利约翰大公"],place:"巴伐利亚霍恩林登（今德国上巴伐利亚）",state:"法兰西第一共和国／奥地利",sources:["The Cambridge History of the Napoleonic Wars","David Chandler, The Campaigns of Napoleon (1966)"],tags:["反法同盟","战役"]},related:["world--1800--m01"]},
  {id:"world--1800--s01",track:"world",year:1800,yearApprox:false,dim:"science",weight:5,title:"伏打发明电堆",summary:"伏打制成首个可持续供电的化学电池，开启电化学研究。",detail:{background:"受伽伐尼1791年动物电实验启发，伏打经多年金属接触电研究，认为电来源于异种金属与湿介质的化学作用而非生物电。",process:"1800年3月20日伏打在致英国皇家学会秘书班克斯的信中公布装置：以锌片与银片（后改用铜）相叠、夹以盐水浸湿的纸板串联成柱，即伏打电堆。该装置可提供稳定连续电流，并被用于分解水与多种盐类。",impact:"电堆使持续电流首次可得，直接催生电解化学（戴维1807至1808年分离碱金属）、电磁学（奥斯特1820年、法拉第1831年）与电化学工业，是现代电池技术的起点。",figures:["亚历山德罗·伏打","约瑟夫·班克斯","路易吉·伽伐尼"],place:"意大利科莫（信函寄往英国伦敦）",state:"拿破仑治下的北意大利／英国",sources:["《技术史》（A History of Technology，辛格等主编，牛津）","Iwan Rhys Morus, Electricity: A Very Short Introduction (2020)"],tags:["电化学","发明","电气"]},related:["world--1800--s02"]},
  {id:"world--1800--s02",track:"world",year:1800,yearApprox:false,dim:"science",weight:3,title:"哈特利测定导体电阻规律",summary:"哈特利测出电阻随导体长度与截面变化，为欧姆定律铺路。",detail:{background:"伏打电堆公布后，欧洲各实验室竞相测量不同导体的导电性能。",process:"1800年，英国教士埃德蒙·哈特利把铜、铁、铅丝与碳棒串入电堆电路，记录导体长度增加时电流减弱、截面积增大使导电增强的定量关系，并注意到温度对碳与金属导电方向的相反影响。",impact:"哈特利的观测构成欧姆1827年定律与电阻概念的前驱，使电路从定性演示转为可测量对象，是电学工程化的早期一步。",figures:["埃德蒙·哈特利","格奥尔格·欧姆"],place:"英国",state:"英国",sources:["J. L. Heilbron (ed.), The Oxford Companion to the History of Modern Physics (2003)","The Cambridge History of Science, Vol. 5"],tags:["电学","测量","欧姆定律"]},related:["world--1800--s01"]},
  {id:"world--1800--e01",track:"world",year:1800,yearApprox:false,dim:"economy",weight:3,title:"欧文接管新拉纳克",summary:"欧文接办苏格兰棉纺村，试验改良劳动与幼儿教育的工厂社区。",detail:{background:"新拉纳克是克莱德河畔由阿克莱特体系建立的棉纺村，因合伙人继承而管理失序，童工与酗酒问题严重。",process:"1800年1月，罗伯特·欧文成为新拉纳克纱厂合伙人兼经理，随后缩短工时、拒雇十岁以下童工、设立幼儿学校与夜校、以村中商店低价供应日用品，并推行劳动记分制以调整工序分工。",impact:"新拉纳克成为空想社会主义试验与近代企业管理、职业教育、工厂福利制度的样板，吸引欧洲各国参观者，也为英国工厂法与合作社运动提供了舆论基础。",figures:["罗伯特·欧文"],place:"苏格兰拉纳克郡新拉纳克",state:"英国",sources:["罗伯特·欧文《新社会观》(1813)","E. P. Thompson, The Making of the English Working Class (1963)"],tags:["工厂制","空想社会主义","劳动"]},related:[]},
  {id:"world--1800--p01",track:"world",year:1800,yearApprox:false,dim:"politics",weight:4,title:"英爱合并法通过",summary:"英爱两地议会通过合并法案，次年元旦成立联合王国。",detail:{background:"1798年联合爱尔兰人起义被镇压后，皮特政府决定取消爱尔兰议会，把爱尔兰并入威斯敏斯特以稳固后方。",process:"1800年7月2日与8月1日，英国议会与爱尔兰议会先后通过《合并法案》（39 & 40 Geo. III c.67），规定自1801年1月1日起两国合并，爱尔兰在上院保留32名贵族、在下院占100席，两地自由贸易并统一关税；随附的天主教解放条款因国王反对而被搁置。",impact:"合并结束了1782年以来爱尔兰的立法独立，把爱尔兰问题长期绑定于威斯敏斯特政治；天主教解放议题被推迟，成为1829年危机的直接源头。",figures:["小威廉·皮特","康登勋爵"],place:"英国伦敦／爱尔兰都柏林",state:"大不列颠（1801年后为大不列颠及爱尔兰联合王国）",sources:["Parliamentary History of the UK: Act of Union 1800 (39 & 40 Geo. III c.67)","R. F. Foster (ed.), The Oxford History of Ireland"],tags:["议会","合并","爱尔兰"]},related:["world--1829--p01"]},
  {id:"world--1801--p01",track:"world",year:1801,yearApprox:false,dim:"politics",weight:3,title:"吕内维尔和约",summary:"奥地利承认法国据有莱茵左岸与意大利北部的既成格局。",detail:{background:"马伦哥与霍恩林登两役后奥地利军事崩溃，英国在欧洲大陆失去伙伴，被迫单独谈判。",process:"1801年2月9日，法国（约瑟夫·波拿巴、霍托维茨）与奥地利（科本茨尔）在吕内维尔签字：和约确认利古尔、阿尔卑斯山南、巴达维亚等法国体系内的共和国，奥地利让出莱茵河左岸，并同意在帝国内以世俗化土地补偿丧失莱茵属地的诸邦。",impact:"和约把革命战争成果写成条约文本，并预告了1803年帝国大规模世俗化；同年8月法国与奥斯曼议和、10月与巴达维亚等签约，第二次反法同盟完全解体。",figures:["拿破仑·波拿巴","科本茨尔","约瑟夫·波拿巴"],place:"洛林吕内维尔",state:"法兰西第一共和国／奥地利",sources:["《近代国际条约集》","The Cambridge History of the Napoleonic Wars"],tags:["和约","外交","反法同盟"]},related:["world--1800--m01"]},
  {id:"world--1801--i01",track:"world",year:1801,yearApprox:false,dim:"institution",weight:4,title:"法国政教协定签订",summary:"拿破仑与庇护七世协定，重建天主教会但置于国家管理之下。",detail:{background:"革命期教会财产被没收、教士因宣誓而分裂、信仰实践几近崩溃，拿破仑认为需要以宗教重建社会秩序并把教会置于国家控制之下。",process:"1801年7月15日拿破仑与教宗庇护七世的特使在巴黎签约，1802年4月随附《组织条款》生效：天主教被定义为法国绝大多数公民的宗教而非国教，教宗认可主教与教区重新划界，执政府提名主教、教宗授予神权，教士薪俸由国家负担，教会不得追回革命中已出售的教产。",impact:"协定结束法国十年的宗教分裂，把教会改造为受国家监督的机构，这一政教模式延续至1905年政教分离法；同时为拿破仑1804年加冕提供了宗教合法性渠道。",figures:["拿破仑·波拿巴","庇护七世","约瑟夫·富歇"],place:"法国巴黎",state:"法兰西第一共和国／教宗国",sources:["《1801年政教协定》原文（法国国家档案馆）","J. M. Roberts, Napoleon: A Life (2014)"],tags:["政教关系","天主教会","拿破仑"]},related:[]},
  {id:"world--1801--m01",track:"world",year:1801,yearApprox:false,dim:"military",weight:3,title:"哥本哈根海战",summary:"纳尔逊率英舰队突袭丹麦舰队，瓦解第二次武装中立同盟。",detail:{background:"第二次武装中立同盟（俄、丹、瑞典、普）主张中立船只不受英国拦截检查，威胁英国的水手与木材补给线。",process:"1801年4月2日，海德·帕克上将与纳尔逊率英舰队进入厄勒海峡，以绕渡浅滩、分纵队近战的战术猛攻停泊于哥本哈根外侧的丹麦-挪威分舰队，击沉或缴获其舰只十余艘；5月英俄达成谅解，丹麦于7月退出同盟。",impact:"此役以武力确认了英国的海上检查权与北海制海权，为此后特拉法加时代的长期制海奠定基础；英军此役以火船与纵火艇配合近战。",figures:["霍雷肖·纳尔逊","海德·帕克","斯托达特"],place:"丹麦哥本哈根外海",state:"英国／丹麦-挪威",sources:["Christopher Hibbert, Nelson: A Personal History (1994)","《海权对历史的影响1660—1833》马汉（中译本）"],tags:["海战","制海权","中立同盟"]},related:["world--1805--m01"]},
  {id:"world--1801--s01",track:"world",year:1801,yearApprox:false,dim:"science",weight:3,title:"托马斯·杨提出光的干涉原理",summary:"杨以双缝实验论证光的波动性与干涉条纹。",detail:{background:"牛顿的微粒说在英国学界占支配地位，杨试图以实验重建惠更斯式的波动说。",process:"1801年前后，托马斯·杨在伦敦皇家学会讲座中演示单孔与双缝投影实验，观察到明暗相间的条纹，提出光是以太中的横向振动、重叠时产生相加或相消干涉，并据条纹间距推算可见光波长量级（约十万分之一点二英寸级）。",impact:"干涉与波长概念为菲涅耳1810至1820年代的波动光学、1819年偏振横波说以及后来的波粒二象性讨论提供了原始论证；杨同时提出三原色说与杨氏模量概念。",figures:["托马斯·杨","艾萨克·牛顿","奥古斯丁·菲涅耳"],place:"英国伦敦",state:"英国",sources:["Thomas Young, Course of Lectures on Natural Philosophy (1807)","The Cambridge History of Science, Vol. 5"],tags:["光学","波动说","实验"]},related:[]},
  {id:"world--1802--p01",track:"world",year:1802,yearApprox:false,dim:"politics",weight:5,title:"亚眠和约",summary:"英法西巴四国签约，暂时终结1792年以来的欧战。",detail:{background:"1801年法国先后与奥地利、奥斯曼、俄国达成和解后，英国财政、粮食与海军兵员压力上升，小皮特政府接受法国提出的和谈。",process:"1802年3月25日至27日（芽月6日），法国（约瑟夫·波拿巴、马尔布瓦）、英国（康沃利斯侯爵）、西班牙与巴达维亚共和国代表在亚眠签字：英国归还大部分法属殖民地占领地（保留特立尼达与锡兰），承诺撤出马耳他并交予医院骑士团，法国则不再向亚得里亚海与意大利之外扩张。",impact:"和约是1792至1815年间唯一一次全欧停战，但波兰、德意志与马耳他三项悬案未决，和平仅维持十三个月；1803年5月英国宣战，战争转为以遏制拿破仑个人权力为目标的长期对抗。",figures:["拿破仑·波拿巴","康沃利斯侯爵","小威廉·皮特","巴尔贝-马尔布瓦"],place:"法国亚眠",state:"法兰西第一共和国／英国／西班牙",sources:["《近代国际条约集》","The Cambridge History of the Napoleonic Wars"],tags:["和约","外交","反法同盟"]},related:["world--1803--p02"]},
  {id:"world--1802--i01",track:"world",year:1802,yearApprox:false,dim:"institution",weight:3,title:"荣誉军团勋章设立",summary:"拿破仑设荣誉军团，以国家功绩勋赏取代旧王室等级。",detail:{background:"旧制度下的圣路易勋章等随革命废除，拿破仑需要一个向各阶层开放、并把忠诚绑定于个人政权的奖励体系；该提案在议会遭遇「这是对平等的侮辱」的批评。",process:"1802年5月19日（获月29日）通过组织法：荣誉军团分大鹰官、大军官、指挥官、军官、军团团员五级，设十五个团籍单位，文武官员与士兵依功绩入选，高级成员领取固定薪俸并附设特别学校，女性原则上不获授勋。",impact:"荣誉军团成为近代国家功勋制度的原型之一，被欧洲多国仿效；它与1808年帝国的贵族称号衔接为一套功绩化等级，进一步削弱了出身特权在法律上的地位。",figures:["拿破仑·波拿巴","康巴塞雷斯"],place:"法国巴黎",state:"法兰西第一共和国",sources:["1802年5月19日荣誉军团组织法（获月29日法律）","《拿破仑书信集》"],tags:["勋赏","制度","平等"]},related:["world--1804--i01"]},
  {id:"world--1802--p02",track:"world",year:1802,yearApprox:false,dim:"politics",weight:4,title:"法国恢复殖民地奴隶制",summary:"牧月法令重设蓄奴与奴隶贸易，触发海地全面战争。",detail:{background:"国民公会1794年2月废除殖民地奴隶制，海地革命期间图桑·卢维杜尔实际掌握全岛并以强制劳动维持种植园生产。",process:"1802年5月20日（牧月30日）法令正式恢复1789年之前法属殖民地的奴隶制与奴隶贸易，并剥夺有色自由人的既有权利；同期勒克莱尔率远征军抵海地，6月解除图桑部属武装并将其逮捕押往法国，法军恢复鞭刑与强制劳动制度。",impact:"恢复奴役的决定把圣多明各战争性质从「恢复秩序」转为反殖民独立战争，法军因黄热病与游击战损失惨重，1803年11月凡泰里耶战役后法军投降，1804年1月1日海地宣布独立。",figures:["拿破仑·波拿巴","夏尔·勒克莱尔","图桑·卢维杜尔"],place:"法属圣多明各（今海地）／法国巴黎",state:"法兰西第一共和国",sources:["1802年5月20日（牧月30日）法令（法国国家档案馆）","C. L. R. James, The Black Jacobins (1938)"],tags:["殖民","奴隶制","海地革命"]},related:["world--1804--p01"]},
  {id:"world--1802--m01",track:"world",year:1802,yearApprox:false,dim:"military",weight:3,title:"法军远征圣多明各",summary:"勒克莱尔率军登陆海地，试图以武力重建种植园统治。",detail:{background:"1801年图桑颁布宪法统一全岛并就任终身总督，拿破仑意在借和约后的海运窗口恢复糖业生产与政治控制。",process:"1801年12月至1802年2月，勒克莱尔率约两批共二万余人的船团在法兰西角等地登陆，先以政治分化诱使图桑部属缴械，6月以会谈名义逮捕图桑并押送法国；同年秋法军北上平定后南下围攻山区，至1802年夏末因黄热病减员近万人以上。",impact:"远征失败使法国放弃重建北美殖民体系，直接促成1803年出售路易斯安那；海地的胜利也鼓舞了西属美洲与巴西的独立预期。",figures:["夏尔·勒克莱尔","图桑·卢维杜尔","让-雅克·德萨林","亨利·克里斯托夫"],place:"法属圣多明各",state:"法兰西第一共和国",sources:["Laurent Dubois, Avengers of the New World (2004)","《剑桥拉丁美洲史》卷三"],tags:["远征","殖民战争","海地"]},related:["world--1803--p01"]},
  {id:"world--1802--c01",track:"world",year:1802,yearApprox:false,dim:"culture",weight:3,title:"《基督教真谛》出版",summary:"夏多布里昂以情感与美学论证宗教，影响浪漫主义走向。",detail:{background:"大革命关闭教堂、崇拜理性的尝试失败后，拿破仑寻求以宗教重建秩序；夏多布里昂流亡英国归来后整理旧稿。",process:"1802年4月《基督教真谛》在巴黎出版，分《错误与原因》《战争与和平的宗教》《教义》《德行》《天才》五部分，主张以遗迹、礼仪与情感经验论证基督教之美与历史功用，并附带《阿达拉》《勒内》两篇插曲小说。",impact:"该书成为法国浪漫主义与保守宗教论述的标志文本，为复辟时期与19世纪天主教复兴提供了修辞模式，也确立了作家作为政治力量介入公共生活的文化地位。",figures:["弗朗索瓦-勒内·德·夏多布里昂","拿破仑·波拿巴"],place:"法国巴黎",state:"法兰西第一共和国",sources:["夏多布里昂《基督教真谛》中译本","The Cambridge History of French Literature"],tags:["浪漫主义","宗教思想","文学"]},related:["world--1801--i01"]},
  {id:"world--1803--p01",track:"world",year:1803,yearApprox:false,dim:"politics",weight:3,title:"图桑·卢维杜尔死于囚禁",summary:"海地革命领袖在法国堡垒中去世，成为废奴运动象征。",detail:{background:"1802年6月勒克莱尔以会谈名义逮捕图桑，将其押送至法国，经马赛转至阿尔普杜阿的茹城堡单独关押。",process:"1803年4月7日，图桑在缺乏取暖、口粮受限的牢房中去世，遗体被置于牛舍之外，未获葬礼；同年11月18至19日法军在凡泰里耶战败投降，德萨林成为独立运动最高领导人。",impact:"图桑之死使圣多明各战争被普遍理解为反殖民事件而非内战平定，其形象成为19世纪废奴运动与黑人解放叙事的核心象征。",figures:["图桑·卢维杜尔","夏尔·勒克莱尔","拿破仑·波拿巴"],place:"法国茹城堡（阿尔普杜阿）",state:"法兰西第一共和国",sources:["C. L. R. James, The Black Jacobins (1938)","Madison Smartt Bell, Toussaint Louverture (2007)"],tags:["海地革命","人物","废奴"]},related:["world--1804--p01"]},
  {id:"world--1803--p02",track:"world",year:1803,yearApprox:false,dim:"politics",weight:5,title:"路易斯安那购地",summary:"美国以一千五百万美元自法国购得密西西比河流域土地。",detail:{background:"1802年西班牙依约把路易斯安那交还法国后，新奥尔良通航权成为美国西部农户命脉；杰斐逊派门罗赴法愿出价购新奥尔良，而拿破仑因远征海地失利、对英战争迫近而急于套现。",process:"1803年4月30日，巴尔贝-马尔布瓦与利文斯顿、门罗签订购地条约，美国支付1500万美元并另行承担1125万美元对美国公民的债务，取得约214万平方公里法属路易斯安那；10月20日参议院批准，1804年3月10日新奥尔良正式移交。",impact:"购地使美国国土近乎倍增、移除密西西比河流域的欧洲强权，同时耗尽拿破仑的战争财政；其「宪法是否允许取得新领土」的争议扩大了联邦隐含权力的解释，并把奴隶制向西部扩张的问题推到台前。",figures:["托马斯·杰斐逊","詹姆斯·门罗","拿破仑·波拿巴","巴尔贝-马尔布瓦"],place:"法国巴黎／美国新奥尔良",state:"美国／法兰西第一共和国",sources:["《合众国法律总汇编》第8卷（购地条约）","《剑桥美国对外关系史》"],tags:["领土","外交","美国扩张"]},related:["world--1802--m01"]},
  {id:"world--1803--p03",track:"world",year:1803,yearApprox:false,dim:"politics",weight:4,title:"帝国内世俗化总决议",summary:"帝国代表会议以世俗化土地补偿诸邦，教会领地几乎被清空。",detail:{background:"吕内维尔和约承诺以帝国内土地补偿丧失莱茵左岸属地的德意志诸邦，法国与俄国共同指定补偿方案。",process:"1803年2月25日神圣罗马帝国批准《帝国代表会议总决议》：除三个教会选侯外，绝大多数教会领地、数百座修道院与四十余自由市被世俗化并转给普鲁士、巴伐利亚、符腾堡、巴登等中等邦，选侯团结构由此改为新教占优。",impact:"决议终结了帝国政体的教会基础，把德意志的碎片格局压缩为数十个较大邦国，为1806年莱茵联邦与帝国解体铺路；大量修道院抄本与教会档案在此过程中散佚。",figures:["卡尔·冯·达尔贝格","拿破仑·波拿巴"],place:"雷根斯堡（帝国议会）",state:"神圣罗马帝国",sources:["《帝国代表会议总决议》（1803年2月25日）文本","Thomas Nipperdey, Germany from Napoleon to Bismarck (1996)"],tags:["世俗化","德意志","帝国"]},related:["world--1806--p02"]},
  {id:"world--1803--m01",track:"world",year:1803,yearApprox:false,dim:"military",weight:3,title:"阿赛战役与第二次马拉塔战争",summary:"威尔斯利在德干击败马拉塔军，英国确立印度中部霸权。",detail:{background:"东印度公司自1798年起以辅助金制度与英国驻军逐步渗透印度诸邦，1803年与辛迪亚、薄斯来为首的马拉塔邦联爆发第二次战争。",process:"1803年9月23日，阿瑟·韦尔斯利率约4500人在朱拉河畔阿赛强渡并突击辛迪亚与法国教官训练的数万马拉塔军，虽己方伤亡近1500人但夺占阵地；11月阿贡、拉斯瓦里等役续胜，12月17日《瓦宗加姆劳条约》迫使辛迪亚割地并接受英国驻扎官。",impact:"战后马拉塔邦联丧失独立外交与建军能力，公司领土与岁入大增，法国军事教官被逐出印度诸邦；印度由此进入公司单极扩张时期，直至1857年起义。",figures:["阿瑟·韦尔斯利","达道吉·辛迪亚"],place:"印度德干朱拉河畔阿赛",state:"英国东印度公司／马拉塔邦联",sources:["《剑桥印度史》","The Oxford History of the British Empire（斯特恩主编）"],tags:["殖民征服","印度","战役"]},related:["world--1857--m01"]},
  {id:"world--1803--s01",track:"world",year:1803,yearApprox:false,dim:"science",weight:4,title:"道尔顿列出首张原子量表",summary:"道尔顿以化合重量比例推定元素相对原子量，创立近代原子论。",detail:{background:"拉瓦锡的元素表、气体溶解实验以及普鲁斯特定比定律之争为道尔顿提供了问题框架。",process:"1803年9至10月间，约翰·道尔顿在曼彻斯特文学与哲学学会的笔记中首次列出相对原子量表，以氢为1，据碳、氧、氮等的化合重量推定化合物组成（并把水的组成误定为HO），提出同种元素原子等重、化合物按简单整数比构成的假说；论文1805年刊出。",impact:"原子量与倍比定律使化学计量成为可计算体系，构成19世纪化学式、当量概念与1860年卡尔斯鲁厄会议后原子—分子论确立的起点。",figures:["约翰·道尔顿","安托万·拉瓦锡","约瑟夫·路易·普鲁斯特"],place:"英国曼彻斯特",state:"英国",sources:["John Dalton, A New System of Chemical Philosophy (1808)","Lawrence Principe, The Ascent of Chemistry (2013)"],tags:["原子论","化学计量"]},related:["world--1808--s01"]},
  {id:"world--1803--s02",track:"world",year:1803,yearApprox:false,dim:"science",weight:3,title:"富尔顿在塞纳河试验汽船",summary:"富尔顿明轮蒸汽船在巴黎试验成功片刻后因漏水中沉。",detail:{background:"菲奇、拉姆齐等美国先行者已试蒸汽船，富尔顿结合博尔顿-瓦特蒸汽机与明轮推进，并向法方提出渡海入侵运输方案。",process:"1803年8月，罗伯特·富尔顿所造单桅明轮蒸汽船在巴黎塞纳河顺流航行约半小时，因船体接缝开裂进水而沉没，试验当场失败；他此前已在英国取得相关专利并试制潜艇「蜥蜴号」。",impact:"试验虽败，却促使富尔顿转向商业条件更有利的美国，最终在1807年完成哈德逊河定期航行；蒸汽航运从河道向远洋扩散的路线由此确定。",figures:["罗伯特·富尔顿","拿破仑·波拿巴"],place:"法国巴黎塞纳河",state:"法兰西第一共和国",sources:["H. W. Dickinson, Robert Fulton and the Steamboat (1913)","《技术史》（辛格等主编）"],tags:["蒸汽船","发明","试验"]},related:["world--1807--s01"]},
  {id:"world--1804--p01",track:"world",year:1804,yearApprox:false,dim:"politics",weight:5,title:"海地宣布独立",summary:"德萨林元旦宣告脱离法国，建立拉美第一个独立共和国。",detail:{background:"1803年11月18至19日凡泰里耶战役后，罗尚博率剩余法军投降；远征军累计约五万余人损失于战斗与黄热病，德萨林在克里斯托夫、佩蒂翁之上掌握军政。",process:"1804年1月1日，让-雅克·德萨林在戈奈耶尔宣读独立宣言，取泰诺语旧名定国号为海地，宣布全岛永久废除奴隶制、禁止外国人取得土地；2月起对残留白人居民发出屠杀令并延续数月，1804年与1805年宪法确立其终身统治（1804年9月称帝）。",impact:"海地是拉美第一次成功的奴隶革命与独立建国，也是首个以黑人为主体的共和国；列强长期拒绝承认，法国1825年以1.5亿法郎（后减为9000万）赔款换承认，该债务沉重影响海地财政逾百年。",figures:["让-雅克·德萨林","亨利·克里斯托夫","亚历山大·佩蒂翁"],place:"海地戈奈耶尔",state:"海地（原法属圣多明各）",sources:["《海地独立宣言》（1804年1月1日）原文","Laurent Dubois, Avengers of the New World (2004)"],tags:["独立","废奴","殖民"]},related:["world--1802--p02"]},
  {id:"world--1804--i01",track:"world",year:1804,yearApprox:false,dim:"institution",weight:5,title:"法国民法典颁布",summary:"统一私法体系确立财产权与契约自由，并强化夫权家庭。",detail:{background:"革命时期多次编纂民法典的方案均未完成，1800年8月拿破仑任命特龙谢、波塔利斯、比戈-德-普雷亚梅讷、马勒维尔四人起草，执政府时期由参政院逐条审议。",process:"1804年3月21日公布《法国民法典》（1807年起称拿破仑法典），含序题与三编共2281条：确认法律面前平等、废除封建义务与长子继承、所有权绝对、契约须有约因且不得侵害第三人；同时规定妻处于夫的管辖之下、妻财产权与行为能力受限，雇工契约与劳动者结社受严格限制。",impact:"法典成为大陆法系的原型，随拿破仑战争传入意大利、莱茵联邦、荷兰、波兰与西班牙部分地区，并经比利时、魁北克、路易斯安那、日本等继受；其家庭与劳动条款直至19世纪末与20世纪才被陆续修改。",figures:["拿破仑·波拿巴","康巴塞雷斯","波塔利斯","特龙谢"],place:"法国巴黎",state:"法兰西第一共和国",sources:["《法国民法典》1804年通行本","《比较法总论》茨威格特、克茨（中译本）"],tags:["法典","大陆法系","财产"]},related:["world--1804--p02"]},
  {id:"world--1804--p02",track:"world",year:1804,yearApprox:false,dim:"politics",weight:4,title:"拿破仑加冕称帝",summary:"教宗到场而皇帝自取冠冕，共和体制转为世袭帝国。",detail:{background:"雾月政变后拿破仑连续以公民投票为权力背书；1804年王党暗杀阴谋与处决当甘亲王为其称帝提供口实。",process:"1804年5月18日参议院元老院咨文宣布共和国政府交由世袭皇帝；11月6日公民投票以约357万赞成对2569反对批准帝制；12月2日在巴黎圣母院举行典礼，庇护七世到场，拿破仑自取冠冕加于己首，随后为皇后约瑟芬加冕，以军乐与礼炮掩盖部分教会礼仪。",impact:"加冕把革命的功绩原则与王朝合法性焊接起来，形成以勋章、法典与常备军支撑的新王朝国家；同年欧陆局势因汉诺威、意大利与瑞士问题再度紧张，第三次反法同盟在酝酿中成形。",figures:["拿破仑一世","庇护七世","约瑟芬"],place:"法国巴黎圣母院",state:"法兰西第一帝国",sources:["《拿破仑书信集》","乔治·勒费弗尔《拿破仑时代》（中译本）"],tags:["加冕","帝制","公民投票"]},related:["world--1805--m03"]},
  {id:"world--1804--s01",track:"world",year:1804,yearApprox:false,dim:"science",weight:4,title:"特里维西克蒸汽机车首次牵引",summary:"高压蒸汽机车在威尔士铁轨上完成首次载重牵引。",detail:{background:"瓦特对高压蒸汽持保留意见并诉诸专利限制，特里维西克改用膨胀做功的高压蒸汽机以提高功率重量比。",process:"1804年2月21日，理查德·特里维西克所造蒸汽机车在威尔士梅瑟蒂德菲尔的佩尼达伦铁轨上牵引约10吨铁与70名工人、行驶约5英里、耗时约5小时，平均时速约5公里；其1803年造的高压固定蒸汽机已在该地铁厂投产。",impact:"此次牵引被视为铁路机车运输的起点，但铸铁轨无法长期承受机车重量而一度受挫；其后齿轨与锻铁轨的改进为1825年斯托克顿—达灵顿公共铁路铺路。",figures:["理查德·特里维西克"],place:"威尔士梅瑟蒂德菲尔佩尼达伦",state:"英国",sources:["《技术史》（辛格等主编）","Sidney Pollard, Peaceful Conquest: Industrial Europe 1790–1850 (1981)"],tags:["蒸汽机","铁路","发明"]},related:["world--1825--e01"]},
  {id:"world--1804--p03",track:"world",year:1804,yearApprox:false,dim:"politics",weight:3,title:"第一次塞尔维亚起义",summary:"起义者攻取贝尔格莱德，开启巴尔干民族自治进程。",detail:{background:"奥斯曼中央权威在耶尼切里叛乱后崩溃，贝尔格莱德桑贾克由叛乱的达希亚军团实行地方暴政，1804年初屠杀塞尔维亚族老。",process:"1804年2月中旬，舒马贾地区武装在卡拉乔尔杰·彼得罗维奇领导下起义，10月包围并攻入贝尔格莱德；1806至1813年间两度与素丹朝廷谈判获自治承诺并事实上自行征税建军，1813年被镇压，1815年第二次起义再起。",impact:"起义使塞尔维亚成为奥斯曼帝国境内第一个取得事实自治的基督教省份，1817年米洛什·奥布雷诺维奇建立公国，1830与1833年素丹诏书确认自治，1878年柏林条约承认其完全独立。",figures:["卡拉乔尔杰·彼得罗维奇","米洛什·奥布雷诺维奇"],place:"贝尔格莱德桑贾克（今塞尔维亚中部）",state:"奥斯曼帝国（塞尔维亚起义者）",sources:["《剑桥巴尔干史》","L. S. Stavrianos, The Balkans since 1453 (1958)"],tags:["民族主义","奥斯曼","起义"]},related:["world--1821--p01"]},
  {id:"world--1805--p01",track:"world",year:1805,yearApprox:false,dim:"politics",weight:3,title:"第三次反法同盟结成",summary:"英俄缔约后奥地利、瑞典加入，欧洲再度对法合围。",detail:{background:"亚眠和约破裂后英国于1803年5月宣战，拿破仑占领汉诺威、扣押英籍侨民，俄皇亚历山大一世由妥协转向抗法。",process:"1805年4月11日英国与俄国在圣彼得堡签订同盟公约，以恢复欧洲均势与意大利秩序为目标；8月9日奥地利对法宣战，瑞典与西西里随后加入，普鲁士在11月《波茨坦秘密协定》后短暂倒向法国一方。",impact:"同盟虽在乌尔姆与奥斯特里茨被各个击破，但英国凭财政与海军持续组织反法战争，形成以补贴换取大陆兵源的联盟模式，该模式延续至1815年。",figures:["拿破仑一世","亚历山大一世","小威廉·皮特"],place:"圣彼得堡／英国伦敦",state:"英国／俄国／奥地利",sources:["《近代国际条约集》","The Cambridge History of the Napoleonic Wars"],tags:["同盟","外交","反法同盟"]},related:["world--1805--m03"]},
  {id:"world--1805--m01",track:"world",year:1805,yearApprox:false,dim:"military",weight:5,title:"特拉法加海战",summary:"纳尔逊击溃法西联合舰队，英国确立长期海上绝对优势。",detail:{background:"拿破仑为掩护布洛涅大军渡海侵英，命维尔纳夫舰队自西印度返航与西班牙舰队会合，但因信号混乱与训练差距而部署散乱。",process:"1805年10月21日在加的斯西南外海，纳尔逊率27艘战列舰以两个纵列垂直切断维尔纳夫指挥的33艘法西联合舰队，攻击其中央与后卫并围攻旗舰；法西方面损失22艘、死伤与被俘约4400人，英军无一舰被俘但阵亡449人、伤1214人，纳尔逊在「胜利号」上被狙击阵亡。",impact:"此役永久终结了法国以武力侵英与重建海外殖民帝国的可能，迫使拿破仑转向大陆封锁；英国海权的不可挑战地位维持至20世纪初，为其殖民扩张与金本位贸易网提供安全条件。",figures:["霍雷肖·纳尔逊","皮埃尔·维尔纳夫","弗雷德里克·柯林伍德"],place:"西班牙特拉法加角附近海面",state:"英国／法兰西第一帝国／西班牙",sources:["《纳尔逊通信与公文集》（尼古拉斯编）","Christopher Hibbert, Nelson: A Personal History (1994)"],tags:["海战","制海权","拿破仑战争"]},related:["world--1801--m01"]},
  {id:"world--1805--m02",track:"world",year:1805,yearApprox:false,dim:"military",weight:3,title:"乌尔姆战役奥军投降",summary:"拿破仑机动包围歼灭麦克军团，未攻坚而克乌尔姆。",detail:{background:"奥军先在意大利与蒂罗尔分兵，拿破仑判断其集结尚未完成即抢先渡过多瑙河上游。",process:"1805年9月底至10月20日，大军团自布洛涅疾行进入巴伐利亚，在维瑟尔堡、兰多、埃尔兴根、内伦贝格、哈斯拉赫-容金根连续取胜，把卡尔·马克军团压缩于乌尔姆；10月20日马克率约2.7至3万人投降，法军缴获火炮60余门。",impact:"乌尔姆使11月13日进入维也纳与12月的奥斯特里茨决战成为可能，并促成巴伐利亚倒向法国；普鲁士在犹豫中错失干预窗口，随后被迫接受法国在德意志的安排。",figures:["拿破仑一世","卡尔·马克·冯·莱贝里希","若阿基姆·缪拉","达武"],place:"巴伐利亚乌尔姆、多瑙沃尔特",state:"法兰西第一帝国／奥地利",sources:["David Chandler, The Campaigns of Napoleon (1966)","The Cambridge History of the Napoleonic Wars"],tags:["机动","投降","战役"]},related:["world--1805--m03"]},
  {id:"world--1805--m03",track:"world",year:1805,yearApprox:false,dim:"military",weight:5,title:"奥斯特里茨战役",summary:"法军中央反击击破俄奥联军，第三次反法同盟瓦解。",detail:{background:"乌尔姆与维也纳陷落后，俄军本拟等待普鲁士与后备兵力，亚历山大一世在进攻派参谋怂恿下选择决战。",process:"1805年12月2日，法军约7.3万对俄奥联军约8.5万，在布尔诺以南奥斯特里茨（今捷克斯拉夫科夫）交战。拿破仑故意示弱右翼诱联军南下分割其阵线，苏尔特第四军上午夺回普拉岑高地切断联军中央，联军向结冰的萨茨班湖与梅尔尼茨湖方向溃退；法军缴大炮130余门，联军死伤与被俘约2.7万，法军损失约9000。",impact:"战役迫使奥地利签订普雷斯堡和约、放弃意大利与蒂罗尔，直接促成神圣罗马帝国解体与莱茵联邦建立，普鲁士临时屈服；1806年第四次同盟很快形成，战争规模与性质进一步升级。",figures:["拿破仑一世","亚历山大一世","弗朗茨二世","库图佐夫","苏尔特"],place:"摩拉维亚奥斯特里茨（今捷克斯拉夫科夫）",state:"法兰西第一帝国／俄国／奥地利",sources:["David Chandler, The Campaigns of Napoleon (1966)","《拿破仑书信集》"],tags:["战役","拿破仑","反法同盟"]},related:["world--1805--p02"]},
  {id:"world--1805--p02",track:"world",year:1805,yearApprox:false,dim:"politics",weight:3,title:"普雷斯堡和约",summary:"奥地利割让意大利与蒂罗尔并付赔款，退出当年战局。",detail:{background:"奥斯特里茨后拿破仑拒绝俄军单独撤退的和谈空间，只与奥地利谈判，奥方急需止损。",process:"1805年12月26日双方在普雷斯堡（今布拉迪斯拉发）签约：奥地利承认拿破仑兼任意大利国王、巴伐利亚与符腾堡升格为王，将威尼斯、达尔马提亚、阿尔巴尼亚属地让与意大利王国，蒂罗尔与福拉尔贝格让与巴伐利亚，赔款4000万法郎，法军限期撤出。",impact:"和约把奥地利逐出意大利与蒂罗尔，使神圣罗马帝国解体几成定局，并扩大法国在中德的附庸体系；奥地利此后以外交避战为国策，梅特涅的主和路线由此定型。",figures:["拿破仑一世","弗朗茨二世","卡尔大公"],place:"摩拉维亚普雷斯堡（今布拉迪斯拉发）",state:"法兰西第一帝国／奥地利",sources:["《近代国际条约集》","A. J. P. Taylor, The Habsburg Monarchy 1815–1918"],tags:["和约","奥地利","领土"]},related:["world--1806--p01"]},
  {id:"world--1806--p01",track:"world",year:1806,yearApprox:false,dim:"politics",weight:3,title:"莱茵联邦成立",summary:"十六邦脱离帝国结成法国保护下的邦联，中德秩序重组。",detail:{background:"普雷斯堡和约后拿破仑拟以中德缓冲带巩固帝国东南边界，巴登与贝格率先移植法典与宪法。",process:"1806年7月12日，巴伐利亚、符腾堡、巴登、黑森-达姆施塔特、拿骚、克莱沃贝格等16邦在巴黎签订联邦条约，宣布脱离神圣罗马帝国并奉拿破仑为保护者；联邦设议会于斯图加特后迁法兰克福，各邦陆续引入民法典、废除农奴制与犹太人格托限制。",impact:"莱茵联邦成为德意志改革与国家现代化的实验场：行政集中、义务教育、统一度量衡与犹太公民权在此先行推进；1815年后被松散的德意志邦联取代，但其改革成果大多被保留下来。",figures:["拿破仑一世","卡尔·冯·达尔贝格"],place:"巴黎／法兰克福、斯图加特",state:"莱茵联邦／法兰西第一帝国",sources:["《莱茵联邦条约》（1806年7月12日）","Thomas Nipperdey, Germany from Napoleon to Bismarck (1996)"],tags:["邦联","德意志改革","法典"]},related:["world--1806--p02"]},
  {id:"world--1806--p02",track:"world",year:1806,yearApprox:false,dim:"politics",weight:5,title:"神圣罗马帝国解体",summary:"弗朗茨二世放弃帝号，延续八百余年的帝国体制终结。",detail:{background:"帝国自1648年威斯特伐利亚和约后已趋空转，1803年世俗化与1805至1806年法国改组抽走了其制度骨架。",process:"1806年7月莱茵联邦成立并通知帝国议会后，8月6日弗朗茨二世以退位诏书宣布放弃神圣罗马帝国皇冠与帝国政府，同时保留其1804年8月11日自立的奥地利皇帝称号；帝国枢密法院、帝国骑士与自由市的法理依托一并消失。",impact:"解体终结了中世纪普世秩序的最后制度残余，德意志问题从此转为「由谁来统一」；1815年维也纳会议只建立主权邦联，1871年的小德方案统一可视为这一问题的最终答案。",figures:["弗朗茨二世","拿破仑一世","梅特涅"],place:"维也纳",state:"奥地利帝国／神圣罗马帝国",sources:["《弗朗茨二世退位诏书》（1806年8月6日）","Thomas Nipperdey, Germany from Napoleon to Bismarck (1996)"],tags:["帝国解体","德意志","宪制"]},related:["world--1871--p01"]},
  {id:"world--1806--m01",track:"world",year:1806,yearApprox:false,dim:"military",weight:4,title:"耶拿-奥尔施泰特战役",summary:"法军一日双役击溃普军主力，普鲁士军事体系崩溃。",detail:{background:"普鲁士1805年持中立，1806年秋因安斯巴赫事件与萨克森动员对法宣战，其指挥与条令仍停留在腓特烈时代。",process:"1806年10月14日，拿破仑在耶拿以南以六个军对阵普鲁士霍恩洛厄军，法军约5.4万人、普军约4万，普军损失约1.3万与百余门炮；同日达武第三军约2.7万在奥尔施泰特击破不伦瑞克公爵亲率的约5万普军主力，不伦瑞克公爵重伤阵亡，达武负伤，普军另损失约1.5万。",impact:"两役使普鲁士在一个月内亡国：10月27日法军进入柏林，11月21日柏林敕令宣布大陆封锁；普鲁士随即启动沙恩霍斯特、洪堡、施泰因主导的军事、行政与教育改革，1813年得以重新参战。",figures:["拿破仑一世","达武","不伦瑞克公爵卡尔·威廉","沙恩霍斯特"],place:"图林根耶拿、奥尔施泰特",state:"法兰西第一帝国／普鲁士",sources:["David Chandler, The Campaigns of Napoleon (1966)","Christopher Clark, Iron Kingdom: The Rise and Fall of Prussia (2006)"],tags:["战役","普鲁士","军事改革"]},related:["world--1806--i01"]},
  {id:"world--1806--i01",track:"world",year:1806,yearApprox:false,dim:"institution",weight:4,title:"柏林敕令宣布大陆封锁",summary:"拿破仑封锁不列颠群岛，把欧陆经济整体纳入战争工具。",detail:{background:"特拉法加后法国无法在英国海上作战，遂转向以贸易战打击英国的财政、市场与信用。",process:"1806年11月21日拿破仑在柏林签署敕令：宣布不列颠群岛处于封锁状态，禁止与英国通邮、通信、通商，境内英国臣民一律视为战俘，凡来自英国殖民地或由英国船只转运的货物均可合法捕获；其后1807年枫丹白露与米兰敕令扩展适用范围，1810年以「生产原产地证书」进一步收紧。",impact:"封锁未能扼死英国，反而催生出大规模走私网络与英国对南欧、美洲市场的重新布局，并激化与俄国、普鲁士、瑞典的矛盾；欧陆糖价、谷物价格波动与1810至1811年粮食危机，成为1812年征俄的重要经济与政治动因。",figures:["拿破仑一世"],place:"普鲁士柏林",state:"法兰西第一帝国",sources:["《柏林敕令》（1806年11月21日）原文","The Cambridge History of the Napoleonic Wars"],tags:["封锁","贸易战","拿破仑"]},related:["world--1812--m01"]},
  {id:"world--1807--p01",track:"world",year:1807,yearApprox:false,dim:"politics",weight:4,title:"蒂尔西特和约",summary:"法俄和解重划欧陆格局，普鲁士失去半数领土。",detail:{background:"弗里德兰（6月14日）与海尔斯贝格之战后俄军受挫，亚历山大一世面临财政与兵员压力而接受和谈。",process:"1807年6月25日两皇在涅曼河上的浮动木筏会晤，7月7日签订法俄和约、7月9日签订法普和约：俄国承认法国在欧陆与波兰的既成安排并加入大陆封锁；普鲁士让出1772与1793年所得波兰土地以及易北河以西全部领土，失去约半数人口；随后由所得土地组建华沙大公国与威斯特伐利亚王国，拿破仑之兄约瑟夫、其弟热罗姆分别就位。",impact:"蒂尔西特体系把欧陆划分为法俄两强的势力范围，也埋下其崩溃的种子：波兰复国期待与大陆封锁的經濟代价，使1812年亚历山大一世背弃条约成为战争导火索。",figures:["拿破仑一世","亚历山大一世"],place:"涅曼河畔蒂尔西特",state:"法兰西第一帝国／俄国／普鲁士",sources:["《近代国际条约集》","The Cambridge History of Russia, Vol. 2（帝国俄国1689–1917）"],tags:["和约","瓜分","大陆封锁"]},related:["world--1812--m01"]},
  {id:"world--1807--e01",track:"world",year:1807,yearApprox:false,dim:"economy",weight:4,title:"英国废除奴隶贸易法",summary:"英国立法终止贩奴航线，并动用海军长期查缉。",detail:{background:"威尔伯福斯等福音派与贵格会自1787年推动议会废奴；1806年部分种植园主担心法属殖民地抢夺市场而转为支持。",process:"1807年3月25日《废除奴隶贸易法案》（47 Geo. III c.51）获得御准，规定自1808年5月1日起帝国臣民不得参与贩奴航运，违者按船只与载奴人数课以重罚并没收船只；英国随后以西非分舰队与混合委员会法院执行查缉，学界估计至1860年代共约十六万名非洲人经此获释安置于弗里敦等地。",impact:"该法首次把国际航道纳入带有普遍主义色彩的规制，形成以海军执法推动多边条约的模式，为此后与各国签订查缉条约奠定基础；但帝国境内的种植园奴隶制延续至1833年废奴法、1834年8月生效。",figures:["威廉·威尔伯福斯","查尔斯·詹姆斯·福克斯","巴瑟斯特勋爵"],place:"英国伦敦",state:"英国",sources:["Parliamentary Papers, Abolition of the Slave Trade Act 1807 (47 Geo. III c.51)","The Cambridge Economic History of Europe"],tags:["废奴","贸易","立法"]},related:["world--1833--e01"]},
  {id:"world--1807--s01",track:"world",year:1807,yearApprox:false,dim:"science",weight:5,title:"克莱蒙特号蒸汽船首航",summary:"富尔顿汽船在哈德逊河完成首次商业性持续航行。",detail:{background:"富尔顿1803年巴黎试验沉没后转赴美国建造，获利文斯顿家族资金与纽约州航运特许权支持。",process:"1807年8月17日，以博尔顿-瓦特直顶式蒸汽机驱动的明轮客船「克莱蒙特」自纽约出发，溯哈德逊河约150英里至奥尔巴尼，耗时约32小时、平均约每小时4.5至5节，同年秋季投入定期航班营运。",impact:"这次航行首次证明蒸汽航运可长期商业运营，此后哈德逊河、密西西比河与英国沿海航线相继开班；1819年萨凡纳号以蒸汽辅助横渡大西洋，远程航运的时间压缩由此成为国际市场与帝国治理的物质条件。",figures:["罗伯特·富尔顿","罗伯特·利文斯顿"],place:"美国纽约至奥尔巴尼（哈德逊河）",state:"美国",sources:["《技术史》（辛格等主编）","H. W. Dickinson, Robert Fulton and the Steamboat (1913)"],tags:["蒸汽船","交通","商业化"]},related:["world--1819--x01"]},
  {id:"world--1807--c01",track:"world",year:1807,yearApprox:false,dim:"culture",weight:4,title:"黑格尔《精神现象学》出版",summary:"以意识诸形态演进论证精神自我认识，重塑欧陆思想。",detail:{background:"黑格尔在耶拿任大学讲师期间完成书稿，出版商在战事逼近时抢先印行，序言为其事后补入。",process:"1807年4月《精神现象学》在班贝格出版，分意识、自我意识、理性、精神、宗教、绝对知识诸章，把主奴辩证、苦恼意识、道德精神与「艺术宗教」写成意识逐步自我认识的过程，全书以绝对知识收束。",impact:"该书成为德国观念论的枢纽文本：主奴辩证经由科耶夫1930年代讲疏影响萨特、梅洛-庞蒂与法农，其历史哲学与异化框架被马克思批判继受，也构成此后欧陆哲学与英美哲学分野的起点之一。",figures:["格奥尔格·威廉·弗里德里希·黑格尔","拿破仑一世"],place:"班贝格／耶拿",state:"普鲁士（德意志诸邦）",sources:["黑格尔《精神现象学》中译本（贺麟、王玖兴译）","Charles Taylor, Hegel (1975)"],tags:["观念论","哲学","异化"]},related:["world--1848--c01"]},
  {id:"world--1807--i01",track:"world",year:1807,yearApprox:false,dim:"institution",weight:3,title:"施泰因十月敕令",summary:"普鲁士废除世臣隶属关系，启动农业与地方自治改革。",detail:{background:"耶拿战败与蒂尔西特和约使普鲁士丧失半数领土与人口，改革派认为必须重建国家与社会之间的纽带。",process:"1807年10月9日首相施泰因签署《关于公民关系与农业经营自由的敕令》：自1810年11月11日起废除农民对领主的世臣身份与人身依附役，允许土地自由买卖与跨邦迁徙，取消骑士地产与农民地产的法律差别，并将地方司法与行政分离、以村镇自治取代领主裁判。",impact:"十月敕令开启普鲁士农业的资本主义化，但随后的《管制与施行令》使容克以「补偿」方式取得农民大片林地与好地，形成东易北河大地产结构，其政治与社会后果延续至1848年革命乃至20世纪。",figures:["卡尔·冯·施泰因","哈登贝格"],place:"普鲁士柯尼斯堡",state:"普鲁士",sources:["《十月敕令》（1807年10月9日）原文","Thomas Nipperdey, Germany from Napoleon to Bismarck (1996)"],tags:["改革","农奴制","普鲁士"]},related:["world--1806--m01"]},
  {id:"world--1808--p01",track:"world",year:1808,yearApprox:false,dim:"politics",weight:3,title:"巴约内逼宫与约瑟夫入西班牙",summary:"拿破仑迫波旁父子退位，把西班牙王位交给其兄。",detail:{background:"法军自1807年经西班牙借道远征葡萄牙，已在潘普洛纳、圣塞瓦斯蒂安等地驻军；西班牙王室与戈多伊的对英摇摆为干预提供口实。",process:"1808年3月阿兰胡埃斯兵变使戈多伊倒台、卡洛斯四世退位、斐迪南七世继位；4月底拿破仑召父子至巴约内，5月5日卡洛斯四世签署转让西班牙王位，6月6日约瑟夫·波拿巴接受王位，7月颁布巴约内宪法，同年秋拿破仑亲赴马德里布置军事。",impact:"废长立幼造成西班牙主权空位，各省以斐迪南七世之名相继成立洪达，半岛战争持续六年、长期牵制法军二十万以上，成为帝国解体的第一道结构性裂口。",figures:["拿破仑一世","约瑟夫·波拿巴","卡洛斯四世","斐迪南七世"],place:"西班牙巴约内／马德里",state:"西班牙／法兰西第一帝国",sources:["Charles Esdaile, The Peninsular War (2002)","《剑桥拉丁美洲史》卷三"],tags:["王位更替","半岛战争","波旁"]},related:["world--1808--m01"]},
  {id:"world--1808--m01",track:"world",year:1808,yearApprox:false,dim:"military",weight:4,title:"马德里五月二日起义",summary:"市民起义遭炮兵镇压，西班牙全境转入游击战争。",detail:{background:"法军占领马德里后由缪拉实行军事管制，并强行转运王室余员出境，社会对「改革式占领」的反感在此爆发。",process:"1808年5月2日，马德里市民袭击法军巡逻与马厩，缪拉以炮兵与骑兵在城中镇压；5月3日凌晨在蒙塔拿破仑山等地成排枪决数百人，戈雅随后绘成《1808年5月2日》与《1808年5月3日》。5月底至7月阿斯图里亚斯、安达卢西亚、瓦伦西亚相继成立洪达并宣战；6月15日至8月14日萨拉戈萨第一次围城以巷战、疫病与火药库爆炸守下。",impact:"起义把拿破仑的王朝安排转为消耗战，正规抵抗与乡村游击并行，游击战一词自此进入欧洲诸语言；英军8月在葡萄牙登陆，半岛战场成为帝国的战略软肋。",figures:["华金·缪拉","弗朗西斯科·戈雅","佩德罗·卡罗","阿戈斯蒂娜·萨拉戈萨"],place:"西班牙马德里、萨拉戈萨",state:"西班牙／法兰西第一帝国",sources:["Charles Esdaile, The Peninsular War (2002)","《剑桥西班牙史》"],tags:["起义","游击战","西班牙"]},related:["world--1812--m03"]},
  {id:"world--1808--m02",track:"world",year:1808,yearApprox:false,dim:"military",weight:3,title:"拜伦：法军首次整军投降",summary:"杜邦军团在安达卢西亚投降，打破法军不可战胜的神话。",detail:{background:"杜邦军团自马德里南下，意在恢复安达卢西亚秩序并接应舰队，但因兵力分散、桥梁被毁而孤军深入。",process:"1808年6月初法军进入科尔多瓦，6月6至7日阿尔科莱亚桥之战后继续南撤；6月19日拉德之战法军受挫，退入拜伦（安杜哈尔附近）被卡斯塔尼奥斯与雷登所率安达卢西亚军队与农民武装四面包围，补给断绝，7月19日签订投降条款，约1.7至1.8万名法军及全部火炮辎重被俘，后被押至卡塔赫纳拘禁。",impact:"这是革命与拿破仑战争中法军首次整建制投降，直接促使拿破仑亲率约8万大军南下；各国据此重估半岛战局，威灵顿的干预获得政治与舆论空间。",figures:["皮埃尔·杜邦","弗朗西斯科·哈维尔·卡斯蒂尼奥斯","红发雷登"],place:"西班牙安达卢西亚拜伦",state:"西班牙／法兰西第一帝国",sources:["Charles Esdaile, The Peninsular War (2002)","The Cambridge History of the Napoleonic Wars"],tags:["战役","半岛战争","投降"]},related:["world--1808--m01"]},
  {id:"world--1808--s01",track:"world",year:1808,yearApprox:false,dim:"science",weight:3,title:"道尔顿《化学哲学新体系》卷一",summary:"以原子论、元素符号与溶解定律重建化学基础叙述。",detail:{background:"自1803年首张原子量表后，道尔顿用十余年补充实验并回应定比与倍比之争。",process:"1808年在曼彻斯特出版《化学哲学新体系》第一部分，系统阐述原子不可分、同种元素原子等重、化合物按简单整数比构成，附自创元素圆点符号与「复杂原子」图式，并给出水的组成推断、倍比定律与气体溶解度随温度变化的处理。",impact:"该书首次把原子论作为可操作的化学理论公之于众，19世纪的化学式、反应方程与1860年卡尔斯鲁厄会议对原子—分子论的确认，皆以这一叙述框架为起点。",figures:["约翰·道尔顿","托马斯·汤姆森"],place:"英国曼彻斯特",state:"英国",sources:["John Dalton, A New System of Chemical Philosophy, Part I (1808)","The Cambridge History of Science, Vol. 5"],tags:["原子论","化学","出版"]},related:["world--1803--s01"]},
  {id:"world--1809--m01",track:"world",year:1809,yearApprox:false,dim:"military",weight:3,title:"阿斯佩恩-埃斯林战役",summary:"法军渡多瑙河后浮桥被毁，被迫退守洛鲍岛。",detail:{background:"第五次反法同盟中卡尔大公自波希米亚南下，拿破仑在雷根斯堡、埃克米尔获胜后追击至维也纳郊外。",process:"1809年5月21至22日，法军在洛鲍岛与阿斯佩恩—埃斯林一线渡过多瑙河与奥军激战；21日夜间洪水与奥军上游炮击冲毁中央桥，法军补给与增援中断，22日晨奥军集中攻击阿斯佩恩村，法军逐屋抵抗后趁夜退回洛鲍岛，双方各损失约2万至2.3万人，让·拉纳元帅22日重伤后数日不治。",impact:"此役是拿破仑亲自指挥的首次重大失败，证明其并非不可战胜，短暂鼓舞了蒂罗尔与北德意志的反法起义；但六周后瓦格拉姆战役使法军重新夺回主动权。",figures:["卡尔大公","拿破仑一世","让·拉纳"],place:"维也纳东北阿斯佩恩—埃斯林",state:"法兰西第一帝国／奥地利",sources:["David Chandler, The Campaigns of Napoleon (1966)","The Cambridge History of the Napoleonic Wars"],tags:["战役","多瑙河","渡河"]},related:["world--1809--m02"]},
  {id:"world--1809--m02",track:"world",year:1809,yearApprox:false,dim:"military",weight:3,title:"瓦格拉姆战役",summary:"法军强渡多瑙河决战击破奥军，第五次同盟终结。",detail:{background:"阿斯佩恩之后拿破仑增调兵力、控制河道并等待马塞纳与贝尔纳多特两军会合。",process:"1809年7月5至6日，法军约19万（含意、巴伐利亚部队）对奥军约13至14万，在维也纳以北洛鲍岛至比萨姆贝格之间决战。5日夜法军在埃斯林下游架桥强渡，6日麦克唐纳中央纵队以方阵突破奥军阵线间隙，达武自右翼包抄奥军左翼，奥军夜间有序撤退；双方合计损失约7万余人。",impact:"战役直接导致10月申布伦和约：奥地利割地、限军十万、加入大陆封锁并失去亚得里亚海海岸，第五次反法同盟瓦解，拿破仑帝国到达最大疆域的顶点。",figures:["拿破仑一世","卡尔大公","马塞纳","达武","贝尔纳多特"],place:"维也纳北郊瓦格拉姆",state:"法兰西第一帝国／奥地利",sources:["David Chandler, The Campaigns of Napoleon (1966)","The Cambridge History of the Napoleonic Wars"],tags:["战役","多瑙河","决战"]},related:["world--1809--p01"]},
  {id:"world--1809--p01",track:"world",year:1809,yearApprox:false,dim:"politics",weight:3,title:"申布伦和约",summary:"奥地利再割地限军，接受大陆封锁并支付赔款。",detail:{background:"瓦格拉姆后奥军无力再战，新任外交大臣梅特涅主持谈判，有意保留与法国合作、伺机再起的余地。",process:"1809年10月14日双方签约：奥地利让出萨尔斯堡与贝希特斯加登给巴伐利亚，克拉尼斯卡、克罗地亚萨瓦河以南并入法国伊利里亚省，塔尔诺波尔归华沙大公国；赔款8500万法郎，军队限为十万，并确认加入大陆封锁体系。",impact:"和约使奥地利被完全纳入封锁体系并失去亚得里亚海出海口，同时确立梅特涅的对法缓和路线：以王朝联姻（1810年拿破仑娶玛丽·路易丝）换取重整时间，为1813年奥地利调停与倒戈定下政策框架。",figures:["拿破仑一世","梅特涅","卡尔大公"],place:"维也纳申布伦",state:"奥地利／法兰西第一帝国",sources:["《近代国际条约集》","A. J. P. Taylor, The Habsburg Monarchy 1815–1918"],tags:["和约","奥地利","大陆封锁"]},related:["world--1813--m01"]},
  {id:"world--1809--p02",track:"world",year:1809,yearApprox:false,dim:"politics",weight:2,title:"蒂罗尔霍费尔起义",summary:"山区民军三度驱逐巴伐利亚占领者，最终被镇压。",detail:{background:"依普雷斯堡和约蒂罗尔被割让给新升格的巴伐利亚王国，当局推行强制征兵、改税、取消教会节日与传统特权，山区共同体认为义务契约已被破坏。",process:"1809年4月至11月，因斯布鲁克旅店主安德烈亚斯·霍费尔率民军在4月、5月与8月三度夺回因斯布鲁克，配合奥地利在瓦格拉姆前的攻势；10月申布伦和约使奥地利放弃蒂罗尔后，法巴联军于11月重占全境，霍费尔藏匿后被出卖，1810年1月在普拉茨被俘，2月20日在波尔扎诺被枪决。",impact:"霍费尔被蒂罗尔与奥地利民族主义奉为反抗外来统治的原型人物，19世纪以歌曲、纪念碑与纪念仪式构成的记忆体系，至今仍是蒂罗尔地区身份政治的核心符号。",figures:["安德烈亚斯·霍费尔","马克西米利安一世·约瑟夫"],place:"蒂罗尔因斯布鲁克、波尔扎诺",state:"巴伐利亚王国（原蒂罗尔）",sources:["A. J. P. Taylor, The Habsburg Monarchy 1815–1918","《剑桥德意志史》"],tags:["起义","民族主义","蒂罗尔"]},related:["world--1809--p01"]},
  {id:"world--1809--s01",track:"world",year:1809,yearApprox:false,dim:"science",weight:3,title:"气体化合体积定律发表",summary:"盖-吕萨克测定反应气体体积整数比，暴露原子分子之困。",detail:{background:"其实验旨在解释为何道尔顿式的重量相加无法说明水的合成体积，接续了1802年其气体热膨胀研究。",process:"1808年12月约瑟夫·路易·盖-吕萨克向法兰西学会宣读气体化合实验报告，1809年刊布：在相同温度压强下，参与反应的气体体积成简单整数比，例如2体积氢与1体积氧生成2体积水蒸气；他同时提出等体积气体含相同数目「分子」的想法但未坚持。",impact:"体积定律与道尔顿原子论直接冲突，把原子与分子不加区分的问题暴露出来，因而催生阿伏加德罗假说（1811），并最终促成1860年卡尔斯鲁厄会议确立原子与分子的区分。",figures:["约瑟夫·路易·盖-吕萨克","亚历山大·冯·洪堡"],place:"法国巴黎",state:"法兰西第一帝国",sources:["Gay-Lussac, Mémoires de la Classe des sciences mathématiques et physiques (1809)","The Cambridge History of Science, Vol. 5"],tags:["气体化学","计量","实验"]},related:["world--1811--s01"]},
  {id:"world--1810--p01",track:"world",year:1810,yearApprox:false,dim:"politics",weight:4,title:"布宜诺斯艾利斯五月革命",summary:"市民会议罢免总督成立洪达，拉普拉塔独立进程启动。",detail:{background:"1806至1807年英军两度进攻拉普拉塔，本地民兵自行击退守军，克里奥尔人的军事与政治自信大增；1808年约瑟夫·波拿巴强占西班牙王位使总督的合法性彻底动摇。",process:"1810年5月18日至22日，布宜诺斯艾利斯各区的市民代表在市政厅召开公开市政议会，25日成立以萨维德拉为主席的「第一洪达」，罢免总督西斯内罗斯，宣布以斐迪南七世之名行使权力，并立即向内地与上秘鲁派出军事与外交使团。",impact:"五月革命开启了拉普拉塔由洪达到1816年图库曼宣言的独立路线，也埋下布宜诺斯艾利斯与内陆省份、以及乌拉圭东岸（阿蒂加斯）之间的长期分裂，1810年5月25日至今为阿根廷国庆日。",figures:["科尔内利奥·萨维德拉","马里亚诺·莫雷诺","贝尔纳迪诺·里瓦达维亚","何塞·德·圣马丁"],place:"拉普拉塔总督区布宜诺斯艾利斯",state:"西班牙拉普拉塔总督区（第一洪达）",sources:["《剑桥拉丁美洲史》卷三","John Lynch, The Spanish-American Revolutions 1808–1826 (2006)"],tags:["独立运动","洪达","阿根廷"]},related:["world--1816--p01"]},
  {id:"world--1810--p02",track:"world",year:1810,yearApprox:false,dim:"politics",weight:3,title:"多洛雷斯呼声",summary:"伊达尔戈在多洛雷斯发动起义，墨西哥独立战争爆发。",detail:{background:"新西班牙的克里奥尔不满半岛人垄断官职，1808年贝特莱斯·孔韦罗斯在巴利亚多利德密谋成立洪达事泄被捕；伊达尔戈任多洛雷斯本堂神父，与阿连德、阿达马斯等人在圣胡安·德·洛斯莫罗斯秘密结社。",process:"1810年9月16日凌晨，米格尔·伊达尔戈·伊·科斯蒂利亚敲响教堂钟，号召印第安人与混血农民起义（「多洛雷斯呼声」），数周内聚集起六七万人、以棍棒与土炮为武器，攻取瓜纳华托、巴利亚多利德，10月30日蒙特德阿尔马迪维亚桥血战受挫后北撤。",impact:"起义把群众性的农村暴动第一次引入拉美独立进程，社会性质远比拉普拉塔河流域的军人政治深刻；1821年完成独立的墨西哥以9月16日为国庆日，其反西象征意义远超军事成果。",figures:["米格尔·伊达尔戈","伊格纳西奥·阿连德","何塞·马里亚·莫雷洛斯","阿莉亚东多·奥尔蒂斯"],place:"新西班牙瓜纳华托省多洛雷斯",state:"西班牙新西班牙总督区",sources:["《剑桥拉丁美洲史》卷三","John Lynch, The Spanish-American Revolutions 1808–1826 (2006)"],tags:["独立运动","墨西哥","起义"]},related:["world--1811--f01"]},
  {id:"world--1810--p03",track:"world",year:1810,yearApprox:false,dim:"politics",weight:3,title:"圣地亚哥九月十八日政变",summary:"圣地亚哥市民罢免加西亚·卡拉斯科，智利进入旧祖国时期。",detail:{background:"智利总督弗朗西斯科·加西亚·卡拉斯科拒绝承认塞维利亚洪达，与本地克里奥尔人矛盾激化；阿根廷五月革命的消息于8月经门多萨传入。",process:"1810年9月18日，圣地亚哥爱国派在兵营哗变支持下迫使总督卡拉斯科召开议会并罢免之，成立由博尔内罗斯等组成的洪达，卡拉斯科次年被枪决；此后1810至1814年「旧祖国」阶段内，卡雷拉兄弟与奥伊金斯先后掌权，1814年兰卡瓜战役后保王派重占智利。",impact:"智利由此进入独立试验期，1817年圣马丁与奥伊金斯越安第斯山、1818年查卡布科与马伊普战役后确立独立；1810年9月18日为智利国庆日。",figures:["何塞·米格尔·卡雷拉","贝尔纳多·奥伊金斯","弗朗西斯科·加西亚·卡拉斯科"],place:"智利总督区圣地亚哥",state:"西班牙智利总督区",sources:["《剑桥拉丁美洲史》卷三","Simon Collier & William Sater, A History of Chile"],tags:["独立运动","智利","洪达"]},related:["world--1818--m02"]},
  {id:"world--1810--p04",track:"world",year:1810,yearApprox:false,dim:"politics",weight:3,title:"加拉加斯四月十九日洪达",summary:"委内瑞拉克里奥尔罢免西班牙军事总督，成立执政洪达。",detail:{background:"加拉加斯商会自1790年代起推动贸易自由与取消公司特权；1808年拿破仑入侵西班牙后，1809年12月米兰达在拉瓜伊拉登陆的起义未成。",process:"1810年4月19日，加拉加斯市政议会在民众与民兵压力下成立执政洪达，罢免军事总督比森特·德埃斯帕尼亚，声明拥戴斐迪南七世并派使团赴伦敦求援；7月召集资制大会，1811年7月5日宣布独立。",impact:"委内瑞拉成为宣布独立最快、也最早陷入党争与西班牙反攻的地区之一：1812年大地震后米兰达投降、第一共和国覆灭，玻利瓦尔由此写出卡塔赫纳宣言，提出「新大陆一体」的战略。",figures:["弗朗西斯科·德·米兰达","西蒙·玻利瓦尔","比森特·埃斯帕尼亚"],place:"委内瑞拉加拉加斯",state:"西班牙委内瑞拉都督区",sources:["《剑桥拉丁美洲史》卷三","John Lynch, Simon Bolivar: A Life (2006)"],tags:["独立运动","委内瑞拉","洪达"]},related:["world--1812--d01"]},
  {id:"world--1810--p05",track:"world",year:1810,yearApprox:false,dim:"politics",weight:3,title:"贝尔纳多特当选瑞典王储",summary:"瑞典议会选拿破仑元帅为继承人，北欧结盟方向由此改变。",detail:{background:"1809年瑞典在对俄战争中失败，失去芬兰并与丹麦决裂；国王古斯塔夫四世·阿道夫被废，其弟卡尔十三世即位后因无嗣需指定继承人，9月原选定的克里斯蒂安·奥古斯特亲王突然去世。",process:"1810年8月21日（接受9月），瑞典非常议会选举拿破仑的元帅让-巴蒂斯特·贝尔纳多特为王储（改名卡尔·约翰）；拿破仑起初默许。贝尔纳多特入新教、赴斯特拉尔松任总司令，但随即背弃大陆封锁，1812年4月与俄国结盟、8月与英国缔约，并坚持以挪威交换瑞典的补偿。",impact:"这一继承安排使瑞典彻底退出法国体系并加入第六、第七次同盟，1813年贝尔纳多特在登尼茨维茨与瓦肖击败法军；1814年基尔和约使挪威并入瑞典，北欧版图重画，其王朝延续至今。",figures:["让-巴蒂斯特·贝尔纳多特","卡尔十三世","拿破仑一世","亚历山大一世"],place:"瑞典勒勒布罗／斯德哥尔摩",state:"瑞典",sources:["【《剑桥斯堪的纳维亚史》】记贝尔纳多特当选王储的经过与1812年后对法开战","【勒费弗尔《拿破仑时代》】论大陆封锁与瑞典的取向转变"],tags:["王位继承","北欧","外交转向"]},related:["world--1813--m01"]},
  {id:"world--1810--e01",track:"world",year:1810,yearApprox:false,dim:"economy",weight:3,title:"英国通货委员会金银报告",summary:"下院委员会论英镑贬值与黄金溢价，埋下金本位之争。",detail:{background:"1797年皮特政府为支付战争经费暂停英格兰银行钞票兑付黄金（限制兑付令），此后物价上涨、英镑汇率跌落，1809年黄金市价远高于铸币平价。",process:"1810年3月下院设立通货委员会，F. 霍纳任主席，12月提交报告，将英镑贬值归因于纸币超发与限制兑付令，主张恢复金币兑付以稳定汇率；1811年下院以78对22的多数通过其决议反对该报告，但上院与学界（李嘉图等）多支持其结论。",impact:"金银论争确立了以黄金平价衡量通货信用的分析框架，1819年皮尔法案恢复兑付、1821年金币事实上回归，成为英国金本位（1816年法定）的理论与制度起点。",figures:["弗朗西斯·霍纳","大卫·李嘉图","亨利·桑顿"],place:"英国伦敦",state:"英国",sources:["【英国下院通货委员会《金银高价报告》（1810年12月）】将贬值归因于限制兑付令与纸币超发","【李嘉图《高金价短论》（1810年）】同论英镑贬值的纸币原因"],tags:["货币","金本位","英格兰银行"]},related:["world--1815--e02"]},
  {id:"world--1810--m01",track:"world",year:1810,yearApprox:false,dim:"military",weight:3,title:"布萨库战役与托雷斯韦德拉什线",summary:"威灵顿凭预设阵地阻住马塞纳，半岛战局转为守势消耗。",detail:{background:"拿破仑命马塞纳率约六万军入侵葡萄牙，期望一举摧毁英国的伊比利亚基地；威灵顿自1808年起在葡萄牙构筑秘密防线。",process:"1810年9月27日，马塞纳在布萨库山地强攻英军左翼阵地失利，双方伤亡合计约1.2万人；10月法军推进至里斯本以北的托雷斯韦德拉什线，面对横断半岛、配有152座炮台与海军补给的筑垒阵地无法突破，1811年3月3日至4日进攻失败后于3月5日至6日撤退，沿途遭游击与英军追击。",impact:"马塞纳部的溃退使法军永久失去葡萄牙，被迫在西班牙维持漫长补给线与分散据点；半岛战场由此成为牵制法军的「西班牙溃疡」，为1812年征俄后法军无法抽身反击埋下伏笔。",figures:["阿瑟·韦尔斯利","安德烈·马塞纳","拿破仑一世"],place:"葡萄牙布萨科、托雷斯韦德拉什",state:"英国／葡萄牙／法兰西第一帝国",sources:["Charles Esdaile, The Peninsular War (2002)","Osborne, The Peninsular War 相关英军档案"],tags:["半岛战争","筑垒","消耗战"]},related:["world--1811--m01"]},
  {id:"world--1810--p06",track:"world",year:1810,yearApprox:false,dim:"politics",weight:3,title:"法国吞并荷兰与北海海岸",summary:"拿破仑废荷兰王国，把北海沿岸并入法国本土。",detail:{background:"荷兰国王路易·波拿巴因无法有效执行大陆封锁、又需维持贸易而屡与拿破仑冲突，走私在北海沿岸蔓延。",process:"1810年7月1日路易被迫退位、其子继位未成，7月9日至11日发布吞并法令：荷兰、原贝格属林堡与北莱茵、汉萨城市汉堡与不来梅、以及瓦卢瓦与部分德意志海岸一并并入法国，设省直辖，1811年起实施统一的法国法典、税制与征兵制；教宗亦因罗马被吞并而于同年被扣押。",impact:"吞并使大陆封锁在形式上覆盖全部欧洲西海岸，但法国随即需要在此驻重兵防范走私与征兵抵抗；1813至1814年德意志与荷兰的反法情绪，正是以这次兼并与强制征兵为直接动因。",figures:["拿破仑一世","路易·波拿巴","庇护七世"],place:"法国巴黎／荷兰阿姆斯特丹",state:"法兰西第一帝国",sources:["《1810年7月吞并法令》（法国国家公报）","The Cambridge History of the Napoleonic Wars"],tags:["吞并","大陆封锁","荷兰"]},related:["world--1806--i01"]},
  {id:"world--1811--p01",track:"world",year:1811,yearApprox:false,dim:"politics",weight:3,title:"委内瑞拉宣布独立",summary:"资制大会通过独立宣言，成立美洲第一个共和国。",detail:{background:"1810年4月洪达后，各省于1811年2月选出资制大会，3月5日开幕，米兰达与玻利瓦尔推动正式决裂。",process:"1811年7月5日，委内瑞拉资制大会通过《独立宣言》，宣布七个省脱离西班牙、成立美利坚合众国式的联邦共和国，米兰达任总司令；同期通过的国旗与宪法确立联邦制与人权宣言，但保王派在科赫德斯等西部省获得大量支持，内战与地震并发。",impact:"这是拉美第一个以宣言形式正式独立的共和国，其7月5日成为委内瑞拉国庆日；第一共和国1812年7月因米兰达投降而覆灭，玻利瓦尔在卡塔赫纳与牙买加文件中将此教训转为「团结中央集权」主张。",figures:["弗朗西斯科·德·米兰达","西蒙·玻利瓦尔","米格尔·佩尼亚韦拉"],place:"委内瑞拉加拉加斯",state:"委内瑞拉第一共和国",sources:["《委内瑞拉独立宣言》（1811年7月5日）","《剑桥拉丁美洲史》卷三"],tags:["独立宣言","共和国","委内瑞拉"]},related:["world--1812--d01"]},
  {id:"world--1811--p02",track:"world",year:1811,yearApprox:false,dim:"politics",weight:3,title:"巴拉圭独立",summary:"亚松森市民会议罢免西班牙总督，成立国民洪达。",detail:{background:"拉普拉塔五月革命后，亚松森的西班牙官员拒绝承认布宜诺斯艾利斯洪达，本地克里奥尔军界在卡瓦列罗家族与独立人士之间重新站队。",process:"1811年5月14日至15日夜，菲赫雷奥兵营起事，次日市政议会罢免军事总督贝拉尔迪，成立由富尔亨西奥·耶格罗斯与卡瓦列罗主持的国民洪达；6月贝尔格拉诺率军沿巴拉那河下进攻，被耶格罗斯在塔库里亚维（1811年1月19日）击退，1813年两国签订友好条约事实上承认独立。",impact:"巴拉圭由此走上与拉普拉塔分离的独立道路，1814年后弗朗西亚以「最高统治者」实行长期闭关独裁；其独立不依靠外部援军，也未经历长期内战，代价是此后的政治封闭。",figures:["富尔亨西奥·耶格罗斯","曼努埃尔·贝尔格拉诺","何塞·加斯帕尔·罗德里格斯·德·弗朗西亚"],place:"巴拉圭亚松森",state:"巴拉圭（原西班牙拉普拉塔属省）",sources:["《剑桥拉丁美洲史》卷三","Thomas Whigham & Barbara Potthast, The Paraguayan Republic"],tags:["独立运动","巴拉圭","洪达"]},related:["world--1810--p01"]},
  {id:"world--1811--e01",track:"world",year:1811,yearApprox:false,dim:"economy",weight:3,title:"卢德运动爆发",summary:"诺丁汉织工砸毁织袜机，英以死刑法镇压机器破坏。",detail:{background:"1811年英格兰中部因封锁、粮价高涨与针织业按件计酬崩坏而失业严重，机械化的宽幅织袜机被视为压低工资与剥夺熟练工生计的直接原因。",process:"1811年11月11日起，诺丁汉周边的织工夜袭并砸毁针织机，卢德（「内德·卢德」为传说人物）名义迅速传至德比、莱斯特，1812年初又延至约克郡西区的粗布厂；1812年2月议会通过《框架破坏法》把砸机定为可处死刑之罪，1813年1月约克特别法庭审判180余人，据当时记载处绞刑数十人。",impact:"镇压并未阻止机械化，但工人把斗争目标从机器转向结社与议会请愿，成为1824年结社合法化、1830年代工会与宪章运动的经验来源；E. P. 汤普森称之为「工人阶级有组织的集体谈判前形态」。",figures:["内德·卢德（传说人物）","罗伯特·斯特格","拜伦"],place:"英格兰诺丁汉郡、约克郡",state:"英国",sources:["E. P. Thompson, The Making of the English Working Class (1963)","Page, The Lauddites (1929)"],tags:["工人运动","机器","镇压"]},related:["world--1824--e02"]},
  {id:"world--1811--e02",track:"world",year:1811,yearApprox:false,dim:"economy",weight:3,title:"奥地利纸币信用崩溃",summary:"哈布斯堡王朝把纸币按五分之一收兑，战争财政代价显形。",detail:{background:"对法战争使奥地利财政长期入不敷出，1762年起的国家银行券至1811年流通额膨胀，物价上涨数倍，信用近乎崩溃。",process:"1811年1月31日（一说1809年9月起贬值）朝廷发布货币决议：新发纸币以「银币券」名义流通，旧国家银行券按五分之一比价强制收兑，同时暂停债券利息按票面支付、并压低国债利率，实际上等于部分违约。",impact:"这次货币贬值把战争成本转嫁到债权人、官员与城市市民，使奥地利财政信用在19世纪上半叶持续受限；1818年与1838年货币改革重建银本位，才逐步稳定了哈布斯堡的财政。",figures:["卡尔·冯·施塔迪翁","梅特涅","弗朗茨一世"],place:"奥地利维也纳",state:"奥地利帝国",sources:["【1811年1月31日奥地利货币专利令】规定银行券按五分之一收兑并转为国债","【《剑桥欧洲经济史》】论哈布斯堡战争财政与纸币信用的崩溃"],tags:["纸币","财政危机","奥地利"]},related:["world--1806--i01"]},
  {id:"world--1811--e03",track:"world",year:1811,yearApprox:false,dim:"economy",weight:2,title:"英军占领荷属爪哇",summary:"英国远征军自印度出击，夺取荷兰在印尼的统治中心。",detail:{background:"1806年荷兰成为法兰西附庸后，荷属东印度的港口与航线成为英国打击目标；印度总督明托勋爵与东印度公司主张以爪哇为重点，消除法国在印度洋的据点。",process:"1811年8月初，英国远征军约一万人自印度启航，在海军掩护下于爪哇北岸登陆，逐次突破荷法守军防线；8月26日荷属巴达维亚当局投降，英军控制巴达维亚等港口。随军文官莱佛士参与接管，废除部分强制役与封建贡纳，开放港口与土地交易。",impact:"英国统治中断了荷属东印度的旧体制，依1814年协定归还、1816年实际交还荷兰；其间的土地税试验成为19世纪荷属印度政策的模板，并确认英国在印度洋与巽他海峡的海权优先。",figures:["托马斯·莱佛士","明托勋爵"],place:"荷属爪哇巴达维亚（今雅加达）",state:"英国／巴达维亚共和国（法兰西附庸）",sources:["【《剑桥东南亚史》】记1811年英国占领爪哇与行政接管","【《牛津不列颠帝国史》】论东印度公司在印度洋的扩张"],tags:["殖民","东南亚","海权"]},related:["world--1815--p02"]},
  {id:"world--1811--s01",track:"world",year:1811,yearApprox:false,dim:"science",weight:4,title:"阿伏加德罗提出分子假说",summary:"阿伏加德罗区分原子与分子，化解气体体积比难题。",detail:{background:"盖-吕萨克1808至1809年的化合体积定律与道尔顿原子论相冲突：若等体积气体含相同数目原子，水就不可能由2体积氢加1体积氧生成2体积水气。",process:"1811年6月与7月，阿梅代奥·阿伏加德罗在《物理学杂志》分两期发表《测定元素分子相对质量及其比例方法试论》，提出等温等压下等体积气体含相同数目的「分子」，分子可由原子成对结合（氢、氧、氮为双原子分子），从而把原子量与分子量分置为两套可推算的量。",impact:"假说被同时代人长期忽视（因与道尔顿及贝采里乌斯的电化二元论抵触），1858至1860年经坎尼扎罗以分子量重整原子量表才被确认，1860年卡尔斯鲁厄会议标志其胜利；阿伏加德罗常数至1900年前后才被精确测定。",figures:["阿梅代奥·阿伏加德罗","约翰·道尔顿","斯坦尼斯劳·坎尼扎罗"],place:"意大利（撒丁王国）韦尔切利／都灵",state:"拿破仑治下的北意大利（后属撒丁王国）",sources:["Amedeo Avogadro, Journal de Physique (1811)","《剑桥科学史》卷五"],tags:["分子论","化学计量","阿伏加德罗"]},related:["world--1860--s01"]},
  {id:"world--1811--f01",track:"world",year:1811,yearApprox:false,dim:"figure",weight:3,title:"伊达尔戈就义",summary:"墨西哥起义领袖被保王军处决，首级悬于阿尔洪迪加粮仓。",detail:{background:"1811年1月卡尔德龙桥战役起义军被帕雷德斯击溃，伊达尔戈率残部北撤试图越境取美援，2月在阿卡尔特·德·巴甘被叛卖俘获。",process:"1811年7月30日，被革除圣职的伊达尔戈在奇瓦瓦被军事法庭判处死刑并枪决（一说先受鞭刑后处决），首级与阿连德等人一同悬挂在圣布拉斯小教堂的阿尔洪迪加（谷仓）上以儆效尤，直至1823年才取下。",impact:"伊达尔戈之死使运动领导权转入更具军事与组织才能的莫雷洛斯手中，后者1813年在奇尔潘辛戈会议提出墨西哥独立与宪政；1824年独立后的墨西哥把他尊为「国父」，谷仓遗址成为国家纪念建筑。",figures:["米格尔·伊达尔戈","伊格纳西奥·阿连德","何塞·马里亚·莫雷洛斯"],place:"新西班牙奇瓦瓦",state:"西班牙新西班牙总督区",sources:["《剑桥拉丁美洲史》卷三","John Lynch, The Spanish-American Revolutions 1808–1826 (2006)"],tags:["人物","墨西哥","独立运动"]},related:["world--1810--p02"]},
  {id:"world--1811--m01",track:"world",year:1811,yearApprox:false,dim:"military",weight:3,title:"富恩特斯德奥尼奥罗战役",summary:"威灵顿击退马塞纳最后一次解围，法军退出葡萄牙。",detail:{background:"马塞纳在托雷斯韦德拉什线受阻后退回葡北，围困阿尔梅达，威灵顿分兵南下解围。",process:"1811年5月3日至5日，双方在富恩特斯德奥尼奥罗（葡西边境）连续交战，威灵顿以四线横列与步兵方阵顶住法军多次纵队冲击，5日夜马塞纳因补给不继撤退，阿尔梅达于5月12日陷落；同月5日、16日在阿尔布埃拉发生另一场惨烈会战。",impact:"此役彻底终结了法军对葡萄牙的攻势，阿尔梅达失守反而使法军失去了反攻的立足点；半岛战局转为由英葡-西班牙联军主导，法军被压缩于西班牙境内据点网中。",figures:["阿瑟·韦尔斯利","安德烈·马塞纳","威廉·贝雷斯福德"],place:"葡西边境富恩特斯德奥尼奥罗、阿尔布埃拉",state:"英国／葡萄牙／法兰西第一帝国",sources:["Charles Esdaile, The Peninsular War (2002)","Fortescue《英国陆军史》半岛部分"],tags:["半岛战争","战役","防线"]},related:["world--1810--m01"]},
  {id:"world--1812--m01",track:"world",year:1812,yearApprox:false,dim:"military",weight:5,title:"拿破仑远征俄国",summary:"大军团渡涅曼河深入俄境，战略决战落空而补给线崩溃。",detail:{background:"蒂尔西特体系自1810年起松动：俄国恢复对中立贸易的许可、拒绝严格执行大陆封锁，并重新扩军；波兰问题与拿破仑的约瑟夫-俄国公主婚议破裂加深对立。",process:"1812年6月24日前后，拿破仑率约42万人（另有后备，学界对总数估计为45万至60余万）分渡涅曼河，俄军按巴克莱·德托利计划避免决战、边战边退并坚壁清野；8月16日至18日法军攻占斯摩棱斯克，但未能歼灭俄军主力，9月7日博罗季诺一战未获决定性结果，法军于9月14日进入已成空城并大火的莫斯科，等待和谈无果后于10月19日撤离。",impact:"远征在半年内使大军团事实上覆灭（学界估计法方死亡与被俘合计约38万以上），第一次打破了拿破仑军事优势的不可逆性；普鲁士、奥地利随之倒向，1813年莱比锡民族之战与1814年帝俄进入巴黎皆由此役决定。",figures:["拿破仑一世","巴克莱·德托利","米哈伊尔·库图佐夫","亚历山大一世","约瑟夫·波拿巴"],place:"俄国涅曼河至莫斯科、斯摩棱斯克",state:"法兰西第一帝国／俄国",sources:["《拿破仑书信集》与钱德勒《拿破仑的战役》","《剑桥俄国史》卷二（帝国俄国1689–1917）"],tags:["远征","消耗","拿破仑战争"]},related:["world--1806--i01"]},
  {id:"world--1812--m02",track:"world",year:1812,yearApprox:false,dim:"military",weight:4,title:"博罗季诺战役",summary:"法军以近八万兵力夺占俄军阵地却未获歼灭性战果。",detail:{background:"巴克莱被解职后库图佐夫继任总司令，面临军中与宫廷的主战压力，选择在莫斯科近郊接受会战以保卫古都。",process:"1812年9月7日（俄历8月26日），拿破仑约13万人对库图佐夫约12万至14万人，在莫斯科以西75英里的博罗季诺村一带会战。法军先后强攻巴格拉季昂箭形堡与中央的拉耶夫斯基炮台，反复易手数次，俄军中央与左翼撤退有序、主力未被合围；双方合计伤亡学界估计约7万人，为拿破仑战争中单日最血腥的一场。",impact:"博罗季诺在战术上由法军占优，战略上却使拿破仑失去迫使俄国媾和的手段：俄军保存实力、放弃莫斯科，战争转入以空间与季节取胜的阶段。",figures:["米哈伊尔·库图佐夫","拿破仑一世","彼得·巴格拉季昂","欧仁·德·博阿尔内"],place:"俄国莫斯科州博罗季诺",state:"法兰西第一帝国／俄国",sources:["《拿破仑的战役》钱德勒","Troyat, Alexander I 与《剑桥俄国史》卷二"],tags:["战役","伤亡","决战"]},related:["world--1812--m03"]},
  {id:"world--1812--m03",track:"world",year:1812,yearApprox:false,dim:"military",weight:3,title:"莫斯科大火",summary:"法军入城即遇纵火与粮缺，占领古都成为战略负担。",detail:{background:"俄军放弃莫斯科是库图佐夫以保存军队为优先的决定；总督罗斯托普金组织了灭火与疏散的矛盾行动。",process:"1812年9月14日法军先头部队进入莫斯科时，城市已依库图佐夫命令疏散、粮食与物资被搬空；当夜起多处起火，至18日至19日延烧成灾，据当时统计城内约三分之二至四分之三的房屋被毁（数字口径不一），克里姆林宫亦受损，法军被迫进驻郊区与「凡尔登的掠夺」式搜刮。",impact:"失去莫斯科使拿破仑既无冬季营地也无谈判筹码：10月18日马洛亚罗斯拉韦茨之战后西撤成为唯一选项，占领古都反而加重了法军在撤退时的补给与纪律崩溃。",figures:["费奥多尔·罗斯托普金","拿破仑一世","缪拉","若米尼"],place:"俄国莫斯科",state:"法兰西第一帝国／俄国",sources:["《拿破仑的战役》钱德勒","《战争与和平》同时代记述与《剑桥俄国史》卷二"],tags:["火灾","占领","补给"]},related:["world--1812--m01"]},
  {id:"world--1812--m04",track:"world",year:1812,yearApprox:false,dim:"military",weight:3,title:"别列津纳河强渡",summary:"法军在俄军三面合围下架桥渡河，残部得以脱出。",detail:{background:"11月初施塔拉渡河计划被奇恰戈夫部阻住，法军被迫北移寻找浅渡点，同时以佯动遮蔽真实渡点。",process:"1812年11月26日至29日，拿破仑残部在气温降至零下二三十度的条件下抵近别列津纳河，前派部队在斯图焦恩卡以木料与浮桥器材架桥；在奇恰戈夫自南岸、维特根斯坦自北岸、库图佐夫自东尾追的合围下，工兵抢修浮桥使主力渡河，但伴随的辎重、溃兵与冻饿者在挤桥与俄军炮击时大量死亡，渡河后随军西撤的战斗人员不足三万（学界数字口径不一）。",impact:"别列津纳使拿破仑避免了一次整军被围歼的结局，却未能挽回远征的战略失败；12月5日拿破仑在斯莫尔贡尼离队先返巴黎，军队交由缪拉指挥，12月18日其抵达巴黎的消息震动全欧。",figures:["拿破仑一世","帕维尔·奇恰戈夫","彼得·维特根斯坦","若阿基姆·缪拉"],place:"俄国别列津纳河斯图焦恩卡",state:"法兰西第一帝国／俄国",sources:["《拿破仑的战役》钱德勒","《剑桥俄国史》卷二"],tags:["渡河","撤退","严寒"]},related:["world--1812--m01"]},
  {id:"world--1812--i01",track:"world",year:1812,yearApprox:false,dim:"institution",weight:4,title:"加的斯宪法颁布",summary:"西班牙议会通过自由主义宪法，确立主权在民与普选。",detail:{background:"1810年法军围困下，议会先迁至莱昂岛后定居加的斯，1810年9月24日开幕的会议中自由派与摄政会反复角力。",process:"1812年3月19日通过《西班牙国家与公民宪法》共384条：宣布主权属于国家而非国王，设一院制议会、年度会期与大臣问责制，确立普选制的间接选举（覆盖本土与海外属地的成年男性，包括按出生地原则取得国籍的美洲人），废除刑讯、限制教会与宗教裁判所，取消部分贵族特权；国王被定义为「行政首脑」且须宣誓效忠宪法。",impact:"这部宪法成为19世纪南欧与拉美自由主义的样板文本，1820年、1836年与1869年被反复援引与仿制；在美洲，其代表权条款反而加速了保守派与地方考迪罗另立主权的要求，1814年斐迪南七世复辟即宣布其无效。",figures:["阿瓜约·穆尼奥斯·托雷洪","华金·洛佩斯·莫雷诺"],place:"西班牙加的斯",state:"西班牙（洪达摄政时期）",sources:["《1812年3月19日西班牙宪法》原文","《剑桥西班牙史》"],tags:["宪法","自由主义","主权在民"]},related:["world--1820--p01"]},
  {id:"world--1812--p01",track:"world",year:1812,yearApprox:false,dim:"politics",weight:3,title:"布加勒斯特和约",summary:"俄土媾和让出比萨拉比亚，解除拿破仑东线的侧翼。",detail:{background:"1806年至1812年俄土战争在多瑙河与高加索两线胶着，拿破仑对俄开战在即，俄国急需收缩南线。",process:"1812年5月28日（俄历5月16日），米尔洛维奇与另方代表在布加勒斯特签约：奥斯曼让出借比萨拉比亚（普鲁特河与德涅斯特河之间）与部分多瑙河口，承认俄国在高加索的阿尔赫西拉瓦诺等地，双方约定互不干涉，俄国则限期撤出摩尔达维亚与瓦拉几亚。",impact:"和约为俄国在南线腾出约4.5万兵力投入对法战争，直接改善了1812年俄军的兵员困境；比萨拉比亚的取得改变了黑海西北岸格局，并为1813至1814年俄国多瑙河军团与高加索军团的调动创造条件。",figures:["米哈伊尔·库图佐夫","马克·米洛维奇"],place:"瓦拉几亚布加勒斯特",state:"俄国／奥斯曼帝国",sources:["《近代国际条约集》","《剑桥俄国史》卷二"],tags:["和约","俄国","奥斯曼"]},related:["world--1812--m01"]},
  {id:"world--1812--p02",track:"world",year:1812,yearApprox:false,dim:"politics",weight:3,title:"瑞典与俄英相继结好",summary:"瑞典以承认俄国得芬兰换取对挪威的承认，转向反法。",detail:{background:"贝尔纳多特继任瑞典王储后判断大陆封锁已不可持续，需以对俄、对英和解换取挪威，拿破仑则试图以波美拉尼亚与不干涉芬兰为条件拉回瑞典。",process:"1812年3月28日贝尔纳多特在勒勒布罗公告中承诺「为瑞典取得挪威」，4月3日与英国签订和平与友好协定（英国承诺不以武力阻碍瑞典取得挪威），4月4日至5日与俄国在图尔库（Åbo）签订条约，俄国确认1809年弗雷德里克斯哈姆边界并支持瑞典对挪威的要求。",impact:"瑞典由此退出拿破仑体系，1813年加入第六次同盟、贝尔纳多特率北方军团在登尼维茨与瓦肖作战，1814年基尔和约迫使丹麦割让挪威，北欧形成瑞挪联合与俄国为芬兰大公的双元格局。",figures:["让-巴蒂斯特·贝尔纳多特","亚历山大一世"],place:"瑞典勒勒布罗／芬兰图尔库",state:"瑞典／俄国／英国",sources:["《近代国际条约集》","《剑桥北欧史》"],tags:["外交转向","挪威","同盟"]},related:["world--1814--p03"]},
  {id:"world--1812--m05",track:"world",year:1812,yearApprox:false,dim:"military",weight:3,title:"美国对英宣战",summary:"杰斐逊党人因海上权利与西部土地对英开战。",detail:{background:"英国以海上检查权拦截美船、强征水手，并据1810年前英属加拿大边界向印第安人提供武器；1807年切萨皮克号事件与《禁运法》失败后，以卡尔洪、克莱为首的「战鹰」派主张以战争解决。",process:"1812年6月18日麦迪逊签署对英宣战书（众院79比49、参院19比13通过，且为美国首次宣战、东北部联邦党人一致反对）；战争初期三路入侵加拿大均告失败，8月19日「宪法号」在「战士号」之战获胜（「老铁壁」之称由此而来），9月10日佩里控制伊利湖，1813年10月5日泰晤士河之战使特库姆塞阵亡。",impact:"《根特条约》（1814年12月24日）以恢复战前状态告终，未涉及强征水手与中立权利（因欧洲战事结束而自行失效）；但新奥尔良大捷与「星条旗」使1812年战争被塑造为二次独立战争，也永久终结了东部印第安人对英国同盟的依赖。",figures:["詹姆斯·麦迪逊","约翰·卡尔洪","亨利·克莱","霍雷肖·琼斯","特库姆塞"],place:"美国华盛顿／北大西洋与加拿大边境",state:"美国／英国",sources:["《合众国法律总汇编》第2卷（宣战决议）","Alan Taylor, The Civil War of 1812 (2010)"],tags:["1812年战争","海权","北美"]},related:["world--1814--m02"]},
  {id:"world--1812--d01",track:"world",year:1812,yearApprox:false,dim:"disaster",weight:3,title:"新马德里大地震群",summary:"密苏里东南连续三次强震，密西西比河短暂倒流。",detail:{background:"1811至1812年冬，北美内陆板块内部断裂带活动，前震于1811年12月出现，当时该地区人口稀少但拓殖正在推进。",process:"1811年12月16日、1812年1月23日与2月7日发生三次主震，据现代研究震级约为7.2、7.4与7.5至8.0级，影响面积约150万平方公里；田纳西一侧因隆起形成里富特湖，密西西比河在浅弯处出现倒流与「河水后退」，圣路易斯与纳切兹报告房屋与烟囱受损，印第安部落口述传说中记录了地震与「燃烧的地面」。",impact:"这是美国本土有记录以来最强的地震序列之一，其后果包括密西西比河航线局部改道与基卡普人等部落的迁徙压力，19世纪末起成为板块内地震研究的经典案例。",figures:["伊莱贾·洛夫乔伊"],place:"美国密苏里州新马德里／田纳西州里富特湖",state:"美国",sources:["美国地质调查局（USGS）新马德里地震带研究","Toppozada & Brackett, 1811–12序列历史地震报告"],tags:["地震","北美","断层"]},related:[]},
  {id:"world--1812--p03",track:"world",year:1812,yearApprox:false,dim:"politics",weight:3,title:"委内瑞拉第一共和国覆灭",summary:"大地震与保王军并进，米兰达签约投降后玻利瓦尔出走。",detail:{background:"1811年7月独立后，共和国军力薄弱、联邦体制使各省拒不出兵，蒙蒂尼亚保王派在乡村游击，西班牙摄政府派蒙特维尔德率军封锁海岸。",process:"1812年3月26日（复活节圣周四）凌晨加拉加斯与瓦伦西亚等地震，死亡者学界估计约一万人（当代记载与后世研究差异较大）；蒙特韦德自科罗东进，米兰达在巴伦西亚、圣埃斯特万失利，7月25日在圣马特奥签订投降协定后于7月30日在拉瓜伊拉被捕、押往加的斯，1816年死于军械库监狱。",impact:"共和国的失败被玻利瓦尔归因于联邦制的分散与教会动员（其1812年《卡塔赫纳宣言》与1815年《牙买加信札》均申此论），这一教训直接塑造了他1819年后主张中央集权、以军事优先推进解放的战略。",figures:["弗朗西斯科·德·米兰达","西蒙·玻利瓦尔","多明戈·蒙特韦德"],place:"委内瑞拉加拉加斯、圣马特奥、拉瓜伊拉",state:"委内瑞拉第一共和国",sources:["玻利瓦尔《卡塔赫纳宣言》(1812)、《牙买加信札》(1815)","《剑桥拉丁美洲史》卷三"],tags:["独立运动","地震","共和国"]},related:["world--1811--p01"]},
  {id:"world--1813--m01",track:"world",year:1813,yearApprox:false,dim:"military",weight:5,title:"莱比锡民族之战",summary:"四国联军会战法军，拿破仑在德意志的统治瓦解。",detail:{background:"停战期（6月4日至8月16日）内联军在特拉亨贝格约定避免与拿破仑正面决战、先打击其部属；8月奥地利加入第六次同盟，俄奥普瑞分别组成北、西、西里西亚与波兰军团。",process:"1813年10月16日至19日，拿破仑约19万至20万（含萨克森部队）对俄奥普瑞四国联军约38万人，在莱比锡周边会战；18日萨克森军临阵倒戈，法军弹药与兵力俱显不足。19日法军向西撤退渡过白埃尔斯特河时，林德瑙唯一的桥梁被过早炸断，麦克唐纳与雷尼埃两军被隔断于东岸，法军损失含被俘约计五万至八万（学界区间），联军约四万至五万。",impact:"莱比锡使莱茵联邦各邦在10月底至11月相继与拿破仑断绝关系、倒向同盟，法国失去德意志的兵力与财源基础；1814年1至2月联军即在六路越莱茵河，3月31日进入巴黎。此役是1914年之前欧洲参战人数最多的会战。",figures:["拿破仑一世","亚历山大一世","梅特涅","布吕歇尔","施瓦岑贝格","卡尔·冯·克劳塞维茨"],place:"萨克森莱比锡",state:"法兰西第一帝国／第六次反法同盟",sources:["《拿破仑的战役》钱德勒","《剑桥德意志史》卷一"],tags:["战役","民族之战","德意志"]},related:["world--1814--p01"]},
  {id:"world--1813--m02",track:"world",year:1813,yearApprox:false,dim:"military",weight:3,title:"德累斯顿战役",summary:"拿破仑在萨克森取得最后的大胜，却无法转为战略结果。",detail:{background:"停战期结束、联军分路进攻，拿破仑以约12万兵力居中，试图以内线作战各个击破。",process:"1813年8月26日至27日，拿破仑在德累斯顿以近卫军与苏尔特、维克托、内伊各军回击施瓦岑贝格约21万至23万联军的正面进攻，27日迫使联军撤退，联军损失约3.8万（含被俘），法军约2.7至3万；法军在城郊的正面防御由圣西尔、古维翁-马科奈等部承担；曾在拿破仑麾下后投联军的法军将领莫罗在城外交火中被炮弹击伤，次月身亡。",impact:"德累斯顿证明拿破仑仍能打赢大战，但内伊在卡茨巴赫（8月26日）、旺达姆在库尔姆（8月29至30日）的接连失利使胜果无法扩张；9月6日登尼维茨之败与10月莱比锡决战，最终把萨克森战场让给联军。",figures:["拿破仑一世","施瓦岑贝格","让·万桑·莫罗","米歇尔·内伊"],place:"萨克森德累斯顿、格尔利茨",state:"法兰西第一帝国／第六次反法同盟",sources:["《拿破仑的战役》钱德勒","The Cambridge History of the Napoleonic Wars"],tags:["战役","萨克森","胜果"]},related:["world--1813--m01"]},
  {id:"world--1813--m03",track:"world",year:1813,yearApprox:false,dim:"military",weight:3,title:"维多利亚战役：法军被逐出西班牙",summary:"威灵顿分兵包抄击溃约瑟夫军团，马德里易手。",detail:{background:"1813年6月拿破仑急调约瑟夫与儒尔当的部队回德意志，联军趁法军换防、集结于潘普洛纳以南之机发起攻势。",process:"1813年6月21日，威灵顿以约8万人分三路（包括比利亚韦德方向的帕克南纵队）攻击约瑟夫·波拿巴与儒尔当约6.5万至7.5万人，法军中央溃散、向潘普洛纳撤退；法军丢弃全部辎重、火炮与约瑟夫的王室收藏（部分挂毯后于马德里被追还），联军随即进入布尔戈斯、圣塞瓦斯蒂安开始围城，11月9日至10日在尼韦勒河越境进入法国。",impact:"维多利亚之役使拿破仑彻底失去西班牙（除加泰罗尼亚少数港口），约50个营队被永久牵制；法军从伊比利亚抽身后，联军的西班牙老兵与骑兵成为1814年在法国南部作战的核心兵力。",figures:["阿瑟·韦尔斯利","约瑟夫·波拿巴","茹尔当"],place:"西班牙维多利亚（巴斯克语称加斯特伊斯）",state:"英国／西班牙／法兰西第一帝国",sources:["Charles Esdaile, The Peninsular War (2002)","Gates《半岛战争》"],tags:["战役","西班牙","溃退"]},related:["world--1808--m01"]},
  {id:"world--1813--p01",track:"world",year:1813,yearApprox:false,dim:"politics",weight:3,title:"赖兴巴赫公约与奥地利参战",summary:"梅特涅以调停为幌子争取时限，奥地利倒向第六次同盟。",detail:{background:"1813年春奥地利名义中立并主持美因茨/布拉格调停，梅特涅以「武装调停」向拿破仑提出保留其帝号与天然疆界为条件的最后通牒式方案。",process:"1813年6月27日英国与奥地利在赖兴巴赫签订补贴公约（英国承诺约每年100万至125万英镑的补助以维持45万奥军；具体数额记载为20先令/人），另与俄国在特拉亨贝格约定共同作战计划；8月12日（一说16日停战期满）奥地利对法宣战，8月27至29日布拉格会议破裂。",impact:"奥地利的参战把第六次同盟的兵力上限推高到联军可承受会战的程度，也使梅特涅成为战后秩序的主要设计者；其「先打垮拿破仑、再约束俄国」的双重目标，定义了此后奥地利外交的基本坐标。",figures:["梅特涅","弗朗茨一世","卡苏尔雷子爵","巴克莱·德托利"],place:"西里西亚赖兴巴赫／布拉格",state:"奥地利／英国／俄国",sources:["《近代国际条约集》","A. J. P. Taylor, The Habsburg Monarchy 1815–1918"],tags:["同盟","补贴","外交"]},related:["world--1813--m01"]},
  {id:"world--1813--m04",track:"world",year:1813,yearApprox:false,dim:"military",weight:3,title:"泰晤士河战役与特库姆塞阵亡",summary:"英印联军溃败于安大略，西北印第安同盟就此瓦解。",detail:{background:"1812年战争初期美军未能攻下加拿大，英国依靠肖尼族领袖特库姆塞组织的印第安同盟在西北边境牵制美军；1813年9月10日佩里在伊利湖获胜，切断安大略湖补给线。",process:"1813年10月5日，亨利·普罗克特率英军与印第安盟军自底特律方向北撤，在摩拉维亚镇（今安大略境内）附近的泰晤士河遭美军沃温德部追击，英军大部投降（约500人），特库姆塞率部断后并阵亡，其遗体被美军剥皮示众，引起英国国内与后来的印第安史叙述长期争议。",impact:"特库姆塞之死终结了跨部落的武装抵抗联盟，1814年杰克逊在霍斯舒本（3月27日）击溃克里克红棍派、1815年《杰克逊堡》与《绿山堡》条约使克里克与肖尼割让今阿拉巴马与佐治亚大部土地，美国向西北与南部的扩张失去主要障碍。",figures:["特库姆塞","亨利·普罗克特","威廉·亨利·哈里森","伊利·皮尔索尔"],place:"上加拿大泰晤士河畔摩拉维亚镇",state:"英国／美国／肖尼族等印第安同盟",sources:["Alan Taylor, The Civil War of 1812 (2010)","《剑桥北美印第安人史》"],tags:["北美","原住民","1812年战争"]},related:["world--1812--m05"]},
  {id:"world--1813--x01",track:"world",year:1813,yearApprox:false,dim:"explore",weight:3,title:"越过蓝山",summary:"三人探险队翻出新南威尔士蓝山，打开内陆牧场。",detail:{background:"1788年殖民初期，悉尼以西的蓝山断绝了牧场扩展，殖民当局悬赏寻找可通过路线，此前多次勘查皆败。",process:"1813年5月11日至31日，格雷戈里·布莱克斯兰、威廉·劳森与温特沃斯（另有三名仆人）沿中分山脉的峡谷向上攀爬，约21天、前进约60英里（约97公里），抵达今日所谓芒特巴瑟斯一带，见到开阔的牧草平原与（当时干涸的）麦夸里河上游；6月报告呈递总督麦克夸里。",impact:"消息传开后殖民地牲畜迅速西移，1815年建成跨越蓝山的通车道路、1817年设巴瑟斯镇；内陆扩张使羊毛产量在1820至1840年代激增（羊毛至1840年代占英国进口羊毛的一半以上），同时把达鲁格等原住民土地卷入强制占用，边疆冲突持续数十年。",figures:["格雷戈里·布莱克斯兰","威廉·劳森","威廉·温特沃斯","拉克伦·麦克夸里"],place:"新南威尔士蓝山、巴瑟斯",state:"英国（新南威尔士殖民地）",sources:["Blaxland《1813年越过山脉之旅》(1823)","《剑桥澳大利亚史》"],tags:["探险","澳大利亚","牧场"]},related:[]},
  {id:"world--1813--p02",track:"world",year:1813,yearApprox:false,dim:"politics",weight:3,title:"拉普拉塔制宪会议与废除贵族头衔",summary:"联合省大会废除象征旧制的头衔，推进共和化立法。",detail:{background:"1810年后拉普拉塔以「临时执政会」代行主权，1812年10月8日三头执政上台（卡斯特利、巴尔卡尔维、里瓦达维亚），各省对立加剧。",process:"1813年1月31日制宪大会在布宜诺斯艾利斯开幕，代表来自联合省各省；10月宣布取消「堂」「骑士」等贵族与世袭称号，1814年又规定长子继承财产禁令，1816年图库曼宣言即由其后续会议作出。",impact:"这次会议与立法使拉普拉塔从「以斐迪南七世之名统治」转为公开的共和表述，废除称号与限嗣继承的条款切断了殖民时期精英再生产的法律基础，但布宜诺斯艾利斯与联邦派（阿蒂加斯、阿蒂加斯同盟）的分裂延续到1850年代。",figures:["赫瓦西奥·安东尼奥·德·波萨达斯","贝尔纳迪诺·里瓦达维亚","卡洛斯·马里亚·德·阿尔韦亚尔"],place:"拉普拉塔联合省布宜诺斯艾利斯",state:"拉普拉塔联合省",sources:["《剑桥拉丁美洲史》卷三","《1813年制宪大会法令》"],tags:["制宪","阿根廷","共和"]},related:["world--1816--p01"]},
  {id:"world--1813--p03",track:"world",year:1813,yearApprox:false,dim:"politics",weight:2,title:"阿蒂加斯与东岸同盟",summary:"乌拉圭东岸省提出联邦自治，与布宜诺斯艾利斯决裂。",detail:{background:"1811年5月阿蒂加斯在拉斯彼德拉斯击败西班牙守军，成为东岸省民军领袖；1812年后与布宜诺斯艾利斯的中央集权路线冲突公开化。",process:"1813年4月至6月，阿蒂加斯拒绝向制宪大会派出代表，1813年至1815年提出以省为单位的联邦同盟方案（1815年4月正式宣告东岸自由人同盟），1816至1820年面对葡萄牙自巴西北入侵，1820年塔夸伦博战役失败后流亡巴拉圭。",impact:"这次决裂确立了乌拉圭政治中联邦-中央对立的结构，1825年三十三人起义、1828年《蒙得维的亚和约》使东岸成为英国调停下缓冲国；阿蒂加斯被尊为乌拉圭国父，其1815年土地法令的分配争议延续至19世纪。",figures:["何塞·赫瓦西奥·阿蒂加斯","曼努埃尔·贝尔格拉诺"],place:"乌拉圭东岸省蒙得维的亚一带",state:"拉普拉塔联合省（东岸同盟）",sources:["【《剑桥拉丁美洲史》卷三】载阿蒂加斯联邦派与布宜诺斯艾利斯决裂的经过","【《牛津拉丁美洲史》】论东岸省（今乌拉圭）的自治运动"],tags:["联邦主义","乌拉圭","独立运动"]},related:["world--1828--p02"]},
  {id:"world--1814--p01",track:"world",year:1814,yearApprox:false,dim:"politics",weight:5,title:"拿破仑第一次退位",summary:"联军入巴黎后皇帝退位，被安置于厄尔巴岛。",detail:{background:"1814年1月起联军六路越莱茵河，拿破仑以约7万对20余万在法国境内打「六日战役」，但塔列朗与参政院转向、约瑟夫放弃巴黎（3月31日），4月1日元老院宣布废帝。",process:"1814年4月6日拿破仑在枫丹白露签署退位诏书（先为子代退、后改为无条件），4月11日《枫丹白露条约》确认其为厄尔巴岛主权君主、享100万法郎年金并保留帝国称号，皇后与罗马王赴奥地利；4月20日他离开枫丹白露前往厄尔巴岛，28日抵地中海港口弗雷瑞斯，随后登船抵达费拉约港；5月2日与30日签订巴黎和约，波旁王朝复辟。",impact:"退位结束了二十二年连续战争的第一阶段，把「个人主权」问题留给1815年与此后整个世纪；1814年和约的宽大（不割让本土、无赔款）与1815年的严苛形成对照，成为「百日」得以发生的社会条件。",figures:["拿破仑一世","塔列朗","亚历山大一世","路易十八","玛丽·路易丝"],place:"法国枫丹白露／厄尔巴岛",state:"法兰西第一帝国／第六次反法同盟",sources:["《枫丹白露条约》（1814年4月11日）","《拿破仑书信集》"],tags:["退位","复辟","厄尔巴"]},related:["world--1815--p02"]},
  {id:"world--1814--m01",track:"world",year:1814,yearApprox:false,dim:"military",weight:3,title:"六日战役与巴黎陷落",summary:"拿破仑以少胜多重创布吕歇尔，仍无法阻止联军入城。",detail:{background:"1814年战役拿破仑以约5万至7万机动兵力对付20万以上联军，必须依赖内线速胜；但增援被截、士兵多为新兵。",process:"1814年2月10日至14日，拿破仑在尚波贝尔（10日）、蒙米拉伊（11日）、蒂埃里堡（12日）、沃尚（14日）连续击败布吕歇尔的西里西亚军团，四日歼灭普军约2万至3万人；但2至3月联军在南线施瓦岑贝格与北线贝纳多特的持续合压下逼近巴黎，3月17日拉洛特、3月23日阿尔西、25日至30日内苏瓦松与拉奥等地接连失陷，3月30日（一说31日）巴黎守军投降，俄普军入城。",impact:"巴黎的陷落使参政院与塔列朗取得议和主导权，拿破仑的军事胜利失去政治基础；3月31日联军宣布不再与拿破仑及其家族交易，4月6日退位成为唯一出路。",figures:["拿破仑一世","布吕歇尔","施瓦岑贝格","塔列朗","奥古斯特·马尔蒙"],place:"法国香槟地区、巴黎",state:"法兰西第一帝国／第六次反法同盟",sources:["《拿破仑的战役》钱德勒","《剑桥法国史》"],tags:["战役","巴黎","内线"]},related:["world--1814--p01"]},
  {id:"world--1814--i01",track:"world",year:1814,yearApprox:false,dim:"institution",weight:3,title:"一八一四年宪章",summary:"复辟王朝以钦定宪章保留革命与帝国制度主要成果。",detail:{background:"1814年4月塔列朗主张以宪章为条件迎回路易十八，5月3日和约承认法国疆界回到1792年，波旁需要一份可让新制度延续的文本。",process:"1814年6月4日公布《王国宪章》共76条：国王为国家主权与立法动议的唯一来源、两院（贵族院由国王任免、众议院由纳税选举人按1812年选举法选出、年满四十岁且纳税千法郎以上者方可当选），同时确认法律面前平等、出版自由（附限制法）、信仰自由的公民保障、革命期间售出教产不可追回（第9条）、帝国与革命时期的资历、职务与勋章继续有效。",impact:"宪章把复辟王朝纳入立宪形式，但其主权来源于国王钦定的逻辑埋下冲突：1820年选举法修改、1826年长子继承法、1830年七月敕令与再次的七月革命皆源于此，1830年修订版删去「钦定」表述。",figures:["路易十八","塔列朗","德卡兹"],place:"法国巴黎",state:"法国（波旁复辟）",sources:["【《1814年宪章》原文】第1至12条确认代议制与选举资格","【基辛格《复辟的世界》（1957年）】论宪章与正统原则的配合"],tags:["宪章","复辟","立宪"]},related:["world--1830--p01"]},
  {id:"world--1814--p02",track:"world",year:1814,yearApprox:false,dim:"politics",weight:3,title:"一八一四年巴黎和约",summary:"反法同盟与复辟法国媾和，疆界回到1792年。",detail:{background:"拿破仑退位后，同盟内部在波兰-萨克森问题上争执，英国与奥地利急于把和约与维也纳会议的领土安排分开处理。",process:"1814年5月30日至31日（塔列朗-卡苏尔雷、梅特涅、施塔基奥姆、哈敦贝格、涅谢尔罗德等），法国与英、俄、奥、普、瑞典、西班牙、葡萄牙签约：法国保留1792年1月1日疆界（含萨瓦、尼斯与部分属地）、归还大部分殖民地占领地但马耳他归英、爱奥尼亚群岛成保护国，各缔约方放弃战时赔款、法国不付赔款，并承诺于两年内撤军，另约定召开全体会议的维也纳继续处理。",impact:"宽大的条件使复辟政权得以稳定国内财政，也把法国重新纳入大国协调；但殖民地归还范围（塞内加尔、圭亚那、马提尼克、留尼汪等）与放弃毛里求斯、塞舌尔、好望角等，实际上确定了十九世纪的殖民分治格局。",figures:["塔列朗","卡苏尔雷子爵","梅特涅","涅谢尔罗德"],place:"法国巴黎",state:"法国（波旁复辟）／第七次同盟前各盟国",sources:["《近代国际条约集》","《剑桥法国史》卷三"],tags:["和约","疆界","殖民地"]},related:["world--1815--p04"]},
  {id:"world--1814--p03",track:"world",year:1814,yearApprox:false,dim:"politics",weight:4,title:"基尔和约与挪威宪法",summary:"丹麦被迫割让挪威，挪威以独立宪法接受联合王位。",detail:{background:"1807年哥本哈根遭英军炮轰后丹麦与法国结盟，拿破仑失败使其失去一切谈判余地；贝尔纳多特以取得挪威为核心目标。",process:"1814年1月14日（英俄调停下），瑞典-英国联军与丹麦在基尔签约：丹麦国王腓特烈六世将挪威割让给瑞典国王，和约同时确认丹麦本土与属地不受侵犯，并由英国提供补贴、俄军施压促成。挪威方面拒绝承认：4月10日至5月17日埃兹沃尔制宪会议通过以美国与法国文本为参照的《挪威王国宪法》（5月17日签署），选出丹麦王储克里斯蒂安·弗雷德里克为国王。",impact:"5月17日宪法使挪威成为当时欧洲最自由的宪法之一（保留教会国家条款、土地与官员制度），也为瑞挪联合（11月4日联盟条例）设置了内部自治边界；1905年挪威和平解散联盟时，所依据的仍是这部1814年宪法。",figures:["让-巴蒂斯特·贝尔纳多特","克里斯蒂安·弗雷德里克","尼尔斯·维勒","赫曼·韦塞尔·韦瑟坎普"],place:"丹麦基尔／挪威埃兹沃尔",state:"瑞典／丹麦-挪威／挪威",sources:["【《基尔条约》（1814年1月14日）】第1条挪威割让条款","【《挪威王国宪法》（1814年5月17日）】原文八章正文"],tags:["挪威","宪法","领土割让"]},related:["world--1905--p01"]},
  {id:"world--1814--m02",track:"world",year:1814,yearApprox:false,dim:"military",weight:3,title:"英军焚毁华盛顿",summary:"罗斯远征军报复式焚烧联邦公建，首都政府一度离散。",detail:{background:"1814年欧洲战事结束，英国得以从半岛与本土抽调兵力；罗斯与科伯恩奉命在切萨皮克湾发动牵制性远征，同时为1813年美军焚烧约克（多伦多）寻求报复。",process:"1814年8月24日，罗斯率约4500人在布拉登斯堡击溃美军（此役被讥为「布拉登斯堡赛跑」），24日至25日纵火烧毁国会大厦（含图书馆与拱顶）、总统府、财政部、战争部与海军工厂，专利局因索恩顿请求而免于焚毁；麦迪逊与内阁逃至弗吉尼亚，多尔利·麦迪逊抢出华盛顿肖像。",impact:"这次焚烧是美国首都唯一一次被外国军队占领，它使美英谈判立场转向、也强化了战鹰派「二次独立」叙事；1815年《根特条约》批准文本以维持战前边界为内容，双方互不索赔。",figures:["罗伯特·罗斯","科伯恩","詹姆斯·麦迪逊","多尔利·麦迪逊","威廉·桑顿"],place:"美国华盛顿哥伦比亚特区",state:"英国／美国",sources:["【艾伦·泰勒《1812年战争：美国的第二次独立战争》（2010年）】记英军焚城的决策与执行过程","【英国陆军部档案】载1814年切萨皮克湾远征的命令与回报"],tags:["焚烧","1812年战争","首都"]},related:["world--1814--m03"]},
  {id:"world--1814--m03",track:"world",year:1814,yearApprox:false,dim:"military",weight:3,title:"巴尔的摩之战",summary:"英军水陆并进受挫，罗斯阵亡、舰队停止炮击。",detail:{background:"焚毁华盛顿后罗斯与科伯恩拟夺取巴尔的摩这一私掠船基地与粮港，1814年8月起在切萨皮克湾集结约50艘舰船与4700名陆兵。",process:"9月12日罗斯在诺斯角战斗中阵亡（被美军狙击手击毙），布鲁克接任地面部队指挥后行军受阻；9月13日至14日英舰以炮艇与康格里夫火箭轰击帕特普斯克岛的麦克亨利堡，因水深与炮台还击而未能突破，14日晨英军撤围，堡上十五星十五道的巨旗在炮火后仍悬挂。",impact:"英军这次攻势的失败极大提振美方士气，成为《根特条约》前美国最重要的防御性胜利；战役中飘扬的旗帜使斯孔特·凯伊写下诗篇，该曲1931年被定为美国国歌。",figures:["罗伯特·罗斯","塞缪尔·帕肯汉","科伯恩","弗朗西斯·斯科特·基"],place:"美国马里兰州巴尔的摩、麦克亨利堡",state:"英国／美国",sources:["《1814年巴尔的摩战事记录》（美海军部档案）","Alan Taylor, The Civil War of 1812 (2010)"],tags:["战役","私掠","防御"]},related:["world--1814--a01"]},
  {id:"world--1814--a01",track:"world",year:1814,yearApprox:false,dim:"art",weight:2,title:"《星条旗》词作写成",summary:"基目睹麦克亨利堡炮击后作词，后配曲定为国歌。",detail:{background:"律师弗朗西斯·斯科特·基因医治被英军扣押的旧友、医生威廉·毕斯而乘谈判船科霍特号前往巴尔的摩，谈判于9月12日夜间完成后被要求滞留至攻势结束。",process:"9月13日黄昏至14日凌晨英舰队炮击麦克亨利堡，基在船上目睹整夜火光；14日晨见大旗仍在堡上飘扬，遂在科霍特号上写成四节诗《麦克亨利堡防御战》，9月稍后在巴尔的摩以《致酒神徒的歌声》（约翰·斯塔福德·史密斯曲调）印行，1814年10月以《星条旗》为标题流传。",impact:"这首歌在19世纪成为军礼与爱国仪式的常用曲，1917年起由海军与军方推广、1931年3月3日经国会法案正式定为国家国歌，其第三、四节在19世纪反英与后来的政治讨论中常被删略。",figures:["弗朗西斯·斯科特·基","约翰·斯塔福德·史密斯"],place:"美国马里兰州巴尔的摩外港",state:"美国",sources:["【美国1931年国会法案】正式指定《星条旗》为国歌","《星条旗》1814年巴尔的摩初印本"],tags:["国歌","诗歌","1814年"]},related:["world--1814--m03"]},
  {id:"world--1814--p04",track:"world",year:1814,yearApprox:false,dim:"politics",weight:2,title:"瑞挪联盟条例",summary:"挪威以接受联盟换取保留宪法与自治体制。",detail:{background:"1814年夏瑞典对挪威采取军事行动但避免全面战争，8月14日《莫斯公约》承认挪威政府与宪法，10月7日停战期满，挪威议会11月4日表决联盟条例。",process:"1814年11月4日挪威议会（斯托尔廷）以仅一票反对通过《瑞挪联盟条例》，11月9日选贝尔纳多特为瑞典-挪威共同国王卡尔十四世·约翰；条例规定共同外交与王室、但保留挪威议会、行政、军队、货币（挪威银克朗）与国教条款，两国以外交代表共派为摩擦焦点。",impact:"这一双元联盟使挪威在19世纪维持了内部自由化与低军事负担，1884年议会制确立、1905年6月7日挪威议会宣布联盟解体、10月公投请哈康七世为王，全程未发生战争，被视为和平分离的样板。",figures:["卡尔十四世·约翰","克里斯蒂安·弗雷德里克"],place:"挪威克里斯蒂安尼亚（今奥斯陆）",state:"瑞典-挪威联盟",sources:["《瑞挪联盟条例》（1814年11月4日）","【《剑桥斯堪的纳维亚史》】记瑞挪双元联盟的制度安排"],tags:["联盟","挪威","宪制"]},related:["world--1905--p01"]},
  {id:"world--1814--p05",track:"world",year:1814,yearApprox:false,dim:"politics",weight:3,title:"斐迪南七世复辟与宪法废止",summary:"国王在军队与教会支持下取消加的斯宪法，恢复专制。",detail:{background:"1813至1814年间部分省议会与主教联名请愿「恢复旧法」，威灵顿的英军撤离使自由派失去外部支撑。",process:"1813年12月11日《瓦朗索尔条约》使拿破仑释放斐迪南七世并承认其为西班牙国王，1814年3月22日他在加泰罗尼亚登陆、5月4日抵达巴伦西亚，在埃尔切宣布议会决议无效；5月10日（一说4月）在埃莱希奥·伊莱斯·卡列洪将军与主教们的劝进下签署法令，恢复1807年前的专制制度、国家与教会委员会、宗教裁判所与市政特权，1814年5月至1820年间流放与监禁数万名自由派。",impact:"专制复辟使1812年宪法成为自由派殉道与流亡记忆的文本，1820年拉莫列达起义迫使国王重行宪法、1823年法国「十万圣路易」武装干涉再度废除，宪法问题由此转为19世纪西班牙内战式的循环；西属美洲则因宗主国不再立宪而失去效忠理由，独立战争全面展开。",figures:["斐迪南七世","埃莱希奥·伊莱斯·卡列洪","拉斐尔·德尔列戈"],place:"西班牙巴伦西亚、马德里",state:"西班牙",sources:["《1814年5月4日与10日王室法令》","《剑桥西班牙史》"],tags:["复辟","专制","西班牙"]},related:["world--1820--p01"]},
  {id:"world--1814--p06",track:"world",year:1814,yearApprox:false,dim:"politics",weight:3,title:"根特条约",summary:"美英以恢复战前状态缔和，边界与印第安条款落空。",detail:{background:"1814年8月起英美在比利时根特谈判，美方代表亚当斯、加勒廷、贝亚德、克莱因与亨利，英方为哥本哈根伯爵等；战局变化与维也纳会议使英方立场由强硬转为速了。",process:"1814年12月24日签署《根特和约》共10条：双方归还一切征服地、以1783年巴黎和约所定边界为准恢复原状、不处理强征水手与中立贸易（因欧洲战争结束而失效），并设数委员会划界；条约未提及印第安同盟的「屏障国」要求，第9条仅承诺恢复其1811年前权利与领地。",impact:"因消息传递迟缓，1815年1月8日杰克逊在新奥尔取得大捷才被计入战果，美国国内普遍视和约为「体面的平局」；印第安诸族失去英国保障，1815至1830年代西部土地的开放与强制迁移由此加速。",figures:["约翰·昆西·亚当斯","亨利·克莱","詹姆斯·加勒廷","哥本哈根伯爵"],place:"比利时根特",state:"美国／英国",sources:["《合众国法律总汇编》（根特条约批准文本，1815）","Alan Taylor, The Civil War of 1812 (2010)"],tags:["和约","边界","原住民"]},related:["world--1814--m02"]},
  {id:"world--1815--m01",track:"world",year:1815,yearApprox:false,dim:"military",weight:5,title:"滑铁卢战役",summary:"法军在布鲁塞尔南郊被英普联军合击击溃。",detail:{background:"拿破仑3月20日重掌政权后判断必须在俄奥军集结前各个击破联军在比利时的部队，6月15至16日在林尼与四臂村两战分击，但格鲁希未能追住布吕歇尔（18日瓦弗里之战）。",process:"1815年6月18日，拿破仑约7.2万人对威灵顿约6.8万英-荷-德联军在圣让山-滑铁卢一线决战。法军以大规模纵队与骑兵反复冲击乌古蒙庄园、拉海圣与联军中央方队，内伊的骑兵冲锋因缺乏步炮协同而耗尽；下午4时起布吕歇尔的先头部队（齐滕骑兵与皮尔希第一军）自瓦弗里方向到达普军右翼，19时30分左右旧近卫军被击退，法军全线崩溃，损失约2.5至2.8万（另被俘约8000至9000），联军约1.5万、普军约7000。",impact:"次日拿破仑第二次退位（6月22日）、7月8日路易十八回巴黎，百日与二十三年战争终结；滑铁卢与维也纳会议最后文件同周签订（6月9日），使战败条件远较1814年严苛，并确立了以普鲁士崛起与英国霸权为轴心的十九世纪格局。",figures:["拿破仑一世","阿瑟·韦尔斯利","布吕歇尔","米歇尔·内伊","埃曼努埃尔·德·格鲁希"],place:"今比利时瓦弗尔省滑铁卢（拉海圣）",state:"法兰西第一帝国／第七次反法同盟",sources:["【钱德勒《滑铁卢：百日战役》】记战役时序与普军到达时刻","【西博里《1815年法国比利时战史》】据官兵来信统计序列与伤亡"],tags:["战役","滑铁卢","百日"]},related:["world--1815--p02"]},
  {id:"world--1815--p01",track:"world",year:1815,yearApprox:false,dim:"politics",weight:5,title:"维也纳会议最后文件",summary:"列强以条约重建欧陆版图，奠定「维也纳体系」。",detail:{background:"会议自1814年9月开议，塔列朗以「正统原则」介入，波兰-萨克森危机一度使俄奥英与普接近战争边缘，1815年1月3日英奥秘密同盟、2月卡斯尔雷与维特根斯坦的协约使之化解。",process:"1815年6月9日八国（法、英、奥、普、俄、西、葡、瑞典）签署《最后总决议》共121条：俄国取得华沙大公国大部（成立波兰王国）、普鲁士得到萨克森五分之二、莱茵兰与威斯特伐利亚，奥地利取得伦巴第-威尼西亚并主持德意志邦联，意大利其余地区复位；汉诺威升格为王国，瑞士确认中立与22州，瑞典得挪威，荷兰与比利时合并；莱茵河、维斯瓦河等国际河流航行自由；另以专门条款（第124条前的第八议定书与第118条）宣布大西洋奴隶贸易为「违背人道与普遍道德原则」而予废止。",impact:"维也纳体系以均势、正统与协调三原则组织国际关系，避免了1792至1815年式的全面欧战：其集体协商机制延续为「欧洲协调」（1818、1820至1822年的会议体系），但其对民族与宪政诉求的压制亦成为1830与1848年革命的靶子；德意志与意大利的分裂问题、波兰的亡国由此定下长达半世纪的议程。",figures:["梅特涅","塔列朗","卡斯尔雷子爵","亚历山大一世","威廉三世（奥伦治）","斯坦因"],place:"奥地利维也纳",state:"欧洲列强（战后会议）",sources:["《近代国际条约集》（维也纳会议最后总决议）","Kissinger, A World Restored (1957)"],tags:["维也纳体系","均势","领土安排"]},related:["world--1815--i01"]},
  {id:"world--1815--p02",track:"world",year:1815,yearApprox:false,dim:"politics",weight:4,title:"百日王朝",summary:"拿破仑自厄尔巴返回巴黎重掌政权又再度退位。",detail:{background:"维也纳会议期间波兰-萨克森之争、波旁复辟后军人与自由派的不满、英奥财政与征兵争议，为拿破仑提供了返回窗口。",process:"1815年2月26日拿破仑带约千人自厄尔巴岛费拉约港出航，3月1日在儒安湾登陆，经阿尔卑斯山区北进、沿途驻军倒向；3月20日进入杜伊勒里宫，路易十八出奔。5月至6月颁行《帝国宪法附加法》（4月22日）并选举众议院，6月1日「五月广场」集会；滑铁卢战败后6月22日第二次退位，7月3日《圣克卢公约》、7月8日路易十八回巴黎，7月15日在罗什福尔向英舰「柏勒罗丰号」投降。",impact:"百日使拿破仑问题以「不可共存」方式解决：同盟宣布其为个人而非法国之敌，和约条件转为赔款与占领军，1815年11月和约及7月24日军事条约（驻军15万、每年1.5亿法郎、最长5年）确立了战胜方的处置权。",figures:["拿破仑一世","路易十八","吕西安·波拿巴","富歇"],place:"法国戛纳湾儒安至巴黎",state:"法兰西第一帝国（百日）",sources:["《拿破仑书信集》与《帝国宪法附加法》（1815年4月22日）","《剑桥法国史》卷三"],tags:["百日王朝","退位","复辟"]},related:["world--1815--m01"]},
  {id:"world--1815--i01",track:"world",year:1815,yearApprox:false,dim:"institution",weight:4,title:"德意志邦联条例",summary:"三十九邦结为主权邦联，第13条许诺各邦宪政。",detail:{background:"维也纳会议以《最后文件》附件形式设立德意志邦联，梅特涅与普鲁士谈判以维持二元主导与反对任何统一方案。",process:"1815年6月8日《德意志邦联条例》（1815年6月8日颁布，1816年与1819年修订）生效：由奥地利、普鲁士、巴伐利亚、萨克森、汉诺威等39（一说41）个主权邦与4个自由市组成，设联邦议会于法兰克福、奥地利任主席，联邦权限限于共同防御与内部秩序，第13条规定各邦应制定「等级代议制」宪法，但未设立统一公民权、关税或司法。",impact:"邦联把「德意志问题」冻结在主权分裂状态：宪政许诺与现实的落差催生了1817年瓦特堡与1832年哈姆巴赫集会、1819年《卡尔斯巴德决议》审查制度，也为此后1848年法兰克福议会与1866、1871年的两种统一方案提供了共同的谈判对象。",figures:["梅特涅","施塔基奥姆","哈登贝格"],place:"法兰克福（联邦议会）",state:"德意志邦联",sources:["《德意志邦联条例》（1815年6月8日）","Thomas Nipperdey, Germany from Napoleon to Bismarck (1996)"],tags:["邦联","德意志","宪政"]},related:["world--1815--p01"]},
  {id:"world--1815--e01",track:"world",year:1815,yearApprox:false,dim:"economy",weight:3,title:"一八一五年谷物法",summary:"英国立法以价格门槛禁购外国谷物，维护地主利益。",detail:{background:"1815年和平使谷物进口与复员士兵同时涌入市场，1813至1815年粮价由每夸脱约110先令急跌，地主与农场主收入骤减。",process:"1815年2月（2月15日至23日之间三读、上院以投票通过）《谷物进口法》确立：本国小麦价格低于80先令/夸脱时禁止进口，高于则允许；投票中威灵顿的滑铁卢胜利被政府用作号召，下院辩论时伦敦发生「宪政俱乐部」与反谷物法骚乱（2月至3月、5月斯帕菲尔兹事件续发）。",impact:"谷物法使地租与面包价格的矛盾成为19世纪英国政治的核心议题，直接推动1828年滑动税率法与1846年皮尔废除谷物法，并催生了反谷物法同盟（1838年，曼彻斯特）与以工业资本、工人消费利益为诉求的自由贸易共识。",figures:["利物浦勋爵","弗雷德里克·鲁滨逊","威灵顿公爵"],place:"英国伦敦",state:"英国",sources:["Parliamentary Papers, Corn Importation Act 1815","《剑桥欧洲经济史》卷九"],tags:["关税","谷物","地主"]},related:["world--1846--e01"]},
  {id:"world--1815--d01",track:"world",year:1815,yearApprox:false,dim:"disaster",weight:4,title:"坦博拉火山喷发",summary:"印尼火山超级喷发致全球气候异常，酿成跨国饥荒。",detail:{background:"坦博拉位于松巴哇岛，此前长期休眠；1815年4月5日起有征兆，随军与殖民当局记录陆续传来。",process:"1815年4月10日至11日（夜间至次日）发生火山指数7级的超大规模喷发，喷发柱高约43公里，形成约6至7公里宽、数百米深的破火山口；火山灰、浮石与火山碎屑流摧毁松巴哇与龙目岛村落，据后世研究统计，直接死亡约1.1万至1.2万人、计入饥荒与疫病总数约7.1万人；喷出的硫酸气溶胶使1815至1816年全球平均气温下降约0.4至0.7摄氏度。",impact:"1816年成为「无夏之年」：欧洲与北美东部6月降霜雪、瑞士与爱尔兰饥荒、粮食价格暴涨诱发骚乱与移民；此次灾害与同年维苏威、希腊希俄斯岛的疫病与英国粮法危机叠加，成为近代气候-社会研究的基准案例。",figures:["斯坦福·莱佛士（时驻爪哇）","亚历山大·冯·洪堡"],place:"荷属（英占）松巴哇岛坦博拉",state:"印度尼西亚（爪哇总督辖区）",sources:["Behringer, Tambora and the Year Without a Summer (1999)","Oppenheimer, Science (2003)；Smithsonian 全球火山计划档案"],tags:["火山","气候","饥荒"]},related:["world--1816--d01"]},
  {id:"world--1815--f01",track:"world",year:1815,yearApprox:false,dim:"figure",weight:2,title:"拿破仑被流放圣赫勒拿",summary:"英国把被俘前皇帝拘于南大西洋孤岛看管至死。",detail:{background:"1815年7月15日拿破仑在罗什福尔登英舰「柏勒罗丰号」求政治庇护，英国政府拒绝承认其投降身份，决定将其置于最偏远的属地看管以防再逃。",process:"1815年10月15日抵达圣赫勒拿，先居贝尔兰布雷宅邸，12月10日迁至潮湿多风的朗伍德宅；总督哈德森·洛管制其通信与访客（每月限一名）、限制随行人员自由，1818年起蒙托隆夫妇抵达。1821年5月5日拿破仑因胃癌去世，1821年5月9日（原葬于「无名胜之地」）1840年遗骨由路易-菲利普迎回巴黎荣军院。",impact:"流亡把拿破仑变成政治神话：其口述的《圣赫勒拿回忆录》（1823年出版）与「被不列颠与卖国者牺牲」的叙事直接孕育了波拿巴主义，1848年路易-拿破仑以侄孙身份当选总统、1852年称帝。",figures:["拿破仑一世","哈德森·洛","埃马纽埃尔·德·拉斯·卡斯","蒙托隆"],place:"南大西洋圣赫勒拿岛朗伍德",state:"英国（圣赫勒拿殖民地）",sources:["《圣赫勒拿回忆录》（Marchand/Montchenu 日志）","《拿破仑书信集》"],tags:["流亡","人物","记忆政治"]},related:["world--1815--p02"]},
  {id:"world--1815--m02",track:"world",year:1815,yearApprox:false,dim:"military",weight:2,title:"托伦蒂诺战役与那不勒斯王位易手",summary:"奥军四日击溃缪夏军队，那不勒斯回归波旁。",detail:{background:"维也纳会议已把那不勒斯王位许予奥地利体系内的波旁分支；缪拉试图以民族呼吁保住王位。",process:"1815年3月15日缪拉对奥地利宣战（并发表意大利民族呼吁书），率约三至四万那军北上；4月30日至5月3日在托伦蒂诺（马尔凯）与比安奇指挥的奥军激战，5月3日奥军自奥西尼奥方向侧击得手，那军溃退约7000人损失；8月至10月奥军进入那不勒斯，10月缪拉在卡拉布里亚被俘枪决（一说10月13日），1815年6月4日维也纳条约确认斐迪南四世复位（称斐迪南一世）。",impact:"这次失败使意大利统一运动的第一次「军事-民族」尝试归于流产，也确立了奥地利对伦巴第-威尼西亚与对那不勒斯的实际支配，1815至1821年的烧炭党起义与1821年皮埃蒙特、1831年中部意大利起义皆以此为对立面；1860年的两西西里征服可视为其最终清算。",figures:["若阿基姆·缪拉","弗雷德里克·比安奇","斐迪南一世"],place:"马尔凯托伦蒂诺",state:"两西西里王国／奥地利",sources:["《近代国际条约集》（1815年6月4日奥地利-那不勒斯条约）","《剑桥意大利史》"],tags:["战役","意大利","复辟"]},related:["world--1815--p01"]},
  {id:"world--1815--i02",track:"world",year:1815,yearApprox:false,dim:"institution",weight:3,title:"维也纳会议宣布废止奴隶贸易",summary:"八国在总文件中宣布贩奴违背人道原则，但未订执行期。",detail:{background:"英国以1807年本国废奴与1808年起的海军查缉为筹码，在会议中推动普遍性禁令；卡斯雷尔以不签和约相胁，葡西与法国各有拖延。",process:"1815年2月8日（第八议定书）与3月（第15议定书）先后通过宣言，最后写入6月9日《总决议》第118条：与会诸国认为延续自非洲贩买黑人「违背人道与普遍道德原则」，承诺以其所属臣民逐步废止贩奴；但仅规定各国按自身情形「尽快」谈判，未设时间表，荷兰、瑞典即时废、法国承诺五年、西班牙与葡萄牙至1820年前后仅止于限缩航区。",impact:"宣言把废奴写进欧洲国际法话语，形成此后以双边查缉条约、混合委员会法院与「文明标准」施压的合法性基础；但无强制条款使实际效果有限，巴西与古巴的贩奴航线至1830与1850年代才被英以炮舰与《皮尔逊法案》式的强制手段终结。",figures:["卡斯尔雷子爵","梅特涅","塔列朗","威灵顿公爵"],place:"奥地利维也纳",state:"欧洲列强（维也纳会议）",sources:["《维也纳会议最后文件》第118条与第八议定书","《剑桥大英帝国史》卷二"],tags:["废奴","国际法","人权"]},related:["world--1807--e01"]},
  {id:"world--1815--p03",track:"world",year:1815,yearApprox:false,dim:"politics",weight:3,title:"神圣同盟宣告成立",summary:"三皇以基督教兄弟之谊为欧陆干预提供原则依据。",detail:{background:"亚历山大一世此时转向虔信派神秘主义，主张以宗教原则取代马基雅维里式外交；英、教宗与奥斯曼拒绝加入，梅特涅私下称之为「空洞的噪音」。",process:"1815年9月26日（一说9月14/26日）俄皇亚历山大一世（文本起草者）、奥皇弗朗茨一世与普王腓特烈·威廉三世在巴黎圣母院签署《神圣同盟宣言》：三位君主以上帝之名结为基督教兄弟，承诺彼此援助、并依「正义、仁爱与和平」原则治理内政与外交，文本未设机构、成员与表决程序。",impact:"虽无约束力，神圣同盟与11月的四国同盟结合成「干涉原则」的舆论框架：1820至1823年间那不勒斯、皮埃蒙特与西班牙革命皆由同盟体系（1821年莱巴赫、1822年维罗纳会议）依法干预，成为自由派眼中「欧洲反动」的象征。",figures:["亚历山大一世","弗朗茨一世","腓特烈·威廉三世","梅特涅"],place:"法国巴黎",state:"俄国／奥地利／普鲁士",sources:["《神圣同盟宣言》（1815年9月26日）","《剑桥奥地利史》/Taylor, The Habsburg Monarchy"],tags:["同盟","干涉","正统"]},related:["world--1815--p04"]},
  {id:"world--1815--p04",track:"world",year:1815,yearApprox:false,dim:"politics",weight:4,title:"四国同盟与欧洲协调",summary:"英奥普俄以条约把会议机制固定为定期协商。",detail:{background:"为防止法国再度扩张与拿破仑个人影响，同盟需超越一次性安排的制度化机制。",process:"1815年11月20日英、奥、普、俄在巴黎签订《四国同盟条约》共六条：维持1814年巴黎和约与维也纳最后文件所定疆界，任何一方受攻击时四国各出15万兵相互援助，约定以「共同会议」定期协商并（第6条）开放他国加入；同日正式对法签订第二次巴黎和约，1818年亚琛会议接纳法国与萨丁尼亚为五国。",impact:"这一机制（史称「欧洲协调」或会议制度）在1818、1820、1821、1822、1854年间实际避免了欧洲大国总开战，是19世纪集体安全的最早实践；1823年后因英奥在西班牙与东方问题上分歧而松动，1853至1856年克里米亚战争标志其终结。",figures:["卡斯尔雷子爵","梅特涅","亚历山大一世","哈登贝格","威灵顿公爵"],place:"法国巴黎",state:"英国／奥地利／普鲁士／俄国",sources:["《四国同盟条约》（1815年11月20日）","《近代国际条约集》"],tags:["同盟","协调机制","集体安全"]},related:["world--1815--p03"]},
  {id:"world--1815--p05",track:"world",year:1815,yearApprox:false,dim:"politics",weight:3,title:"第二次巴黎和约",summary:"法国失去1792年以来占领地并负担赔款与占领军。",detail:{background:"滑铁卢后同盟内部分歧于惩罚强度：普鲁士主张割让勃艮第与莱茵左岸、英奥则要求保留法国完整以维均衡。",process:"1815年11月20日法国（塔列朗与吉耶努瓦公爵）与英、俄、奥、普签订和约：法国疆界退回1815年1月1日（失去萨瓦部分与朗道、萨尔路易等17个要塞地带，赔款7亿法郎、另付1.5亿用于要塞工程、并归还拿破仑劫掠的艺术品（约5000件）），盟军（威灵顿为总司令）最多15万人占领东北诸省最长五年，并确认1815年3月20日关于废止奴隶贸易的宣言。",impact:"严苛条款使法国「1815年创伤」进入政治记忆，1818年10月亚琛会议后提前撤军（11月30日）成为复辟王朝唯一的对外成就之一；赔款与艺术归还改变了欧洲博物馆与债权国关系的格局，1919年凡尔赛和约的处置常被史家与之比较。",figures:["塔列朗","威灵顿公爵","梅特涅","亚历山大一世","卡斯尔雷子爵"],place:"法国巴黎",state:"法国／第七次反法同盟",sources:["《第二次巴黎和约》（1815年11月20日）","《近代国际条约集》"],tags:["和约","赔款","占领"]},related:["world--1815--p01"]},
  {id:"world--1815--i03",track:"world",year:1815,yearApprox:false,dim:"institution",weight:2,title:"波兰王国宪章颁布",summary:"亚历山大一世为波兰王国颁给较自由宪章，二元安排确立。",detail:{background:"维也纳会议以俄皇兼任波兰国王的方式解决华沙大公国归属，俄方需一份可安抚波兰贵族与西方舆论的文本。",process:"1815年（宪章于6月制定、11月18日正式生效）《波兰王国宪法》规定：两院制议会（参院由国王任命、众院半数由地方贵族选举、半数由选民选出）、国王须为天主教徒且为俄皇兼任、公民自由与出版不受审查（附事后限制）、军队与行政体系独立于俄国、1791年五三宪法的精神被承认但无实效；1819年起以审查与军事审判事实上停用宪政条款，1832年起草组织法取消议会。",impact:"宪章使波兰问题成为19世纪欧洲自由主义的国际议题，1830至1831年十一月起义与1863年起义都以「违反宪章」为由，俄国把起义后果转为直接统治（1832年组织法、1867年维斯瓦边区），1918年复国时的宪政传统由此上溯。",figures:["亚历山大一世","恰尔托雷斯基公爵","斯塔希茨"],place:"波兰华沙",state:"俄国（波兰王国）",sources:["《波兰王国宪法》（1815年11月18日）、《近代国际条约集》","《剑桥波兰史》"],tags:["宪章","波兰","二元制"]},related:["world--1830--p02"]},
  {id:"world--1815--m03",track:"world",year:1815,yearApprox:false,dim:"military",weight:2,title:"法军投降与联军进入巴黎",summary:"达武与富歇以《圣克卢公约》有条件撤军，波旁重登位。",detail:{background:"滑铁卢后法军退入巴黎近郊（7月初），众议院与军队中仍有继续作战的要求，达武任陆军大臣、富歇掌警政与政府。",process:"1815年6月29日至7月3日法军在拉瓦瓦赞与伊塞斯与布吕歇尔、威灵顿谈判，7月3日签订《圣克卢公约》：法军于次日撤出、7月8日前退过卢瓦尔河，人员、装备、车辆与粮秣不受侵犯，国民自卫军保留武装，个人与财产不受追究（普军单独在7月4日攻打了蒙马特尔高地并违反停火）；7月8日路易十八在联军护卫下回到巴黎。",impact:"有条件投降保全了拿破仑时代军队骨干与国家机器，使「两百日」未演变为一场内战式清算，但普军1815至1818年占领东北、以军事法庭对待政治嫌疑者，把巴黎和约条款变成了法国的集体记忆；1815至1816年南方保王派的「白色恐怖」对波拿巴派与军界清洗。",figures:["达武","约瑟夫·富歇","布吕歇尔","威灵顿公爵","路易十八"],place:"法国巴黎、圣克卢",state:"法国／第七次反法同盟",sources:["《圣克卢公约》（1815年7月3日）","《剑桥法国史》卷三"],tags:["投降","占领","复辟"]},related:["world--1815--p02"]},
  {id:"world--1815--e02",track:"world",year:1815,yearApprox:false,dim:"economy",weight:3,title:"英国恢复现金支付法",summary:"战时纸币兑换禁令终止，英镑经四年过渡回到金本位。",detail:{background:"1797年限制兑付令使英格兰银行纸币不再兑换金币，1810年金银报告已主张恢复；1819年《皮尔法案》定出路径，1815年只是立法与舆论推进的第一环。",process:"1815至1819年议会连续辩论金贵问题（黄金派与反黄金派），1816年《铸币法案》（56 Geo. III c.68）确立金索维林为法定货币单位、规定金币与纸币按每盎司3英镑17先令10.5便士比价自由铸造，1819年3月（59 Geo. III c.49）通过：1821年5月起纸币可全额兑换金币，1819年5月至1823年4月为过渡期，英格兰银行先以金条兑换。",impact:"这一路径使英国成为首个以法律形式确立金币本位的国家，1821年后英镑信用为其国际债权与自由贸易提供了货币基础；短期代价是国内物价与农产品价格继续下跌，加剧了1815至1822年农业与工人失业的双重压力。",figures:["罗伯特·皮尔","亨利·桑顿","大卫·李嘉图","塞缪尔·琼斯·劳埃德"],place:"英国伦敦",state:"英国",sources:["【1816年《铸币法案》（56 Geo. III c.68）】确立金币为本位与铸造比价","【1819年《恢复现金支付法》（59 Geo. III c.49）】定1821年为全额兑付期限"],tags:["金本位","英格兰银行","货币"]},related:["world--1810--e01"]},
  {id:"world--1816--p01",track:"world",year:1816,yearApprox:false,dim:"politics",weight:4,title:"图库曼宣言：拉普拉塔独立",summary:"各省代表在图库曼正式宣布脱离西班牙联合省独立。",detail:{background:"1813年制宪大会因内部对立休会，1815年4月阿蒂加斯派击败中央军后，1815年5月阿尔韦亚尔任最高执政，决定召集全境代表大会。",process:"1816年7月9日，各省代表三十余人在图库曼的圣弗朗西斯科教堂开会，大会主席拉普里达主持表决，通过《独立宣言》，声明联合省「脱离西班牙君主制、恢复其被剥夺的自由与主权」，并以费尔南多七世之名仍不可信为由建立共和政府；同年8月9日宣言在布宜诺斯艾利斯宣读。",impact:"图库曼宣言使拉普拉塔在西班牙复辟（斐迪南七世1814年重掌专制）后断绝任何回归可能，为1816至1824年圣马丁翻越安第斯、解放智利与秘鲁提供了法理与兵源基础；1819年中央集权宪法失败后进入罗萨斯时代，1853年联邦宪法才是其最终归宿。",figures:["弗朗西斯科·纳西斯科·德·拉普里达","何塞·德·圣马丁","贝尔纳迪诺·里瓦达维亚"],place:"图库曼（今阿根廷图库曼省）",state:"拉普拉塔联合省",sources:["《图库曼独立宣言》（1816年7月9日）","《剑桥拉丁美洲史》卷三"],tags:["独立宣言","阿根廷","共和国"]},related:["world--1810--p01"]},
  {id:"world--1816--d01",track:"world",year:1816,yearApprox:false,dim:"disaster",weight:3,title:"无夏之年",summary:"坦博拉尘埃使北半球夏季霜雪连降，欧洲与北美粮荒。",detail:{background:"1815年4月坦博拉喷发（另一说1814至1815年间南美火山活动）使平流层硫酸气溶胶遮蔽太阳辐射，1816年成为北半球有记录以来最冷的年份之一。",process:"1816年5至6月瑞士、法国东部、德意志与美国新英格兰出现六月降雪与霜冻（6月6至8日新英格兰结冰，「六月冻杀」），7月阴雨、8月霜降，欧洲谷物1816至1817年连续两季歉收，英国与爱尔兰粮价翻倍、1817年爱尔兰与瑞士发生饥荒与斑疹伤寒（瑞士瓦莱、格劳宾登死亡率显著上升），北美的佛蒙特与俄亥俄出现向密苏里、伊利诺伊的西迁潮；印度与中国的云南、江浙亦在1816至1817年记录低温与粮荒（学界以树轮与文献重建）。",impact:"饥荒与粮价暴涨把1815年谷物法与英国粮荒抗议推向高潮、并促成欧洲马铃薯种植的普遍化与1817年英国济贫与谷物补贴立法；1816年夏天莱茵湖畔的雨也催生了雪莱《黑暗》与玛丽·戈德温《弗兰肯斯坦》，成为气候—文化关联的著名案例。",figures:["珀西·雪莱","玛丽·戈德温","拜伦"],place:"欧洲中部、爱尔兰、美国新英格兰",state:"跨洲气候事件",sources:["【比林格《坦博拉与无夏之年》（Behringer, 1999年德文版、2000年英译本）】以火山冰芯记录、树轮密度与各国日记重建1815年喷发后1816年的北半球降温与欧洲粮荒","【《剑桥欧洲经济史》第九卷（1843—1938年，经济扩张与社会变革）】用于核对1816至1817年欧洲农业歉收、粮价与移民的部门统计"],tags:["气候","饥荒","无夏之年"]},related:["world--1815--d01"]},
  {id:"world--1816--a01",track:"world",year:1816,yearApprox:false,dim:"art",weight:2,title:"《弗兰肯斯坦》构思",summary:"雨夜日内瓦湖别墅的鬼故事游戏催生现代科幻小说雏形。",detail:{background:"1816年夏（无夏之年）珀西·雪莱、玛丽·戈德温（时年18至19岁）、贝尔与波利多里在日内瓦湖畔科洛尼因阴雨闭居，共读德意志奇幻故事集并讨论电击复活之议。",process:"1816年6月中旬（一般认为6月16日至18日间）众人约定各写一篇超自然故事，玛丽·戈德温记下「一个苍白的学子跪在自己拼凑的造物旁」的梦境，随后在1816年冬至1817年春写成小说，1818年1月由伦敦书商匿名出版，1831年再版时加了长序。",impact:"该书确立了「造物反噬其主」与科学责任的叙事母题，被普遍视为科幻小说的起点，其1818年版本中的现代普罗米修斯副题成为此后技术伦理讨论的通用框架；1823年起被不断改编为舞台剧。",figures:["玛丽·戈德温","珀西·比希·雪莱","约翰·波利多里","克莱尔·克莱尔蒙特"],place:"瑞士日内瓦湖畔科洛尼",state:"瑞士（日内瓦州）",sources:["玛丽·戈德温《弗兰肯斯坦》1818/1831年版及其序","《戈德温与雪莱家书集》"],tags:["小说","科幻","浪漫主义"]},related:["world--1816--d01"]},
  {id:"world--1816--p02",track:"world",year:1816,yearApprox:false,dim:"politics",weight:3,title:"英占好望角确立",summary:"荷兰依约让出开普殖民地，英国南进非洲有了锚点。",detail:{background:"1795年与1803年英国两度占领开普，1806年1月布来登贝格战役后成为英国军事管理；1814年8月13日英荷协定规定以100万英镑补偿荷兰让出开普、德梅拉拉、伯比斯与埃塞奎博。",process:"1816年起开普殖民地由英国文官治理（1817年设立法会议、1822年1820年移民计划），讲荷兰语的布尔人保留土地与奴隶制；1828年10月英国宣布废除殖民地奴隶制（1834年生效），1836至1840年代大迁徙由此发生。",impact:"开普成为英国绕好望角航线上唯一的永久补给站，也是19世纪南非殖民扩张的起点；1816年至1867年钻石、1886年兰德金矿的发现使英国资本与布尔人共和国的冲突成为第二次英布战争（1899至1902）的根源。",figures:["查尔斯·萨默塞特"],place:"南非开普敦",state:"英国（开普殖民地）",sources:["【《英荷协定》（1814年8月13日）】以100万英镑补偿荷兰让出开普、德梅拉拉与伯比斯","【《剑桥非洲史》】记开普转为英国文官统治与1828年废除奴隶制的令文"],tags:["殖民","南非","领土"]},related:["world--1899--p02"]},
  {id:"world--1817--m01",track:"world",year:1817,yearApprox:false,dim:"military",weight:3,title:"安第斯军翻越安第斯",summary:"圣马丁率军两周越山，二月查卡布科击溃保王军。",detail:{background:"1814年兰卡瓜战役后保王派重占智利，圣马丁在库约用近两年组建安第斯军，征集骡马、粮秣与向导，主张越山奇袭而非沿海强攻。",process:"1817年1月自门多萨出发，分多路翻越海拔三四千米的山口，主力经乌斯帕亚塔山口，非战斗损失数百人；2月12日在圣地亚哥以北的查卡布科发动晨间突击，一日击溃守军，随后进入圣地亚哥。",impact:"此役使智利爱国者在奥伊金斯重组后重获战场主动，保王军被迫退回秘鲁方向；越山行动成为南美独立战争中最著名的机动战例，也为1818年马伊普决战创造条件。",figures:["何塞·德·圣马丁","贝尔纳多·奥伊金斯"],place:"安第斯山脉乌斯帕亚塔山口、智利查卡布科",state:"拉普拉塔联合省／智利",sources:["【《剑桥拉丁美洲史》卷三】记安第斯军的组建与越山路线","【林奇《西班牙美洲革命1808—1826》】论圣马丁的越山战略"],tags:["越山","独立战争","机动"]},related:["world--1810--p03", "world--1816--p01"]},
  {id:"world--1817--d01",track:"world",year:1817,yearApprox:false,dim:"disaster",weight:3,title:"第一次霍乱大流行开始",summary:"孟加拉出现的霍乱随军队与商路扩散至东南亚和俄国。",detail:{background:"霍乱长期地方性流行于恒河下游与孟加拉；1817年起，随英属印度军队调动、朝圣与稻米贸易路线，疫情开始跨区域扩散。",process:"1817至1824年的第一次大流行自加尔各答一带扩及印度各地，随后传入暹罗、爪哇、日本与中国东南沿海；1823年经里海—阿斯特拉罕一线进入俄国南部，报告死亡以数十万计（当时登记不全，学界认为实际远高于此）。",impact:"这次流行确立了霍乱的「大流行」形态，1829至1837、1846至1860年又两度波及欧洲与美洲；围绕疫源、隔离与水源的争论推动1851年起巴黎历次国际卫生会议与检疫规则的国际化。",figures:["哈斯廷斯侯爵"],place:"印度恒河三角洲至东南亚、俄国南部",state:"跨洲疫情（英属印度为起点）",sources:["【世界卫生组织霍乱实况简报】对历次大流行年代划分","【《剑桥印度史》】记19世纪疫情与检疫措施"],tags:["霍乱","大流行","检疫"]},related:["world--1831--d01"]},
  {id:"world--1817--s01",track:"world",year:1817,yearApprox:false,dim:"science",weight:2,title:"帕金逊描述震颤麻痹",summary:"伦敦外科医生首次系统描述后来以其命名的疾病。",detail:{background:"19世纪初神经病理学开始以临床观察分类；帕金逊在伦敦近郊行医并业余研究地质与植物学，接触数例震颤与肌强直患者。",process:"1817年出版《震颤麻痹论》，以六例病史描述静止性震颤、肌张力增高、姿势前屈与步态拖曳，指出该病与老年性震颤不同，并提出可用药物试验观察病程；该书篇幅不大，长期未受重视。",impact:"「帕金逊病」的名称在1860年代由夏尔科确立后广为采用，19世纪末对其病理（黑质变性）与20世纪初左旋多巴治疗的发现（1960年代）都建立在这一临床描述之上；它是19世纪神经病学科形成的早期文本之一。",figures:["詹姆斯·帕金逊"],place:"英国伦敦",state:"英国",sources:["【帕金逊《震颤麻痹论》（1817年）】原书","【《剑桥医学史》】记该病的命名与夏尔科的贡献"],tags:["神经病学","临床描述","医学"]},related:[]},
  {id:"world--1818--m01",track:"world",year:1818,yearApprox:false,dim:"military",weight:2,title:"美军入侵西佛罗里达",summary:"杰克逊以追剿印第安人为由攻入西班牙属地佛罗里达。",detail:{background:"1812年战争期间英国曾武装克里克与塞米诺尔人，战后美国种植园主持续要求取得庇护逃亡奴隶的西属佛罗里达；1817年美军越界「追剿」引发外交抗议。",process:"1818年3月至4月，安德鲁·杰克逊率军深入西属佛罗里达，攻占西班牙据点圣马科斯，处死两名协助塞米诺尔人的英国志愿军官，随后占领彭萨科拉并扶植亲美长官；亚当斯政府以「自卫与追剿」为政策辩解。",impact:"军事既成事实直接促成1819年《亚当斯—奥尼斯条约》，西班牙以500万美元为价让出东西佛罗里达；此役也确立美国以「剿匪」名义越界用兵的先例，加剧与东南部各部落的冲突。",figures:["安德鲁·杰克逊","约翰·昆西·亚当斯"],place:"西属佛罗里达圣马科斯、彭萨科拉",state:"美国／西班牙",sources:["【《亚当斯—奥尼斯条约》（1819年2月）】划界与转让条款","【《剑桥美国外交史》】记1818年军事行动与谈判"],tags:["边境","扩张","西班牙"]},related:["world--1819--p01"]},
  {id:"world--1818--m02",track:"world",year:1818,yearApprox:false,dim:"military",weight:3,title:"马伊普战役",summary:"安第斯军一日决胜，智利独立再无逆转可能。",detail:{background:"查卡布科后保王军退守康塞普西翁；1818年3至4月间保王军夜袭坎查拉亚达，击溃爱国军并逼近圣地亚哥，圣马丁收拢溃兵并急调援军。",process:"1818年4月5日两军在圣地亚哥以南的马伊普平原决战，双方各约五千人；爱国军以步兵纵队与骑兵迂回同时施压，战斗至黄昏以保王军溃败告终，保王军伤亡与被俘约二千五百人，爱国军损失约千人（学界估计，双方统计有别）。",impact:"此役终结了西班牙在智利重建主力的可能，1818年智利独立得以巩固并获英国事实上承认；圣马丁随即把战略转向海路进攻秘鲁，1820年自瓦耳帕莱索出发。",figures:["何塞·德·圣马丁","贝尔纳多·奥伊金斯","马里亚诺·奥索里奥"],place:"智利马伊普河（圣地亚哥以南）",state:"智利爱国军／西班牙",sources:["【《剑桥拉丁美洲史》卷三】记兵力与后果","【科利尔与萨特《智利史》】论马伊普后的独立巩固"],tags:["战役","智利","独立"]},related:["world--1817--m01", "world--1810--p03"]},
  {id:"world--1818--p01",track:"world",year:1818,yearApprox:false,dim:"politics",weight:3,title:"亚琛会议与法军撤离",summary:"四国同意提前撤走占领军，法国重返欧洲协调。",detail:{background:"1815年第二次巴黎和约规定占领期与赔款；1818年黎塞留公爵政府已按期缴款并完成军队整编，英国主张以撤军换取法国接受现状。",process:"1818年9月至11月，俄、奥、普君主与英、法代表会于亚琛；会议以条约形式同意把占领期缩短至1818年11月底，法国偿清约定的余款后占领军撤离，12月起普军首先撤退。会议同时拒绝干涉西班牙革命政府，英国内阁因此与亚历山大一世发生公开分歧。",impact:"法国恢复大国席位，1815年的管制安排结束，「欧洲协调」由监督战败国转为常设的多边协商；英国反对以同盟名义干预各国革命的立场，为1820年代不干涉政策定下基调。",figures:["卡斯尔雷","梅特涅","亚历山大一世","黎塞留公爵"],place:"普鲁士亚琛",state:"英、俄、奥、普、法",sources:["【《近代国际条约集》】载1818年亚琛撤军公约","【基辛格《复辟的世界》】论亚琛会议与会议体系的成熟"],tags:["会议体系","撤军","赔款"]},related:["world--1815--p05"]},
  {id:"world--1818--e01",track:"world",year:1818,yearApprox:false,dim:"economy",weight:3,title:"普鲁士废除境内关卡",summary:"1818年关税法统一税区，为德意志关税同盟铺路。",detail:{background:"1815年普鲁士获得莱茵兰与威斯特法伦，新领土与旧邦之间关卡林立、转运成本畸高，农业与新兴工业同时受损。",process:"1818年10月26日《普通关税法》生效：取消境内各邦间的一切关卡，改在国境统一征收进口税，原料税低、制成品税适中，并对易北河等水道保留通行费；1819至1828年普鲁士与黑森、巴伐利亚、萨克森等相继缔结双边关税条约。",impact:"统一税区把普鲁士东部领土与莱茵工业区连成一片，构成1834年关税同盟的直接前提；以经济整合先行、政治统一在后的路径，成为19世纪「德意志问题」的关键解决方式之一。",figures:["卡尔·格奥尔格·马森"],place:"普鲁士柏林",state:"普鲁士",sources:["【1818年10月26日《普鲁士普通关税法》】税则条文","【尼佩代《从拿破仑到俾斯麦的德国》】论关税改革与莱茵资本"],tags:["关税","市场统一","普鲁士"]},related:["world--1834--i01"]},
  {id:"world--1819--x01",track:"world",year:1819,yearApprox:false,dim:"explore",weight:3,title:"萨凡纳号横渡大西洋",summary:"首艘带蒸汽机的船横渡大西洋，但多数航程仍靠风帆。",detail:{background:"美国佐治亚州建造的萨凡纳号1818年下水，装一台小功率单缸蒸汽机与可收放的明轮，船主以「蒸汽辅助帆船」方式尝试跨洋航线。",process:"1819年5月22日自萨凡纳启航，据船方记录与后世研究，全程约29天中仅约八十小时使用蒸汽动力，其余依靠风帆，6月20日抵达利物浦；返航取道好望角，1821年回到纽约后拆去机器改作纯帆船。",impact:"它证明蒸汽机械可在大洋上使用，但煤舱容量与成本使定期跨洋蒸汽班轮无法立即实现，商业班轮要到1838年大西方号与1840年代补给网建成后才成立；此次航行被普遍视为风帆向蒸汽过渡的标志。",figures:["史蒂芬·罗杰斯","莫泽·罗杰斯"],place:"大西洋萨凡纳至利物浦",state:"美国",sources:["【《技术史》近代卷】记萨凡纳号动力与蒸汽使用时数","【迪金森《罗伯特·富尔顿与蒸汽船》】论蒸汽船商业化的阶段"],tags:["蒸汽船","大西洋","过渡"]},related:["world--1807--s01", "world--1838--x01"]},
  {id:"world--1819--p01",track:"world",year:1819,yearApprox:false,dim:"politics",weight:4,title:"卡尔斯巴德决议",summary:"邦联通过审查与大学监督令，德意志自由运动受挫。",detail:{background:"1817年瓦特堡节日与学生协会与公众集会令梅特涅警觉，1819年3月剧作家科策比在曼海姆遇刺，奥地利与普鲁士借此把自由派定性为颠覆力量。",process:"1819年8月在卡尔斯巴德秘密会议拟定方案，11月20日经邦联议会通过六项决议：对报刊与薄册实行事前审查、各邦大学设政府监察官并禁止秘密社团、成立美因茨中央调查委员会，并约定联邦有权派兵进入成员邦协助镇压。",impact:"决议终结了1815年后德意志的宪制期望，学生运动瓦解，自由派退回学术与出版领域；它确立奥地利以联邦主席地位主导德意志内政的手段，压制局面维持到1848年三月革命。",figures:["克莱门斯·梅特涅","奥古斯特·冯·科策比"],place:"波希米亚卡尔斯巴德、法兰克福",state:"德意志邦联",sources:["【《卡尔斯巴德决议》（1819年8月）】审查与大学监督条款","【尼佩代《从拿破仑到俾斯麦的德国》】论决议的政治后果"],tags:["审查","邦联","自由主义"]},related:["world--1817--m01", "world--1848--p02"]},
  {id:"world--1819--p02",track:"world",year:1819,yearApprox:false,dim:"politics",weight:3,title:"彼得卢事件",summary:"曼彻斯特六万人集会要求改革，骑兵冲散致十余人死。",detail:{background:"1815年谷物法与战后失业使兰开夏手工业者贫困，汉蒂·亨特等人主张以大规模和平集会争取普选，托平姆纺织区1818年起为集会传统地点。",process:"1819年8月16日六万余人在曼彻斯特圣彼得广场集会，地方法官宣读驱散令后调骑兵（含第十五骠骑团与当地志愿骑兵团）冲入人群，据当年地方调查与报刊统计死者十余人、伤者数百（各方数字有出入）。",impact:"当局随即以1819年12月「六项法令」禁止大型集会并加重报刊押金，反而促成科比特等人的廉价激进报刊网络；「彼得卢」成为1832年改革法与此后工会运动反复援引的记忆。",figures:["威廉·科比特","汉蒂·亨特"],place:"英国曼彻斯特圣彼得广场",state:"英国",sources:["【1819年曼彻斯特集会调查文件（议会档案）】载死伤与命令链","【霍布斯鲍姆《革命的年代》】论其工人运动意义"],tags:["集会","选举改革","镇压"]},related:["world--1832--p01"]},
  {id:"world--1819--e01",track:"world",year:1819,yearApprox:false,dim:"economy",weight:4,title:"莱佛士取得新加坡",summary:"东印度公司在柔佛海峡设厂，转口贸易港随即成形。",detail:{background:"1818年爪哇归还荷兰在即，英国需在马六甲海峡东口取得立足点以保障对华与对印度航线；印度总督明托勋爵支持莱佛士主动出击。",process:"1819年1月底莱佛士抵达柔佛河口，与天猛公阿都拉曼达成协议，并扶植赛义德·胡先为苏丹；2月6日签订条约，许可公司在新加坡设厂并驻军，荷兰方面抗议但未采取军事行动；1824年《伦敦条约》最终把新加坡划归英国。",impact:"自由贸易港政策使人口与转口量激增，据殖民地统计1819年居民约千余人、1824年约万人、1860年代已达八万余（华人占多数）；新加坡成为英国在马来亚与海峡殖民地体系的核心。",figures:["托马斯·莱佛士","天猛公阿都拉曼","明托勋爵"],place:"新加坡",state:"英国（东印度公司）",sources:["【《剑桥东南亚史》】记1819年条约与开埠经过","【《牛津不列颠帝国史》】论1824年英荷条约的势力划分"],tags:["转口贸易","海峡殖民地","开埠"]},related:["world--1811--e03", "world--1824--e01"]},
  {id:"world--1819--e02",track:"world",year:1819,yearApprox:false,dim:"economy",weight:3,title:"美国1819年恐慌",summary:"土地投机与第二银行紧缩同时逆转，西部进入长期萧条。",detail:{background:"1815至1818年英国工业品涌入与西部土地投机并举，联邦土地按最低单价大量出售，各州银行滥发票据；1818年国会要求第二银行回收自身票据并限期兑付。",process:"1819年第二银行收紧信贷、撤回各州银行票据，夏季起西部与南部出现违约潮；同年3月《公有土地抵押法》未能挽回信心，西部债务监禁案件激增，肯塔基州议会试图延期偿债并被联邦最高法院在1819年达特茅斯学院案与格林案判决中限制州权。",impact:"恐慌首次把大西洋两岸信用周期连在一起：英国1819年的兑付紧缩与美洲农产品价格崩塌同步；美国的反应是暂停西部土地出售的进一步扩张、推进关税保护（1820、1824年关税法），并把「州权对抗金融」的争论留给1830年代的银行战争。",figures:["威廉·克劳福德","约翰·马歇尔"],place:"美国纽约、巴尔的摩、西部各州",state:"美国",sources:["【《剑桥美国经济史》】记1819年恐慌与土地投机","【1819年《公有土地抵押法》】与财政部报告"],tags:["恐慌","土地投机","银行"]},related:["world--1821--e01", "world--1825--e02"]},
  {id:"world--1820--p01",track:"world",year:1820,yearApprox:false,dim:"politics",weight:3,title:"西班牙1820年革命",summary:"军队哗变迫使国王宣誓，加的斯宪法恢复施行。",detail:{background:"1814年斐迪南七世恢复专制并重启宗教裁判所，为运往美洲而集结于加的斯的部队长期欠饷，自由派社团在军官中扩散。",process:"1820年1月1日中校拉斐尔·德尔列戈在卡维索德圣胡安宣布恢复1812年宪法，起义军队向马德里推进，宫廷周边士兵相继倒向，3月7日斐迪南七世宣誓遵守宪法，自由派政府成立并大赦政治犯。",impact:"革命使1812年宪法（其条款亦承认美洲各省代表权）重新生效，并直接动摇西班牙在美洲的军事调度；它同时触发1820至1821年那不勒斯、撒丁的军队立宪运动与俄国十二月党人的密谋，1822年维罗纳会议遂决定武装干涉。",figures:["拉斐尔·德尔列戈","斐迪南七世"],place:"西班牙卡维索德圣胡安、马德里",state:"西班牙",sources:["【《1812年西班牙宪法》】正文与1820年恢复施行令","【《剑桥拉丁美洲史》卷三】论革命对美洲战局的影响"],tags:["军队哗变","宪法","自由三年"]},related:["world--1812--i01", "world--1814--p05"]},
  {id:"world--1820--s01",track:"world",year:1820,yearApprox:false,dim:"science",weight:4,title:"奥斯特发现电流磁效应",summary:"课堂演示中磁针因导线通电而偏转，电磁学由此开端。",detail:{background:"1800年伏打电堆使持续电流可用，关于电、磁、光是否为同一「力」的争论延续；奥斯特自1812年起即持有电与磁相关的假设。",process:"1820年4月在哥本哈根大学的公开演示中，他把导线平行置于磁针上方，通电瞬间磁针偏转，证明电流在周围空间产生磁作用；同年7月以拉丁文短文《关于磁针上电冲突的实验》公布结果。",impact:"消息经阿拉戈在巴黎科学院转述后引发连锁研究：安培在数周内提出平行导线作用定律与电动力学，阿拉戈发现磁化与线圈效应，法拉第由此走向1831年电磁感应；电动机、电报与电力系统皆以此为理论起点。",figures:["汉斯·克里斯蒂安·奥斯特","弗朗索瓦·阿拉戈","安德烈-马里·安培"],place:"丹麦哥本哈根",state:"丹麦",sources:["【奥斯特《关于磁针上电冲突的实验》（1820年）】原始通信","【《牛津现代物理学史》】记安培、法拉第的跟进研究"],tags:["电磁学","实验","发现"]},related:["world--1831--s01", "world--1837--s01"]},
  {id:"world--1821--p01",track:"world",year:1821,yearApprox:false,dim:"politics",weight:4,title:"希腊独立战争爆发",summary:"多瑙河与伯罗奔尼撒同时起义，奥斯曼统治开始瓦解。",detail:{background:"1814年希腊商人在敖德萨成立友谊社，以东正教认同与古典复兴为号召；1820至1821年奥斯曼与阿里帕夏的冲突削弱了对南希腊的控制。",process:"1821年3月伊普斯兰提斯率志愿军进入摩尔达维亚举事，因当地贵族不响应与奥军干预于6月失败；3月25日前后伯罗奔尼撒起义爆发，起义军围困并於10月攻陷的里波利，随后双方屠杀与报复使冲突烈度骤升。",impact:"起义把「东方问题」推入欧陆外交的核心：1826年俄土《阿克曼公约》、1827年伦敦条约与纳瓦里诺海战、1829年阿德里安堡和约与1830年伦敦议定书，最终使希腊获得自治并立君；这是奥斯曼欧洲领土第一次被民族主义运动剥离。",figures:["亚历山大·伊普斯兰提斯","彼得罗斯·马弗罗米尔达利斯","马哈茂德二世"],place:"伯罗奔尼撒、摩尔达维亚雅西",state:"奥斯曼帝国／希腊起义者",sources:["【斯塔夫里亚诺斯《1453年以来的巴尔干》】记起义阶段与列强反应","【《剑桥奥斯曼史》】论希腊问题的国际化"],tags:["民族主义","起义","巴尔干"]},related:["world--1804--p03", "world--1827--m01"]},
  {id:"world--1821--p02",track:"world",year:1821,yearApprox:false,dim:"politics",weight:3,title:"科尔多瓦条约承认墨西哥独立",summary:"伊图尔比德与末任总督签约，新西班牙政权和平交接。",detail:{background:"1820年西班牙自由派革命后，加的斯宪法削减教会与军队特权，新西班牙克里奥尔保守派由拥戴王权转向支持独立。",process:"1821年2月伊图尔比德在伊瓜拉宣布「三保障」纲领（天主教、美洲人与半岛人平等、与立宪帝国联合），随后与游击队会合；8月24日与总督胡安·奥多诺霍签订《科尔多瓦条约》承认墨西哥独立，9月27日三保障军进入墨西哥城。",impact:"墨西哥以较低暴力代价脱离西班牙，1822年5月伊图尔比德称帝建立第一帝国，1824年10月共和宪法取而代之；1823年中美洲各省和平退出墨西哥，成立中美洲联合省。",figures:["阿古斯丁·德·伊图尔比德","胡安·奥多诺霍"],place:"墨西哥科尔多瓦（韦拉克鲁斯州）",state:"墨西哥／西班牙",sources:["【《伊瓜拉计划》与《科尔多瓦条约》（1821年）】条文","【《剑桥拉丁美洲史》卷二】论克里奥尔立场转变"],tags:["独立","条约","克里奥尔"]},related:["world--1820--p01"]},
  {id:"world--1821--p03",track:"world",year:1821,yearApprox:false,dim:"politics",weight:3,title:"大哥伦比亚共和国成立",summary:"卡库塔宪法合并新格拉纳达与基多，玻利瓦尔任总统。",detail:{background:"1819年8月博亚卡战役后玻利瓦尔控制波哥大，主张以统一大共和国对抗西班牙残余并避免省级分散。",process:"1821年6月至8月各省代表在卡库塔开会，8月30日通过《大哥伦比亚共和国宪法》，合并新格拉纳达与基多，设两院制议会与任命参议院，规定渐废奴条款并取消印第安人贡赋；玻利瓦尔任总统，桑坦德尔任副总统。",impact:"这是拉美最早稳定运行的共和宪法之一，但中央集权与联邦制、行政权扩张与文官路线的分歧自始存在；1830年1月「波利瓦利亚大会」未能挽救统一，同年5月大哥伦比亚解体为委内瑞拉、新格拉纳达与厄瓜多尔。",figures:["西蒙·玻利瓦尔","弗朗西斯科·德保拉·桑坦德尔"],place:"新格拉纳达卡库塔",state:"大哥伦比亚共和国",sources:["【《1821年卡库塔宪法》】正文","【《剑桥拉丁美洲史》卷二】论大哥伦比亚的宪制与解体"],tags:["共和宪法","解体","玻利瓦尔"]},related:["world--1819--p02", "world--1824--m01"]},
  {id:"world--1821--p04",track:"world",year:1821,yearApprox:false,dim:"politics",weight:2,title:"奥地利干涉那不勒斯",summary:"俄军未动、奥军入意，立宪在那不勒斯被武力终止。",detail:{background:"1820年7月帕尔马与那不勒斯军队相继哗变，两西西里国王费迪南多一世被迫颁布1812年式宪法；撒丁亦于1821年3月发生立宪政变。",process:"1821年1至3月，神圣同盟特罗保会议（1820年11月起）与莱巴赫会议相继决议由奥地利出兵恢复秩序，3月奥军越过波河，3月23日在诺瓦拉附近击败撒丁立宪军；奥军同时翻越亚平宁山进入那不勒斯，立宪军抵抗失败，国王废除宪法并清洗军官。",impact:"同盟由此确立对意大利的干涉权与奥军驻意体制，皮埃蒙特与两西西里的立宪军官流亡，其中不少人转往希腊与拉美战场；这一先例使1831年与1848年的意大利运动都以「反奥」为核心诉求。",figures:["克莱门斯·梅特涅","费迪南多一世","亚历山大一世"],place:"意大利那不勒斯、皮埃蒙特",state:"奥地利帝国／两西西里王国",sources:["【《莱巴赫会议议定书》（1821年5月）】","【《剑桥意大利史》】论1820至1821年立宪运动与干涉"],tags:["干涉","立宪","意大利"]},related:["world--1820--p01"]},
  {id:"world--1821--e01",track:"world",year:1821,yearApprox:false,dim:"economy",weight:3,title:"英镑恢复金币兑付",summary:"1821年纸币可无限制兑金，英国金本位事实上成立。",detail:{background:"1797年限制兑付令中断金币兑换二十余年，1810年通货委员会报告已主张恢复，1819年《恢复现金支付法》规定1821年起重开兑付，1816年《铸币法案》确立金索维林为本位。",process:"1821年起英格兰银行按每金衡盎司3英镑17先令10.5便士的法定比价无限制兑付金币与金条，过渡期结束；同期农产品与工业品价格继续下跌，工资与实际就业恢复缓慢。",impact:"英国成为第一个在法律与操作层面同时确立金币本位的国家，英镑信用为其国际借贷与自由贸易提供货币基础；紧缩的分配后果（农业衰退与工人失业）则构成1830年代改革与宪章运动的经济社会背景。",figures:["罗伯特·皮尔","大卫·李嘉图"],place:"英国伦敦",state:"英国",sources:["【1819年《恢复现金支付法》】兑付期限条款","【《剑桥欧洲经济史》】论恢复兑付与国内物价"],tags:["金本位","英镑","通货"]},related:["world--1815--e02", "world--1810--e01"]},
  {id:"world--1821--s01",track:"world",year:1821,yearApprox:false,dim:"science",weight:3,title:"法拉第制成电磁旋转装置",summary:"载流导线绕磁体持续旋转，首次实现电能转机械运动。",detail:{background:"奥斯特1820年宣布电流磁效应后，法拉第在皇家研究所立即复现实验，并追问能否把电转化为持续的机械运动而非瞬时偏转。",process:"1821年法拉第完成并公开展示两台装置：一台固定磁棒而使载流导线绕其旋转，另一台使磁体绕固定的载流导线旋转，均以水银槽导电并冷却；同年他把实验结果连同自己的评论刊于哲学期刊。",impact:"这是历史上第一次把电能转化为连续的机械旋转，构成电动机的原理雏形；由于当时缺乏持续电源与工程条件，实用电机要到1830至1840年代才出现，其技术谱系普遍以1821年装置为起点。",figures:["迈克尔·法拉第","汉弗莱·戴维"],place:"英国伦敦皇家研究所",state:"英国",sources:["【法拉第1821年论文与皇家研究所笔记】","【《牛津现代物理学史》】论电磁旋转与电动机谱系"],tags:["电动机","电磁学","演示"]},related:["world--1820--s01"]},
  {id:"world--1821--f01",track:"world",year:1821,yearApprox:false,dim:"figure",weight:2,title:"拿破仑在圣赫勒拿去世",summary:"被囚六年后死于长伍德，死因至今存在医学争论。",detail:{background:"1815年10月起拿破仑被囚于圣赫勒拿岛长伍德，看管官哈德逊·洛与英国当局的经费和通信限制使处境恶化；1821年2月起出现胃部疾患与进行性消瘦。",process:"1821年5月5日下午逝世，终年51岁；随医官奥梅纳与尸检记录称胃部有严重溃疡与邻近组织病变，19世纪后期起出现胃癌、慢性砷中毒等不同解释，主流医学史研究仍以胃部病变为主要死因。",impact:"其去世使波拿巴主义从「在位者」转为记忆与传说：1840年遗骨由凡尔努瓦号运回巴黎、12月15日葬入荣军院，成为路易-菲利普争取军队与民意的政治事件，也为1848至1851年路易·拿破仑的崛起准备了象征资源。",figures:["拿破仑一世","埃马纽埃尔·德·拉斯·卡尔","哈德逊·洛"],place:"圣赫勒拿岛长伍德",state:"英国（看管）／前法兰西帝国",sources:["【拉斯·卡尔《圣赫勒拿回忆录》】记病况与临终","【1821年5月6日尸检记录】（收于相关医学史文献）"],tags:["去世","囚禁","政治记忆"]},related:["world--1815--p01"]},
  {id:"world--1822--p01",track:"world",year:1822,yearApprox:false,dim:"politics",weight:4,title:"巴西宣布独立",summary:"佩德罗拒绝里斯本召回，九月宣告与葡萄牙分离。",detail:{background:"1808年若昂六世避法迁都里约，使巴西地位上升；1820年波尔图革命与1821年葡萄牙立宪政府要求国王归国并恢复巴西的从属地位，里斯本议会与驻里约葡军形成压力。",process:"1821年4月若昂六世回国，皇太子佩德罗留任摄政；1822年1月9日他拒绝里斯本的召回令（「留下日」），5月宣布殖民地可自主缔结条约与关税，9月7日在圣保罗郊外宣布与葡萄牙分离，10月12日加冕为佩德罗一世，1824年3月25日颁行宪法。",impact:"巴西以君主制与相对低烈度的方式脱离母国，避免了西属美洲式的长期分裂与军阀化，但奴隶制与大地产原样延续；1825年在英国斡旋下葡萄牙承认独立，巴西支付补偿金并重续对英关税优惠，英巴1827年条约进一步约定废止奴隶贸易。",figures:["佩德罗一世","若泽·博尼法西奥·德·安德拉达","若昂六世"],place:"巴西伊皮兰加、里约热内卢",state:"巴西帝国／葡萄牙",sources:["【1822年独立宣告文告与《1824年巴西宪法》】","【《剑桥拉丁美洲史》卷二】论承认谈判与对英补偿"],tags:["独立","君主制","奴隶制"]},related:["world--1821--p02", "world--1819--e01"]},
  {id:"world--1822--c01",track:"world",year:1822,yearApprox:false,dim:"culture",weight:3,title:"商博良破译象形文字",summary:"以王名圈与科普特语对照，确立圣书体的语音原则。",detail:{background:"1799年罗塞塔石碑出土后三语对照文本成为关键；1814年后托马斯·扬由世俗体确定若干符号的音值，但未识破其系统结构。",process:"1822年商博良发表《致达西耶先生书》，论证象形文字同时具有表音与表意功能、托勒密与克娄巴特拉等外来王名以音符拼写，并借科普特语重建读音系统；1824年《埃及象形文字语法》将其方法体系化。",impact:"埃及学由此成为可直读原始文献的学科，神庙与墓志铭文进入历史叙述；伴随1828至1830年商博良率法队赴埃考察与卢浮宫埃及馆藏的建立，欧洲文物聚拢与殖民地语境下的考古争议也同步展开。",figures:["让-弗朗索瓦·商博良","托马斯·杨"],place:"法国巴黎、格勒诺布尔",state:"法国",sources:["【商博良《致达西耶先生书》（1822年）】原文","【《剑桥科学史》】记破译过程与方法争论"],tags:["埃及学","语言","碑铭"]},related:["world--1800--s01"]},
  {id:"world--1822--d01",track:"world",year:1822,yearApprox:false,dim:"disaster",weight:2,title:"希俄斯岛大屠杀",summary:"奥斯曼军队攻陷希俄斯后屠掠，岛上人口锐减。",detail:{background:"1821年希腊起义后，希俄斯岛因富裕船东与商人的顾虑起初未加入，1822年3月在起义军压力下参盟，奥斯曼当局视为背叛。",process:"1822年4月奥斯曼海陆部队登陆围城，起义军与岛上民众据守山区；城陷后发生连续屠戮与掳掠，据希腊方面记载与后世研究，战前约十万居民中死亡与被卖为奴者合计达数万（奥斯曼与欧洲各国的统计差异极大，学界至今以区间表述）。",impact:"事件成为欧洲「亲希腊运动」的转折点，德拉克洛瓦1824年以《希俄斯大屠杀》入画、拜伦与志愿军相继东来，并推动英法俄1826至1827年三次介入；它对后来国际舆论干预人道危机的实践提供了早期范例。",figures:["马哈茂德二世"],place:"奥斯曼治下希俄斯岛",state:"奥斯曼帝国／希腊起义者",sources:["【《剑桥19世纪希腊史》／斯塔夫里亚诺斯《1453年以来的巴尔干》】记人口损失的不同统计","【1824年英国议会辩论记录】载欧洲舆论与志愿军问题"],tags:["屠戮","希腊","舆论"]},related:["world--1821--p01", "world--1827--m01"]},
  {id:"world--1823--p01",track:"world",year:1823,yearApprox:false,dim:"politics",weight:4,title:"门罗主义宣示",summary:"美国声明反对欧洲再殖民西半球，同时不干预欧陆事务。",detail:{background:"1822至1823年神圣同盟已干涉那不勒斯与撒丁，法国拟入侵西班牙；俄国1823年照会涉及西北美洲海岸，英国外相坎宁提议美英联合声明以阻止瓜分。",process:"1823年12月2日门罗在年度咨文中阐述四项原则：现存殖民地不得易手、此后欧洲不得在西半球再行殖民、美洲政治体系与欧洲体系分立、美国不干预欧洲各国事务；文本由国务卿亚当斯主导拟定，联合声明的提议被否决而改为单方宣示。",impact:"宣示当时并无军力支撑，其效力实际依赖英国海军对既成状态的默认；19世纪末至20世纪初它被重新解释为美国在西半球独占地位的合法性来源（1904年罗斯福推论），在拉美长期被视为干涉主义的修辞依据。",figures:["詹姆斯·门罗","约翰·昆西·亚当斯","乔治·坎宁"],place:"美国华盛顿",state:"美国",sources:["【门罗1823年12月2日年度咨文】原文","【《剑桥美国外交史》】论亚当斯的决策与英国提议"],tags:["外交","西半球","承认"]},related:["world--1822--p01"]},
  {id:"world--1823--p02",track:"world",year:1823,yearApprox:false,dim:"politics",weight:3,title:"法国武装干涉西班牙",summary:"十万法军恢复斐迪南七世专制，同盟干涉达到顶点。",detail:{background:"1822年10月维罗纳会议在法国提议与俄奥普支持下通过对西干涉决议，英国代表威廉斯拒签并声明不认可；西班牙自由派政府处境孤立。",process:"1823年4月7日法军在昂古莱姆公爵率领下越过比利牛斯（史称「十万个儿子的远征」，实际约六万余人），5月占领马德里，斐迪南七世获救并废除宪政；6月至9月围困加的斯，10月初城陷，自由派政府成员流亡英美。",impact:"专制复辟使西班牙在美洲的最后据点（卡亚俄与圣胡安德里亚克鲁斯）失去立宪背景，1824至1826年残保势力相继投降；干涉也暴露同盟内部裂痕：英国借此明确与欧洲干涉主义分离，转向以海军与条约维护现状。",figures:["昂古莱姆公爵","斐迪南七世","路易·德·维莱尔"],place:"西班牙马德里、加的斯",state:"法国／西班牙",sources:["【《维罗纳会议议定书》（1822年10至11月）】与英国代表的抗议声明","【《剑桥西班牙史》】记干涉军的规模与加的斯陷落"],tags:["干涉","复辟","同盟"]},related:["world--1820--p01", "world--1824--m01"]},
  {id:"world--1824--m01",track:"world",year:1824,yearApprox:false,dim:"military",weight:4,title:"阿亚库乔战役",summary:"高原一日决胜，秘鲁保王军主力覆灭。",detail:{background:"1823年玻利瓦尔进入秘鲁时爱国军连遭挫败、疫病与欠饷严重；保王军由总司令拉塞尔纳率领，试图以兵力优势各个击破。",process:"1824年8月6日胡宁骑兵遭遇战获胜后，玻利瓦尔把前线指挥交给苏克雷；12月9日在瓦曼加平原的阿亚库乔会战，双方各约六千人，保王军伤亡与被俘数千人（学界估计三千至四千，含多名高级将领被俘），爱国军损失约千人。",impact:"战役使西班牙在南美大陆的有组织的军事抵抗终结，1825年上秘鲁独立为玻利维亚，1826年1月卡亚俄最后据点投降；玻利瓦尔的声望达到顶点，也为其后统一政权的尝试埋下军事依赖。",figures:["安东尼奥·何塞·德·苏克雷","西蒙·玻利瓦尔","何塞·德·拉塞尔纳"],place:"秘鲁瓦曼加平原阿亚库乔",state:"秘鲁／大哥伦比亚与西班牙",sources:["【《剑桥拉丁美洲史》卷三】记兵力与俘虏名单","【林奇《玻利瓦尔传》】论战役的战略后果"],tags:["战役","秘鲁","独立"]},related:["world--1821--p03", "world--1823--p02"]},
  {id:"world--1824--e01",track:"world",year:1824,yearApprox:false,dim:"economy",weight:2,title:"伦敦的拉美证券发行热",summary:"新独立共和国债券与矿业股票在伦敦大量上市。",detail:{background:"1822至1824年拉美诸国相继独立并公开举债，伦敦承销商以「新世界」叙事招股；英国战后低利率与出口恢复使可投资本充裕。",process:"1824至1825年，哥伦比亚、墨西哥、秘鲁、智利、布宜诺斯艾利斯等多档债券与十余家矿业公司在伦敦发行上市，股价在1825年上半年数倍上涨；1825年6月起股价回落，12月伦敦批发与银行业接连倒闭。",impact:"崩盘使大量英国家庭储蓄与殖民地财政同时受损，据后世统计1825至1826年破产的银行与商行逾七十家；拉美新独立国家此后长期难以在国际市场融资，1820年代的财政重建计划被迫推迟。",figures:["乔治·坎宁","西蒙·玻利瓦尔"],place:"英国伦敦",state:"英国／拉美新独立国家",sources:["【《剑桥拉丁美洲史》卷二】记1820年代证券发行与崩盘","【《剑桥欧洲经济史》】论1825年危机中的外国债券"],tags:["资本输出","投机","债券"]},related:["world--1825--e02"]},
  {id:"world--1824--e02",track:"world",year:1824,yearApprox:false,dim:"economy",weight:3,title:"英国废除禁止结社法",summary:"国会撤销把工会定为非法的制定法，共谋罪仍留尾巴。",detail:{background:"1799至1800年《结社法》把工人组织视为非法，1822至1824年间苏格兰与约克的审判把「共谋罪」适用于和平罢工，引发激烈抗议。",process:"1824年6月在赫斯基森主持下下院通过废止1799、1800年两法的法案，工会本身不再自动违法；1825年新订《组合法》把合法范围限于协商工资与工时，同时保留对胁迫、恐吓与聚众的刑事处罚。",impact:"法律承认使工会由地下转入公开，1830年前后出现跨地区的工种工会与「全国大团结」运动，并催生1834年的流亡犯事件；1859年《秘密贿赂与胁迫法》与1871、1875年工会立法，仍在这一框架上继续修补。",figures:["威廉·赫斯基森"],place:"英国伦敦威斯敏斯特",state:"英国",sources:["【1824年《废止结社法》与1825年《组合法》】条文","【汤普森《英国工人阶级的形成》】论法律与工人组织的互动"],tags:["工会","立法","劳动"]},related:["world--1811--e01"]},
  {id:"world--1824--a01",track:"world",year:1824,yearApprox:false,dim:"art",weight:3,title:"贝多芬第九交响曲首演",summary:"维也纳首演以合唱入交响，全聋的作曲家未听见掌声。",detail:{background:"贝多芬自1817年前后构思以席勒《欢乐颂》作为交响曲终章，1822至1824年完成第九交响曲；此时其听力已近全失，公开露面极少。",process:"1824年5月7日在维也纳克恩顿门剧院首演，由乌姆林格担任台上指挥、贝多芬在台侧打拍；终章以男中音宣叙调「朋友，不再是这些声音！」引入独唱与合唱，据在场记载结束时观众五次挥帽致意，女低音歌手转身让作曲家看到掌声。",impact:"把声乐纳入交响曲结构，改变了19世纪交响体裁的规模与自我理解，马勒、布鲁克纳的作品与后世「欢乐」主题的政治使用（1989年柏林墙倒塌音乐会、欧盟《欢乐颂》器乐版会歌）都以此为参照。",figures:["路德维希·范·贝多芬","弗里德里希·席勒","米夏埃尔·乌姆林格"],place:"奥地利维也纳克恩顿门剧院",state:"奥地利帝国",sources:["【1824年首演节目单与《音乐广讯报》评论】","【《企鹅古典音乐指南》】记首演经过与乐队编制"],tags:["交响曲","合唱","首演"]},related:[]},
  {id:"world--1825--e01",track:"world",year:1825,yearApprox:false,dim:"economy",weight:5,title:"斯托克顿—达灵顿铁路通车",summary:"首条公共蒸汽铁路投入运营，煤运成本大幅下降。",detail:{background:"1820年代英国东北部煤价与道路运费压力促使业主寻求轨道运输；工程师乔治·斯蒂芬森主张以蒸汽机车牵引，1821年议会法案授权后线路多次修改并改用蒸汽牵引。",process:"1825年9月27日线路通车，斯蒂芬森驾驶「运动号」机车牵引煤车与载客车厢行驶，线路自锡尔顿经达灵顿至斯托克顿，全长约二十六英里；此后正式投入商业运营，客货并行并向承租机车的经营者开放线路。",impact:"它确立了「公共蒸汽铁路＋对外运营」的模式，1830年利物浦—曼彻斯特铁路证明客运盈利后，英国进入铁路投资高潮（据议会统计1850年英国营业里程已近一万公里），煤、铁、肥料与劳动力的运输成本同步下降。",figures:["乔治·斯蒂芬森","爱德华·皮斯"],place:"英国斯托克顿至达灵顿",state:"英国",sources:["【1825年《斯托克顿—达灵顿铁路法》】与通车报道","【《技术史》近代卷】记机车牵引与轨道规格"],tags:["铁路","蒸汽机车","运输"]},related:["world--1804--s01", "world--1830--s01"]},
  {id:"world--1825--e02",track:"world",year:1825,yearApprox:false,dim:"economy",weight:3,title:"1825年英国金融危机",summary:"投机崩盘引发挤兑，乡村银行体系大面积倒闭。",detail:{background:"1824至1825年拉美证券与矿业股投机、乡村银行滥发票据并行；1825年夏谷物歉收与对俄、对法结算造成黄金外流，贴现率上升。",process:"1825年6月起股价回落，12月伦敦多家银行与批发商相继停业并引发挤兑，英格兰银行金属储备急剧下降，靠同业与公众回流的少量黄金与政府存款支撑；据后世统计，1825至1826年英格兰、威尔士与苏格兰破产的银行与合股机构逾七十家。",impact:"危机促成1826年《国银行法》允许在伦敦六十五英里外设立股份银行，并引发1832至1844年的通货论争（金本位与银行券发行规则），最终由1844年《皮尔银行法》确立发行部与准备金的分离原则。",figures:["罗伯特·皮尔"],place:"英国伦敦",state:"英国",sources:["【1826年《股份银行法》】与议会关于乡村银行的调查记录","【《剑桥欧洲经济史》】论1825年危机与银行制度改革"],tags:["金融危机","银行","投机"]},related:["world--1824--e01", "world--1833--p01"]},
  {id:"world--1825--p01",track:"world",year:1825,yearApprox:false,dim:"politics",weight:3,title:"玻利维亚独立建国",summary:"上秘鲁议会宣布独立，新国家以玻利瓦尔命名。",detail:{background:"1824年12月阿亚库乔后，「上秘鲁」（查尔卡斯）的归属在秘鲁与大哥伦比亚之间悬而未决；苏克雷入城并促成本地议会自决。",process:"1825年议会就是否并入大哥伦比亚、秘鲁或独立表决，8月6日通过独立决议，10月以「玻利瓦尔共和国」命名（后改玻利维亚）并尊玻利瓦尔为「国父」，1826年颁布玻利瓦尔主持起草的宪法，设终身参议院与「第四权」。",impact:"新国家继承了波托西银矿衰退与强制劳役传统，财政与领土脆弱，1826至1828年即与秘鲁发生冲突；玻利瓦尔本人1830年去世前承认南美「如同在海上犁地」，其统一设想未能实现。",figures:["西蒙·玻利瓦尔","安东尼奥·何塞·德·苏克雷"],place:"上秘鲁丘基萨卡（今苏克雷）",state:"玻利维亚",sources:["【《独立法案》（1825年）】与《1826年玻利维亚宪法》","【《剑桥拉丁美洲史》卷三】论新国家的财政与继承"],tags:["建国","上秘鲁","命名"]},related:["world--1824--m01"]},
  {id:"world--1825--p02",track:"world",year:1825,yearApprox:false,dim:"politics",weight:4,title:"十二月党人起义",summary:"参政院广场士兵拒绝宣誓，起义在炮火中当日瓦解。",detail:{background:"1812年卫国战争与1813至1814年出国进军使俄国军官目睹欧陆宪政与农奴制的反差；1821至1822年救国同盟成立，北方与南方协会分别主张共和宪法与废除农奴。",process:"1825年11月亚历山大一世去世引发继承空位与宣誓争议，12月14日约三千名士兵被带至彼得堡参政院广场拒绝向尼古拉一世宣誓，政府以骑兵冲击与炮兵霰弹驱散，现场死者数百（官方数字与亲历记述差异较大）；1826年南方协会与切尔尼戈夫团的活动亦被平定。",impact:"1826年7月13日五名领导人被绞死，百余人被判刑流放西伯利亚；赫尔岑由此转向革命宣传，十二月党人被后世俄国运动视为第一代「贵族革命者」，而尼古拉一世的审查、密探与农奴政策保守化自此定型。",figures:["康德拉季·雷列耶夫","帕维尔·佩斯捷利","尼古拉一世"],place:"俄国圣彼得堡参政院广场",state:"俄罗斯帝国",sources:["【救国同盟纲领与1826年审判文件】（收于十二月党人文献集）","【《剑桥俄国史》卷二】论继承危机与镇压后果"],tags:["起义","农奴制","宪政"]},related:["world--1812--m01"]},
  {id:"world--1825--p03",track:"world",year:1825,yearApprox:false,dim:"politics",weight:2,title:"三十三东岸人登陆",summary:"三十余名武装者回返东岸，乌拉圭战争由此开始。",detail:{background:"1816至1820年葡萄牙—巴西军队占领乌拉圭东岸省，1821年并入「西普拉蒂纳省」，1822年巴西帝国延续统治；东岸牧场主与布宜诺斯艾利斯皆图恢复。",process:"1825年4月拉瓦列哈等三十余名东岸人自圣菲省渡河登陆，10月19日在弗洛里达集会宣布东岸省回归拉普拉塔联合省并拒绝巴西主权；11月联合省议会表示支持，12月10日巴西对联合省宣战。",impact:"1825至1828年的西普拉蒂纳战争使双方财政耗尽、贸易封锁，英国利益受损而强力调停；1828年《蒙特维的亚条约》以缓冲国乌拉圭收场，并引发拉普拉塔内部政治重组与罗萨斯在布宜诺斯艾利斯上台。",figures:["胡安·安东尼奥·拉瓦列哈","曼努埃尔·多雷戈"],place:"乌拉圭东岸、弗洛里达",state:"拉普拉塔联合省／巴西帝国",sources:["【《剑桥拉丁美洲史》卷三】记1825年登陆与宣战","【《牛津巴西史》】论战争对巴西财政与海军的消耗"],tags:["战争","缓冲国","东岸"]},related:["world--1828--p02"]},
  {id:"world--1826--p01",track:"world",year:1826,yearApprox:false,dim:"politics",weight:3,title:"巴葡条约承认巴西独立",summary:"葡萄牙以补偿金为代价承认巴西独立，英国居中调停。",detail:{background:"1822年9月佩德罗宣布独立后，巴西以陆军、新建舰队与伦敦借款维持事实独立，葡萄牙宫廷与欧洲列强拒不承认，双方海上互相拿捕船只。",process:"1825年8月29日两国在里约热内卢签订和平公约，1826年葡萄牙批准换文后生效：巴西偿付约200万英镑补偿金（其中相当部分靠在伦敦发行债券筹得），承接葡萄牙在巴西的债务与旧约权利，并延续1810年英葡商约的低税待遇。",impact:"条约给巴西独立画上法理句号，却把国债负担与英国商业特权写进建国条件；此后若昂六世遗产争议、1831年佩德罗一世退位与摄政期动荡都在这一财政与王位结构上展开。",figures:["佩德罗一世","亨利·乔治·沃德"],place:"里约热内卢",state:"巴西帝国／葡萄牙王国",sources:["【1825年8月29日《巴西—葡萄牙和平公约》文本（巴西国家历史档案馆）】核对承认条款、补偿金与换文时间","【《剑桥拉丁美洲史》第二卷】论英国调停与巴西独立初期的财政负担"],tags:["条约","承认","英国调停"]},related:["world--1822--p01", "world--1823--p01"]},
  {id:"world--1826--f01",track:"world",year:1826,yearApprox:false,dim:"figure",weight:2,title:"拜伦病逝米索隆吉",summary:"英国诗人变产支援希腊，死于围城中的热病。",detail:{background:"1823年起英国亲希腊舆论以募款与志愿船支援起义者，拜伦变卖家产购置武装，1823年夏抵达凯法利尼亚岛，随后应邀进入被围的米索隆吉。",process:"拜伦在米索隆吉试图调解苏利奥特武装与地方头目之间的派系冲突，出资整训陆战队并计划突袭土军炮台；未及出战即病倒，1826年4月19日因热病死亡（其治疗中的放血与禁食被后世视为加重因素），年38岁。",impact:"他的死把欧洲亲希腊运动推成不可逆的舆论压力，直接促成1826年4月英俄照会与1827年三国《伦敦条约》；米索隆吉由此成为希腊民族记忆中的圣地，自由派也第一次把诗人塑造为殉道者。",figures:["乔治·戈登·拜伦"],place:"希腊米索隆吉",state:"希腊起义区／奥斯曼帝国",sources:["【《拜伦书信与日记全集》（莱斯利·马钱德校勘本，1973至1982年）】收其1823至1826年在希腊的通信与理财记录","【托马斯·戈登《希腊革命史》（1832）】记米索隆吉战局、派系纠纷与拜伦之死"],tags:["诗人","亲希腊运动","希腊独立"]},related:["world--1821--p01", "world--1827--m01", "world--1822--d01"]},
  {id:"world--1826--m01",track:"world",year:1826,yearApprox:false,dim:"military",weight:3,title:"俄土俄波战争再起",summary:"俄国同时对波斯与奥斯曼用兵，巴尔干与高加索并重开。",detail:{background:"希腊起义后东方问题悬而未决，俄国以东正教保护者自居；1826年6月波斯王储阿巴斯·米尔扎越阿拉斯河北进，俄国则以多瑙河两公国与黑海沿岸条款向奥斯曼施压。",process:"1826年俄军在亚美尼亚反攻，1827年9至10月攻取埃里温、进逼大不里士，1828年2月10日《土克曼恰伊和约》使波斯割让埃里温与纳希切万两汗国并赔款；多瑙河方向1826年10月《阿克曼公约》暂时冻结冲突，1828至1829年俄军两度越巴尔干山，1829年8月进占阿德里安堡。",impact:"两战把俄国西南边界推至阿拉斯河—卡拉斯河一线，奠定其在外高加索的支配地位，并把希腊、塞尔维亚问题以条约形式钉进欧洲协调议程，随即引发英奥对俄国单独扩张的警惕。",figures:["尼古拉一世","阿巴斯·米尔扎","伊万·迪比奇"],place:"外高加索、多瑙河两公国与色雷斯",state:"俄罗斯帝国／奥斯曼帝国／波斯卡扎尔王朝",sources:["【《近代国际条约集》】用于核对1828年《土克曼恰伊和约》与1829年《阿德里安堡和约》条文","【斯坦福·肖《奥斯曼帝国史》】记两场战争的军事态势与马哈茂德二世的改革反应"],tags:["战争","高加索","东方问题"]},related:["world--1821--p01", "world--1829--p02", "world--1826--e01"]},
  {id:"world--1826--e01",track:"world",year:1826,yearApprox:false,dim:"economy",weight:2,title:"阿克曼公约与黑海通航",summary:"俄土以公约确认塞尔维亚特权并重开黑海商路。",detail:{background:"1826年6月战争危机爆发后，英国不希望俄国单独对土媾和，坎宁政府以调停换取商业与航运安排的固化。",process:"1826年10月7日俄土在阿克曼（今乌克兰比城）签约：确认1824—1825年关于塞尔维亚自治与两公国的承诺，开放多瑙河与黑海航路，其商务附约给予俄商最惠国待遇与固定吨位税。",impact:"阿克曼安排把奥斯曼此后数年的让步预先写成条件，也使海峡通航与黑海粮运成为英俄长期竞逐的可计量对象；1838年英土《伯麦塔尔曼公约》以英国版最惠国条款接替了这一模式。",figures:["乔治·坎宁","马哈茂德二世","尼古拉一世"],place:"阿克曼（今乌克兰别尔哥罗德-德涅斯特罗夫斯基）",state:"俄罗斯帝国／奥斯曼帝国",sources:["【《近代国际条约集》】用于核对1826年《阿克曼公约》及其商务附约条款","【《剑桥欧洲经济史》】论19世纪20至30年代黑海粮运与地中海航运的扩张"],tags:["条约","黑海","最惠国"]},related:["world--1826--m01", "world--1838--e01", "world--1827--m01"]},
  {id:"world--1826--s01",track:"world",year:1826,yearApprox:true,dim:"science",weight:3,title:"尼埃普斯摄出最早照片",summary:"以沥青感光在金属板上留下窗外的第一眼影像。",detail:{background:"18世纪末贝托莱的银盐退色实验与韦奇伍德的光影剪影都未能定影；法国勃艮第乡绅尼埃普斯自1816年起改以犹太柏油（沥青）作感光剂，因其见光硬化而不褪色。",process:"约1826年（一说1827年）尼埃普斯在自家窗阁以涂沥青的锡铅板曝光约八小时，洗去未硬化部分后得《窗外景色》，成为现存最早的相机实像；1827年他携板赴伦敦，1833年贫病而死，其侄子与达盖尔续研改良。",impact:"这块板确立了「曝光—溶剂显影—永久固定」的摄影逻辑，是摄影术的起点；此后图像进入新闻、档案、科学与日常记忆，也令1839年达盖尔法的公布成为国家事件。",figures:["尼塞福尔·尼埃普斯","路易·达盖尔"],place:"法国圣卢普",state:"法兰西王国",sources:["【格尔恩西姆夫妇《摄影史》】记沥青法原理与最早实物的鉴定经过","【《技术史》（辛格等主编）第五卷】用于核对感光化学的18世纪前史"],tags:["摄影","感光","发明"]},related:["world--1839--s01"]},
  {id:"world--1827--m01",track:"world",year:1827,yearApprox:false,dim:"military",weight:3,title:"纳瓦里诺海战",summary:"三国联合舰队一日之内摧毁土埃舰队主力。",detail:{background:"1826年4月英俄照会后，1827年7月6日英法俄《伦敦条约》要求奥斯曼在摩里亚停战并接受调解；易卜拉欣率埃军于4月攻陷米索隆吉，正围攻阿克。",process:"1827年10月20日科德林顿率联合舰队进入纳瓦里诺湾以护航名义停泊，与土埃舰队交火约四小时：土埃方面六十余艘舰船被击沉或焚毁、人员死伤数千（奥斯曼与欧洲各国的估算差异较大）；联军三艘舰被毁、自身死伤亦以千计，无一艘战列舰被击沉。",impact:"此役是帆船战列舰的最后一场大会战，一举清零奥斯曼海权，迫使易卜拉欣撤出摩里亚，使希腊独立成为既成事实；它也暴露英俄在海峡问题上的分歧，为1829年俄军单独推进与《阿德里安堡和约》铺路。",figures:["爱德华·科德林顿","易卜拉欣·帕沙","马哈茂德二世"],place:"伯罗奔尼撒西南纳瓦里诺湾（皮洛斯湾）",state:"奥斯曼帝国／英法俄联合舰队",sources:["【英国海军部1827年战报与科德林顿公文（英国国家档案馆海军档）】记交火经过与双方损失","【《伦敦条约》（1827年7月6日）文本（《近代国际条约集》）】核对三国共同照会与停战条款"],tags:["海战","希腊独立","列强干预"]},related:["world--1821--p01", "world--1826--m01", "world--1829--p02"]},
  {id:"world--1827--p01",track:"world",year:1827,yearApprox:false,dim:"politics",weight:2,title:"塞尔维亚交还六堡",summary:"奥斯曼依公约把六座城堡守备权交还贝尔格莱德公国。",detail:{background:"1804与1815年两次起义后，塞尔维亚仅取得纳贡自治权，贝尔格莱德等要塞的守备仍归土军，公国无法征税与募兵。",process:"依1826年《阿克曼公约》所定条件，奥斯曼于1826年底至1827年把乌日采、戈卢巴茨、索科堡、兹沃尔尼克、洛兹尼察与沙巴茨六座城堡的守备权交还公国，米洛什·奥布雷诺维奇由此掌握税赋、军械与司法。",impact:"城堡交还把公国从被占领的纳贡区变为有实质的自治体，成为1830年素丹敕令、1833年领土扩展与1878年柏林会议承认完全独立这一连串渐进独立的起点。",figures:["米洛什·奥布雷诺维奇","马哈茂德二世"],place:"贝尔格莱德与舒马迪亚",state:"奥斯曼帝国·塞尔维亚公国",sources:["【《近代国际条约集》】用于核对1826年《阿克曼公约》中有关塞尔维亚要塞与自治的条款","【利奥波德·冯·兰克《塞尔维亚革命史》（1829）】据当地文书论城堡移交与米洛什的税兵权"],tags:["自治","要塞","巴尔干"]},related:["world--1804--p03", "world--1826--e01"]},
  {id:"world--1828--p01",track:"world",year:1828,yearApprox:false,dim:"politics",weight:3,title:"威灵顿与解放之议",summary:"克莱尔补选与阁内分歧迫使托利党内阁主动提案。",detail:{background:"1828年1月威灵顿组阁，坚持新教宪制不可动摇；同年天主教中央协会以群众集会让奥康内尔赢得克莱尔郡补选，而当选者因信仰不能就职。",process:"1828年5月《团法与市法》废除后公职限制部分松动；7月30日奥康内尔在克莱尔郡当选，12月爱尔兰首席秘书戈本承认自己无法在不伪誓的情况下领圣餐而辞职，威灵顿遂承认只能由内阁主动提出全面解放案。",impact:"这一连串程序把「是否解放」变成「如何控制解放代价」，直接导致1829年法案与托利党分裂；奥康内尔依靠佃农与教区网络的动员模式，也被此后的爱尔兰自治运动与英国议会政治沿用。",figures:["威灵顿公爵","罗伯特·皮尔","丹尼尔·奥康内尔"],place:"伦敦与爱尔兰克莱尔郡",state:"大不列颠及爱尔兰联合王国",sources:["【《议会辩论集》（汉萨德新系列，1828至1829年卷）】记戈本辞职争议与两院表决过程","【《牛津插图英国史》】论天主教解放议题对托利党分裂与选举重组的影响"],tags:["天主教解放","爱尔兰","内阁"]},related:["world--1829--p01", "world--1828--i01", "world--1800--p01"]},
  {id:"world--1828--p02",track:"world",year:1828,yearApprox:false,dim:"politics",weight:3,title:"蒙特维的亚初步和约",summary:"英调停下乌拉圭成为巴西与阿根廷之间的缓冲国。",detail:{background:"1825至1828年西普拉蒂纳战争耗尽巴西与联合省财政，海上封锁使布宜诺斯艾利斯关税锐减，英国以债权与贸易为由出面仲裁。",process:"1828年8月27日双方依威灵顿与驻布宜诺斯艾利斯公使庞森比拟定的方案签订《初步和约》：东岸成为独立国家「乌拉圭」，两国保留平等的通航与河港权利，并各自撤军、交换战俘；1830年7月乌拉圭颁布共和国宪法。",impact:"缓冲国方案终结了拉普拉塔与巴西的直接陆地冲突，也把英国的仲裁权写入南美外交惯例；和约同时击溃布宜诺斯艾利斯的中央派，为1829年罗萨斯掌权与联邦派—统一派的长期斗争定型。",figures:["胡安·安东尼奥·拉瓦列哈","庞森比勋爵","曼努埃尔·多雷戈"],place:"蒙特维的亚",state:"拉普拉塔联合省／巴西帝国／乌拉圭",sources:["【1828年8月27日《蒙特维的亚初步和约》（《近代国际条约集》）】记缓冲国条款与通航安排","【《剑桥拉丁美洲史》第三卷】论英国调停与拉普拉塔内部政治重组"],tags:["条约","缓冲国","调停"]},related:["world--1825--p03", "world--1813--p03"]},
  {id:"world--1828--i01",track:"world",year:1828,yearApprox:false,dim:"institution",weight:2,title:"英国废除团法与市法",summary:"非国教徒不再以领圣餐为任公职条件。",detail:{background:"1673与1678年《团体法》《市法》要求公职者领英国国教圣餐并咒斥变体论，名义上排斥天主教徒与非国教徒，实际长期靠每年豁免法维持。",process:"1828年5月9日《团法与市法废除法》御准：取消对非国教徒的圣餐强制，改以一般宣誓，但保留对天主教徒的实质限制，并要求不奉国教者登记其礼拜场所。",impact:"它使不信奉国教的中产阶层得以进入地方公职与公司治理，重划了国教与世俗社会的边界，也为1829年天主教解放、1832年议会改革与1830年代的市政调查铺出「逐层拆墙」的立法路径。",figures:["罗伯特·皮尔","威灵顿公爵"],place:"伦敦与英格兰各自治市",state:"大不列颠及爱尔兰联合王国",sources:["【《1828年团法与市法废除法》御准文本（英国国家档案馆）】核对豁免范围与礼拜场所登记条款","【《牛津插图英国史》】论其与1829年天主教解放法的连续关系"],tags:["宗教","公职","立法"]},related:["world--1828--p01", "world--1829--p01"]},
  {id:"world--1828--e01",track:"world",year:1828,yearApprox:false,dim:"economy",weight:3,title:"美国1828年关税",summary:"高税率激化南北对立，州权理论首次成文。",detail:{background:"1824年关税已抬高制成品税率，东北部工厂主与部分西部农产品利益要求再加保护；南方棉花与烟草出口区痛斥关税转嫁于己。",process:"1828年5月19日新关税法在南部议员缺席下通过，多数应税进口品税率提高、并以估价与最低计税价格并用，实际平均税率接近进口值的近一半，被南方称为「可憎的关税」；同年12月南卡议会通过卡尔霍恩起草的《解释与抗议》。",impact:"该法把「保护即北方利益」的对立固化，并把「一州可宣告联邦法律在本州无效」的理论首次写成正式方案，直接引出1832年南卡拒绝执行案、1833年妥协关税与长达三十年的关税—州权纠缠。",figures:["安德鲁·杰克逊","约翰·卡尔霍恩"],place:"华盛顿与查尔斯顿",state:"美利坚合众国",sources:["【1828年5月19日关税法文本（《美国法律大全》第4卷）】核对税率表与估价条款","【《卡尔霍恩文集》（1851至1856年编行）】收1828年《南卡罗来纳解释与抗议》全文"],tags:["关税","州权","南北对立"]},related:["world--1832--p02"]},
  {id:"world--1828--s01",track:"world",year:1828,yearApprox:false,dim:"science",weight:3,title:"维勒人工合成尿素",summary:"用氰酸铵在瓶中制出尿液成分，动摇生命力论。",detail:{background:"贝采利乌斯的学说把有机物划归生物界特有，认为其形成需一种「生命力」；氰酸与氰酸铵则被视为无机化学的边界。",process:"1828年维勒在《物理学与化学年鉴》报告：加热氰酸铵所得晶体的性质与人尿中提取的尿素一致，并据此写出《论用无机物合成尿素》，1829年又与贝采利乌斯通信争辩其意义。",impact:"这项实验后成为「生命力论解体」的象征，其更实在的后果是确立了分子可跨生物与矿物界合成的纲领，引出1845年科尔贝合成醋酸、1856年珀金苯胺紫与近代合成染料、制药工业。",figures:["弗里德里希·维勒","永斯·贝采利乌斯"],place:"德国柏林",state:"普鲁士王国",sources:["【维勒《论氰酸铵与尿素之比较》（《物理学与化学年鉴》1828年）】给出原始实验记录","【《贝采利乌斯与维勒通信集》】记两人对合成意义的长期争论"],tags:["化学","有机合成","生命力论"]},related:["world--1803--s01"]},
  {id:"world--1829--p01",track:"world",year:1829,yearApprox:false,dim:"politics",weight:4,title:"天主教解放法通过",summary:"爱尔兰天主教徒获任公职，同时被剥夺选举权。",detail:{background:"1828年克莱尔郡补选使政府面对一位无法就职的当选者，威灵顿与皮尔判断拒绝实施将冒内战风险。",process:"1829年2月皮尔提出《消除天主教徒公民与政治限制法》：以新誓词开放议会与几乎全部军政公职，取缔耶稣会等外来宗教管辖，同时以附带法取消爱尔兰四十先令自由持有农的选举权，使爱尔兰选民由约二十万降至不足四万。4月13日御准。",impact:"法案撕碎托利党（1830年政府倒台），把奥康内尔式群众动员转化为议会内的力量，却同时以剥夺选举权把解放的回报送给新教中产；此后爱尔兰自治运动与英国宪政改革始终在这一交换结构上展开。",figures:["丹尼尔·奥康内尔","罗伯特·皮尔","威灵顿公爵"],place:"伦敦威斯敏斯特",state:"大不列颠及爱尔兰联合王国",sources:["【《1829年罗马天主教公民权利法》御准文本（英国国家档案馆，1829年4月13日）】核对誓词、开放公职与选举权条款","【《议会辩论集》（汉萨德新系列，1829年2至4月）】记两院表决与奥康内尔当选之争"],tags:["天主教解放","爱尔兰","议会"]},related:["world--1828--p01", "world--1800--p01", "world--1828--i01"]},
  {id:"world--1829--p02",track:"world",year:1829,yearApprox:false,dim:"politics",weight:3,title:"阿德里安堡和约",summary:"俄土和约划出希腊自治，俄国取得多瑙河口。",detail:{background:"1828至1829年俄军两度越巴尔干山并于8月进占阿德里安堡，君士坦丁堡危殆，马哈茂德二世被迫求和。",process:"1829年9月14日《阿德里安堡和约》确认1827年《伦敦条约》与希腊自治安排、塞尔维亚与两公国的特权条款，多瑙河口与黑海东岸阿纳帕至波季一带划归俄国，奥斯曼偿付军费赔款，并承诺开放海峡通航。",impact:"和约使俄国同时握有多瑙河三角洲与外高加索海岸，并把「保护东正教徒」写成条约机制，1833年《温卡尔—伊斯凯莱西条约》进一步独占海峡通行；英奥遂转向扶植奥斯曼以遏俄，欧洲协调在近东彻底分裂。",figures:["尼古拉一世","马哈茂德二世","伊万·迪比奇"],place:"阿德里安堡（今埃迪尔内）",state:"俄罗斯帝国／奥斯曼帝国",sources:["【《近代国际条约集》】用于核对1829年9月14日和约的割地、赔款与两公国条款","【斯坦福·肖《奥斯曼帝国史》】记战败对坦志麦特改革的触发"],tags:["条约","俄国扩张","近东"]},related:["world--1826--m01", "world--1827--m01", "world--1833--p02"]},
  {id:"world--1829--p03",track:"world",year:1829,yearApprox:false,dim:"politics",weight:2,title:"伦敦议定书定希腊自治",summary:"三国先定自治与边界，把独立分作三步走。",detail:{background:"纳瓦里诺之后奥斯曼拒不承认希腊变更，三国需在遏俄与兑现承诺之间折中，故把「自治」作为可让土耳其接受的中间形态。",process:"1829年2月英法俄在伦敦签订议定书，规定希腊为自治公国、向素丹纳贡并确定其北界，同年《阿德里安堡和约》予以确认；1830年2月三国改认希腊完全独立，1832年5月《君士坦丁堡条约》最终承认，并选定巴伐利亚的奥托为王。",impact:"把独立拆成「自治—完全独立—王朝选定」三步，既避免与奥斯曼立即摊牌，又让三国保留边界与王位的实际控制权；希腊由此成为欧洲协调以条约制造新国家的第一个成功案例。",figures:["卡波迪斯特里亚斯","马哈茂德二世"],place:"伦敦与埃伊纳",state:"英法俄三国／奥斯曼帝国／希腊",sources:["【《近代国际条约集》】用于核对1829年2月伦敦议定书与1832年5月《君士坦丁堡条约》","【斯坦福·肖《奥斯曼帝国史》】记奥斯曼在希腊问题上的让步过程"],tags:["议定书","希腊","自治"]},related:["world--1821--p01", "world--1829--p02", "world--1827--m01"]},
  {id:"world--1829--i01",track:"world",year:1829,yearApprox:false,dim:"institution",weight:3,title:"伦敦大都会警察创建",summary:"皮尔以民事巡逻队取代教区更夫与血腥法典。",detail:{background:"伦敦治安由教区更夫、私人捕盗与数千条可判死刑的法律勉强维持；1829年波士顿街连环杀人案引发《泰晤士报》主导的建制改革运动。",process:"内政大臣皮尔提出《大都会警察法》，1829年6月御准，设两名专职警官；9月29日起在半径约六至七英里圈内招募首批约一千名着蓝色制服、高顶盔的巡逻警，以制服、番号与分段值班取代临时缉捕。",impact:"这是第一支以预防犯罪为业的常备民事警察，其「以公众容忍而非军队维持秩序」的原则成为各国都市警制的蓝本；1831至1832年的骚动中警员大量流失，也暴露这一制度对政治稳定的依赖。",figures:["罗伯特·皮尔","查尔斯·罗恩","理查德·梅恩"],place:"伦敦",state:"大不列颠及爱尔兰联合王国",sources:["【《1829年大都会警察法》御准文本（英国国家档案馆）】核对设警范围、编制与警务委员会","【《泰晤士报》1829年关于波士顿街案与治安改革的系列报道】记立法舆论"],tags:["警察","都市治理","立法"]},related:["world--1829--p01", "world--1828--i01"]},
  {id:"world--1830--p01",track:"world",year:1830,yearApprox:false,dim:"politics",weight:5,title:"法国七月革命",summary:"三日巷战推翻波旁复辟王朝，建立七月王朝。",detail:{background:"1829年波利尼亚克内阁转向极右，1830年3月16日众院以221票对181票通过不信任「地址」；查理十世于7月25日颁四道敕令：解散新选众院、限制选举权、查封报刊并重定选举期。",process:"7月27至29日「光荣三日」巴黎筑起四千余座街垒，国民自卫队重建、部分军队倒向；7月31日拉法耶特在市政厅以三色旗致意新奥尔良公爵，8月2日查理十世退位，8月9日路易-菲利普接受修改后的宪章，称「法国人的国王」。",impact:"七月王朝以财产选举权（选民由约十万增至二十余万）与「中间路线」治国，把主权符号从血统改为公民—纳税者；但它既拒共和派又拒工人要求，1831与1834年里昂两次起义、1832年起共和社团密谋不断，直至1848年2月被推翻。",figures:["路易-菲利普","拉法耶特","查理十世"],place:"巴黎",state:"法兰西王国（七月王朝）",sources:["【1830年8月14日公布的修改宪章文本（《法国国家公报》1830年8月）】核对主权表述与选举条件","【《新剑桥近代史》第十卷（1830至1870年）】论七月王朝的选举与社会基础"],tags:["革命","七月王朝","宪章"]},related:["world--1814--i01", "world--1830--p02", "world--1830--p03", "world--1848--p01"]},
  {id:"world--1830--p02",track:"world",year:1830,yearApprox:false,dim:"politics",weight:3,title:"波兰十一月起义",summary:"华沙军官夜袭总督府，王国十日之内脱离俄控。",detail:{background:"1815年《波兰王国宪章》自1819年起停止实施，审查、大学清洗与征兵令累积不满；华沙青年军官秘密团体计划在1830年11月趁俄土战争之机起事。",process:"1830年11月29日夜起义者袭击贝尔韦德尔宫、占领华沙军械库，俄军司令退郊；12月议会接管政务，1831年1月25日宣告废黜尼古拉一世，2至9月与俄军连续会战；9月8日华沙陷落，残部入普鲁士被解除武装，数万人流亡西欧。",impact:"起义使波兰问题成为1830至1860年代欧洲自由派的共同议题（「一切民族之波兰」），也换来1832年《组织法》撤销议会、军队与大学自治的紧缩；流亡政治与密茨凯维奇等人的写作，把民族运动从战场转入思想领域。",figures:["亚当·密茨凯维奇","弗雷德里克·肖邦"],place:"华沙与马佐夫舍",state:"俄罗斯帝国·波兰王国",sources:["【《剑桥波兰史》第二卷（1795年以后）】记起义经过、军事失败与1832年体制变动","【1831至1832年波兰议会文件与告全民书】用于核对废黜宣言与流亡统计"],tags:["起义","民族","流亡"]},related:["world--1815--i03", "world--1831--p02", "world--1830--p01"]},
  {id:"world--1830--p03",track:"world",year:1830,yearApprox:false,dim:"politics",weight:3,title:"比利时革命爆发",summary:"演出引发的巷战使南尼德兰脱离荷兰王国。",detail:{background:"1815年维也纳会议把南尼德兰并入荷兰王国以构筑北方屏障，但南北在官语、学校立法、国债分摊与议会代表名额分配上积怨，1828年天主教徒与自由派结成反对联盟。",process:"1830年8月25日布鲁塞尔演出歌剧《波尔蒂奇哑女》后爆发骚动，荷兰王军入城镇压反促成9月23至26日巷战并被迫北撤；9月24日临时政府宣告独立，11月10日国民大会在布鲁塞尔开会，12月20日伦敦会议召开。",impact:"比利时独立是1815年体系的第一次和平改写：欧洲列强宁可拆散联合王国也不容法国兼并，其「永久中立」安排（1839年伦敦条约）成为欧陆安全结构的一部分，直到1914年德国借其中立问题宣战。",figures:["荷兰国王威廉一世","利奥波德一世","约瑟夫·莱博"],place:"布鲁塞尔与安特卫普",state:"荷兰联合王国／比利时",sources:["【伦敦会议1830至1831年议定书（《近代国际条约集》）】记四国对比利时独立与王位的处置","【科克尔霍夫《比利时史》（1981年英文版）】用于核对党派联盟与国民大会组成"],tags:["革命","独立","中立"]},related:["world--1815--p01", "world--1831--p03", "world--1831--i01", "world--1830--p01"]},
  {id:"world--1830--p04",track:"world",year:1830,yearApprox:false,dim:"politics",weight:3,title:"美国印第安人迁移法",summary:"联邦以换地条款启动东南部落的西迁强制。",detail:{background:"佐治亚等州陆续把「国内依附民族」土地纳入州法管辖，切罗基等东南部部落面临州法、私占与联邦的双重压力。",process:"1830年5月28日《印第安人迁移法》授权总统以密西西比河以西土地置换东部部落领地，并拨付专款执行迁移；随后十余年间乔克托、奇克索、克里克与切罗基相继签约西迁。",impact:"该法开启1835—1836年克里克战争与1838年切罗基「眼泪之路」，并把部落主权推向联邦最高法院：1831年切罗基族诉佐治亚案与1832年伍斯特诉佐治亚案确立「国内依附民族」概念，却未能阻止强制迁移执行。",figures:["安德鲁·杰克逊","约翰·马歇尔","约翰·罗斯"],place:"华盛顿与佐治亚、俄克拉何马属地",state:"美利坚合众国",sources:["【1830年5月28日《印第安人迁移法》（《美国法律大全》第4卷）】核对授权范围与专款条款","【1832年3月3日最高法院对伍斯特诉佐治亚案的判决】用于核对「国内依附民族」的司法界定"],tags:["迁移","原住民","联邦与州"]},related:["world--1814--p06"]},
  {id:"world--1830--s01",track:"world",year:1830,yearApprox:false,dim:"science",weight:4,title:"利物浦—曼彻斯特铁路通车",summary:"首条蒸汽牵引的定期城际铁路，客运从此成业。",detail:{background:"1825年斯托克顿—达灵顿铁路以混合牵引为主、客运只是附带；曼彻斯特工厂主与棉花商人亟需摆脱运河与马车费的约束，1826年国会批准筑路、斯蒂芬森主持工程。",process:"1829年10月「火箭号」在雷恩希尔牵引竞赛中以多锅炉与直接传动取胜；1830年9月15日全线通车，国会议员赫斯基森在仪式上被该车撞死；此线此后以蒸汽牵引、固定班次与统一运行表为常规经营。",impact:"它证明了城际客运可独立盈利，直接触发英国1830年代的铁路投资浪潮；与电报结合后又产生标准时与全网运行表，是现代企业组织、时间制度与资本市场的共同起点。",figures:["乔治·斯蒂芬森","罗伯特·斯蒂芬森","威廉·赫斯基森"],place:"英格兰利物浦—曼彻斯特",state:"大不列颠及爱尔兰联合王国",sources:["【利物浦—曼彻斯特铁路公司1830至1835年营运报告与账目】记通车后客货运量与收益","【《技术史》（辛格等主编）第五卷】用于核对机车与轨道技术"],tags:["铁路","蒸汽","客运"]},related:["world--1825--e01", "world--1837--s01"]},
  {id:"world--1831--s01",track:"world",year:1831,yearApprox:false,dim:"science",weight:5,title:"法拉第发现电磁感应",summary:"磁生电的实验中找到了工业电力时代的基本原理。",detail:{background:"1820年奥斯特发现电流磁效应、安培给出电动力定律后，「磁能否生电」成为皇家学会实验室内的公开问题；法拉第自1821年起反复尝试均未成功。",process:"1831年8月29日法拉第在绕有两组线圈的软铁环上做实验，仅在接通与断开瞬间检流计偏转，遂悟出「感应」是变化而非稳态；10月28日他用磁棒插入线圈直接取得电流，11月24日向皇家学会宣读首批感应实验结果。",impact:"感应定律成为发电机、变压器与交流输配电的原理基础，使电从实验室奇观变为可计量的工业能量；麦克斯韦1855年后把法拉第的力线数学化，直接通到1887年赫兹实验与无线电。",figures:["迈克尔·法拉第"],place:"伦敦英国皇家研究所",state:"大不列颠及爱尔兰联合王国",sources:["【法拉第《电学实验研究》第一至四系列（《哲学汇刊》1831至1833年）】给出原始实验记录与「感应电流」命名","【麦克斯韦《论法拉第的力线》（1855至1856年剑桥哲学学会会报）】用于核对理论化过程"],tags:["电磁","感应","发电机"]},related:["world--1820--s01", "world--1821--s01", "world--1837--s01"]},
  {id:"world--1831--d01",track:"world",year:1831,yearApprox:false,dim:"disaster",weight:3,title:"霍乱登陆不列颠",summary:"第二次大流行自印度西传，把卫生问题推上立法议程。",detail:{background:"1817年起的第一次大流行主要限于南亚与东南亚；1820年代末霍乱沿里海—俄罗斯商路西进，1830年秋在莫斯科大规模流行，英国朝野既恐惧又轻视其传播机制。",process:"1831年10月末桑德兰出现英国首批病例，11月纽卡斯尔、赫尔相继爆发；1832年2月疫情传入伦敦，春夏达到高峰，1831至1832年大不列颠死亡约三万二千人（学界以登记总表统计，实际或更高）。",impact:"疫情迫使政府以枢密院命令、检疫站与地方卫生委员会取代教区救济，开创以国家机构应对传染病的先例；1842年查德威克调查报告、1848年《公共卫生法》乃至1854年斯诺对伦敦宽街水泵的调查，皆源于这一波经验。",figures:["亨利·哈尔福德","约翰·斯诺"],place:"英格兰北部与伦敦",state:"大不列颠及爱尔兰联合王国",sources:["【枢密院中央卫生委员会1831至1832年呈报与地方卫生报告（英国议会文件）】记检疫措施与分地死亡率","【《泰晤士报》1832年伦敦每周死亡统计表】用于核对伦敦疫情的时空分布"],tags:["霍乱","公共卫生","检疫"]},related:["world--1817--d01", "world--1832--d01"]},
  {id:"world--1831--p01",track:"world",year:1831,yearApprox:false,dim:"politics",weight:3,title:"英国改革法案危机",summary:"上院否决法案引发骚动，两年后以让步通过。",detail:{background:"1830年11月格雷组阁并承诺议会改革，郡与选区结构、腐化选区与不存在的城市代表问题积重百年。",process:"1831年2月3日罗素提出法案；4月在委员会表决中受挫，格雷劝国王解散议会，夏季大选使辉格党大胜；10月8日上院否决法案，诺丁汉、德比、博顿等地爆发骚动并焚毁城堡与官邸教堂，「政治同盟」以拒付税款相威胁；1832年6月在增设贵族的压力下于上院过关。",impact:"这场危机把「下院决议—群众压力—国王让步」变成19世纪英国立宪的运作范式，直接产出1832年法案与其后的1867、1884年改革；它同时表明改革可在不内战的条件下兑现，与1830至1831年欧陆革命形成对照。",figures:["查尔斯·格雷","约翰·罗素","威廉四世"],place:"伦敦与英格兰各郡",state:"大不列颠及爱尔兰联合王国",sources:["【《议会辩论集》（汉萨德，1831至1832年卷）】记两院表决、拒款威胁与增设贵族之争","【英国国家档案馆所藏1831年内阁与王室往来文书】用于核对解散议会与国王立场"],tags:["议会改革","上院","群众运动"]},related:["world--1819--p02", "world--1832--p01", "world--1831--e01"]},
  {id:"world--1831--p02",track:"world",year:1831,yearApprox:false,dim:"politics",weight:3,title:"华沙陷落与起义失败",summary:"俄军攻破城郊防线，波兰王国体制被撤销。",detail:{background:"1830年11月起义后波兰军约五至六万人长期与俄军对峙；俄军于1831年5月26日在奥斯特洛文卡河战役后转入围攻。",process:"1831年9月6至7日俄军强攻华沙西郊沃拉阵地并逐屋争夺，9月8日城防委员会请求停火、次日守军撤离；10月起义军余部进入普鲁士境内被解除武装，领导人先后流亡巴黎与伦敦。",impact:"失败使波兰王国失去议会、独立军队与大学自治权，1832年《组织法》将其并入帝国行省体制，公开政治活动转入地下与流亡；「大流亡」把波兰问题长期留在西欧外交与舆论议程上。",figures:["伊万·帕斯克维奇","约泽夫·贝姆"],place:"华沙与沃拉郊区",state:"俄罗斯帝国·波兰王国",sources:["【1832年2月《波兰王国组织法》（俄国王室法令汇编）】记撤销议会与军制的条款","【《剑桥波兰史》第二卷（1795年以后）】用于核对攻城经过与流亡规模"],tags:["镇压","并入","流亡"]},related:["world--1830--p02", "world--1815--i03"]},
  {id:"world--1831--p03",track:"world",year:1831,yearApprox:false,dim:"politics",weight:3,title:"比利时独立获承认",summary:"国民大会选定国王，荷兰以武力试探失败。",detail:{background:"1830年12月伦敦会议已在事实上讨论比利时分立，国民大会需在法国候选人与一位能同时为列强接受的亲王之间抉择。",process:"1831年1月20日国民大会宣告王位世袭并排除奥兰治家族；2月7日宪法颁布；6月4日选萨克森-科堡的利奥波德为王，7月12日其宣誓就任、7月21日入布鲁塞尔（后成国庆日）；8月2至12日荷兰军队「十日行动」越界，因法军动员与列强照会而退回。",impact:"比利时分立以议会宪法与条约保证并行的方式完成，是复辟时代欧洲唯一一次被列强集体接纳的革命；1831年8月与1832年伦敦安排将其置于集体保障之下，1839年条约最终确认其独立与中立。",figures:["利奥波德一世","荷兰国王威廉一世","埃拉斯姆·苏尔莱·德·肖基耶"],place:"布鲁塞尔",state:"比利时王国",sources:["【伦敦会议1831年议定书（《近代国际条约集》）】记王位选定与荷兰撤军安排","【科克尔霍夫《比利时史》（1981年英文版）】用于核对国民大会表决与宪法施行"],tags:["独立","立宪","列强保证"]},related:["world--1830--p03", "world--1831--i01"]},
  {id:"world--1831--p04",track:"world",year:1831,yearApprox:false,dim:"politics",weight:3,title:"里昂丝织工人起义",summary:"织工以罢工与巷战要求最低工价，遭军队镇压。",detail:{background:"拿破仑时期里昂即有织工与厂主议定工价的惯例，复辟与七月王朝后订单随景气起伏，每千码工价跌破法定基准，数万织工陷于失业。",process:"1831年10月厂主拒付议定工价，11月21日起数万名织工停工并占领市区，起义者以「做工生活、战斗而死」为旗号，一度控制城市并与军队、周边国民自卫队巷战；11月底政府以增兵与部分让步（承认工价表）收场，1834年4月再次起义被血腥镇压。",impact:"这是欧洲第一次以行业工人为主体、带有自己口号与旗帜的大规模起义，使「工人问题」进入法国共和派与思想界的中心议题，直接催生1830年代圣西门主义、傅立叶主义与里昂—巴黎的秘密社团传统。",figures:["卡西米尔·佩里耶","奥尔良公爵费迪南"],place:"法国里昂与克罗瓦鲁斯郊区",state:"法兰西王国（七月王朝）",sources:["【《新剑桥近代史》第十卷（1830至1870年）】记两次里昂起义的规模与政治后果","【1831至1834年法国议会质询与内政大臣报告（《法国议会档案》）】用于核对工价表与兵力部署"],tags:["工人起义","工价","里昂"]},related:["world--1811--e01", "world--1830--p01", "world--1834--p02"]},
  {id:"world--1831--e01",track:"world",year:1831,yearApprox:false,dim:"economy",weight:3,title:"英格兰斯温骚乱",summary:"农业工人砸毁打谷机，雇主以工资协议回应。",detail:{background:"1829至1831年连续歉收使粮价高企，济贫税率上升，教区雇主以「外派劳动制」压低工资；打谷机被视为直接夺走冬季工作。",process:"1830年11月起肯特、萨里、伯克希尔等地夜半出现以「斯温队长」署名的恐吓信，砸毁打谷机、焚烧草垛、围逼济贫屋，要求固定工资、面包价与不征什一税；1831年骚动扩散至东南与东米德兰，特别法庭审判近两千人，处死二十人以内、约五百人流放。",impact:"骚乱迫使雇主普遍与教区议定最低工资与面包价，并把农业工人的处境推入议会视野：1834年《济贫法修正案》以习艺所取代室外救济，正是对这一连串工资斗争的制度化回答。",figures:["斯温队长（化名）"],place:"英格兰东南各郡",state:"大不列颠及爱尔兰联合王国",sources:["【霍布斯鲍姆与鲁德《斯温队长》（1969）】以审判档案与报纸统计重建骚乱范围与量刑","【1830至1831年特别委员会审判记录（英国国家档案馆）】用于核对受审、处死与流放人数"],tags:["工资斗争","农业","济贫法"]},related:["world--1831--p01", "world--1834--p02", "world--1811--e01"]},
  {id:"world--1831--i01",track:"world",year:1831,yearApprox:false,dim:"institution",weight:3,title:"比利时宪法颁布",summary:"国民大会写成欧洲最自由的立宪文件之一。",detail:{background:"国民大会由天主教派与自由派联盟组成，两派在王位、教育权与选举门槛上妥协，惟求以宪法换取列强承认与荷兰让步。",process:"1831年2月7日颁布宪法：确立两院制议会与大臣副署制、部长的连带责任、以教区与省为单位的直接选举、司法独立与公开审判，并明文保障结社、集会、教育与新闻自由（第45至47条），不对信仰内容作事先审查。",impact:"它成为19世纪自由宪政的参照文本（1831年亦为德意志部分邦国、挪威式立宪讨论的样板），并把天主教与自由派的共存写进制度的缝隙中；比中立的国际保障更耐久的，恰恰是这部宪法。",figures:["约瑟夫·莱博","埃拉斯姆·苏尔莱·德·肖基耶"],place:"布鲁塞尔",state:"比利时王国",sources:["【1831年2月7日比利时宪法文本】核对权利章与大臣责任条款","【《新剑桥近代史》第十卷（1830至1870年）】论该宪法在欧洲立宪浪潮中的位置"],tags:["宪法","自由权","两院制"]},related:["world--1830--p03", "world--1831--p03"]},
  {id:"world--1831--f01",track:"world",year:1831,yearApprox:false,dim:"figure",weight:2,title:"黑格尔在柏林逝世",summary:"体系哲学的顶点随其逝世分裂为右派与左派。",detail:{background:"黑格尔1818年应邀到柏林大学，讲演涵盖精神现象学、法哲学、历史哲学、美学与宗教哲学，1830年任大学校长。",process:"1831年11月14日黑格尔在柏林逝世，其时柏林正流行霍乱，通行记载以其死于霍乱（亦有研究归于旧疾），留下《哲学全书纲要》三版与大量由学生据听课笔记编订的讲演录。",impact:"其学派迅速分裂：右派维护「现实与理性同一」与国家神学，左派（费尔巴哈、布鲁诺·鲍威尔、马克思）把辩证法转向宗教批判与政治批判；现代国家理论、解释学与历史主义均自这一分裂展开。",figures:["格奥尔格·黑格尔","路德维希·费尔巴哈"],place:"德国柏林",state:"普鲁士王国",sources:["【黑格尔《哲学全书纲要》（1817年初版、1827与1830年再版）】用于核对其体系表述","【黑格尔1818至1831年柏林讲演的听课笔记（后人编订的《哲学讲演录》）】记学派内部分歧的形成"],tags:["哲学","柏林大学","青年黑格尔派"]},related:["world--1807--c01", "world--1819--p01", "world--1848--c01"]},
  {id:"world--1831--x01",track:"world",year:1831,yearApprox:false,dim:"explore",weight:3,title:"小猎犬号启程",summary:"一次测量航行把一位青年博物学家带向进化论。",detail:{background:"英国海军部拟重测火地岛与南美海岸（菲茨罗伊1826—1830年首次航行的续作），舰上需一位体面、受过科学训练的绅士博物学家陪伴。",process:"1831年12月27日「小猎犬号」自德文港启航，舰长菲茨罗伊，二十五岁的达尔文以博物学家身份随航；航行环南美测绘、考察火山与地震，1835年9至10月停留加拉帕戈斯群岛，1836年10月返回英国，全程近五年。",impact:"这次航行提供了《小猎犬号航海记》、地质渐变论的实证材料，以及地雀与龟类地理变异的直接观察，成为1837年「物种笔记本」与1859年《物种起源》的经验起点。",figures:["查尔斯·达尔文","罗伯特·菲茨罗伊"],place:"南美海岸与加拉帕戈斯群岛",state:"英国皇家海军测量船",sources:["【达尔文《小猎犬号航海记》（1839年定型版）】记测绘、采集与加拉帕戈斯观察","【《达尔文书信集》（伯克哈特等主编，1985年起）】用于核对航期与标本分发"],tags:["测量航行","博物学","进化论"]},related:["world--1859--s01", "world--1831--s01"]},
  {id:"world--1831--c01",track:"world",year:1831,yearApprox:false,dim:"culture",weight:3,title:"《巴黎圣母院》出版",summary:"雨果以中世纪巴黎重写历史与建筑的主题。",detail:{background:"1830年七月革命后法国浪漫派与古典派的论战白热化，雨果同时投入哥特建筑保护运动，并在1830年秋以三个月为限向书商承诺成书。",process:"1831年1月14日《巴黎圣母院》（副题「1482年」）在巴黎出版，以爱斯梅拉达、卡西莫多与克洛德·弗罗洛写成一个关于建筑、命运与底层人的故事；1832年版中雨果删去了带政治意味的序言，只留下「此书或为命运之作」的按语。",impact:"小说把哥特教堂从「野蛮遗物」改写为民族记忆之书，直接助推法国古迹保护立法（1830年设历史古迹总监察，梅里美在职）；它也为浪漫主义提供了叙事范型，1831年同时是雨果、大仲马与巴尔扎克相继成名的一年。",figures:["维克多·雨果","欧仁·德拉克洛瓦"],place:"巴黎",state:"法兰西王国（七月王朝）",sources:["【雨果《巴黎圣母院》1831年初版本及其1832年按语】核对成书与出版经过","【《新剑桥近代史》第十卷（1830至1870年）】用于核对法国浪漫派与七月王朝的文化政治"],tags:["小说","浪漫主义","古迹保护"]},related:["world--1802--c01", "world--1830--p01"]},
  {id:"world--1831--p05",track:"world",year:1831,yearApprox:false,dim:"politics",weight:2,title:"佩德罗一世退位",summary:"巴西皇帝让位幼子，回欧洲争葡萄牙王位。",detail:{background:"1826年若昂六世死后葡萄牙王位争议（米格尔一世与玛丽亚二世之争）牵动巴西；佩德罗在巴西因专制倾向、1825—1828年战争财政与北方省份叛乱而支持率崩塌。",process:"1831年4月7日佩德罗一世宣告退位给四岁的佩德罗二世，自己于同年赴欧洲；随后巴西设摄政委员会、1834年改为单一摄政，1835至1840年间多处省份爆发叛乱。",impact:"退位使巴西避免进一步裂解但换来十余年摄政期动荡，1840年「提前成年」恢复帝制；葡萄牙方面，佩德罗以亚速尔为基地组织立宪军登陆，1834年以《埃武拉蒙特和约》结束米格尔战争，使两国立宪派相互牵动。",figures:["佩德罗一世","米格尔一世"],place:"里约热内卢与里斯本",state:"巴西帝国／葡萄牙王国",sources:["【《牛津巴西史》】记1831年退位与摄政期省份叛乱","【《剑桥拉丁美洲史》第三卷】用于核对退位的财政与军事背景"],tags:["退位","摄政","伊比利亚"]},related:["world--1826--p01", "world--1834--p01"]},
  {id:"world--1832--p01",track:"world",year:1832,yearApprox:false,dim:"politics",weight:5,title:"英国第一次改革法",summary:"1832年改革法重分议席、扩大选民，郡县与城市格局被改写。",detail:{background:"1831年上院两度否决法案，英格兰爆发骚乱（诺丁汉、德比等地），格雷请国王创造足够贵族以通过法案，威廉四世拒绝并一度解职格雷，惠灵顿组阁失败后国王让步。",process:"1832年6月7日御准。上院放弃阻挠后，法案取消四十余个衰败选区的议席并减半若干镇，曼彻斯特、伯明翰、利兹、设菲尔德等获两席，郡按人口分设；城市采用10镑房户选举资格，郡内扩及600镑以上租借户。配套法同时取消爱尔兰40先令自由持有农的选票，使其登记选民由1829年后的约三十五万降至数万（各方统计差异大，学界以区间表述）。",impact:"通行估计英格兰与威尔士选民约增三分之二，工业城市首次获得制度化代表权，但无票的工人、农业劳动者与全部女性被排除在外，这构成1838年人民宪章的直接起因；议会主权与选区可立法重划的原则亦由此确立。",figures:["查尔斯·格雷","威廉四世","威灵顿公爵"],place:"英国伦敦、曼彻斯特",state:"英国",sources:["【《不列颠百科全书》「1832年改革法」条目】记选区重划与选民资格条款","【《议会辩论集》1831至1832年卷】记上院否决、国王拒绝创造贵族与6月4日放弃阻挠"],tags:["改革法","选区","选民"]},related:["world--1831--p01", "world--1819--p02", "world--1832--e01"]},
  {id:"world--1832--p02",track:"world",year:1832,yearApprox:false,dim:"politics",weight:4,title:"南卡州拒行联邦法危机",summary:"南卡罗来纳宣布1828与1832年关税在本州无效，杰克逊以武力威胁回应。",detail:{background:"1828年「可憎关税」使南部出口州承担制造成本，卡尔霍恩在1832年12月致州长的信中系统提出「一州可否判定联邦法违宪并使其在本州无效」的结论。",process:"1832年11月24日州特别会议通过《不服从令》，宣布两税法无效并规定2月起不得在本州征收，同时授权扩充民兵；杰克逊12月10日发表公告指分裂为叛国，1833年3月2日国会通过《强制法》授权动用军队征税，同月通过克莱提出的渐减关税妥协案；卡尔霍恩已于1832年12月28日辞副总统职，州会议3月撤销《不服从令》但宣布《强制法》在本州无效。",impact:"危机以「双方各让一步」收场，但把主权归属问题从论辩推向制度化对立，1840至1850年代两度以关税与领地奴隶制重演；拒行联邦论此后成为南方脱离论的法学前身，1860至1861年脱离文本大量援引1832至1833年先例。",figures:["安德鲁·杰克逊","约翰·C·卡尔霍恩","罗伯特·海恩"],place:"美国南卡罗来纳哥伦比亚",state:"美利坚合众国",sources:["【南卡罗来纳1832年11月24日《不服从令》全文】","【杰克逊1832年12月10日关于分裂的公告】"],tags:["州权","关税","分裂"]},related:["world--1828--e01", "world--1832--e01"]},
  {id:"world--1832--e01",track:"world",year:1832,yearApprox:false,dim:"economy",weight:3,title:"杰克逊否决银行特许状",summary:"国会续签申请被否，联邦存款外迁引发美国金融二十年动荡。",detail:{background:"合众国第二银行特许状1836年到期，行长比德尔提前于1832年申请续签以迫使杰克逊在大选前表态；杰克逊视垄断银行为特权政治的经济形态。",process:"1832年7月10日总统否决法案，咨文论证联邦特许违宪、大量股份为外国人持有、该行未能在危机中充当公共银行；否决成为竞选题，杰克逊连任后1833年9月起把联邦存款撤出该行、分存各州「宠物银行」，1836年特许状到期后本行转入州特许清算。",impact:"总统否决权从此成为塑造经济政策的常规工具，联邦央行真空使1837年恐慌时缺乏最后贷款人；同时各州银行滥发票据与投机的后果，直接促成1840年代自由银行制讨论与1863年国家银行法。",figures:["安德鲁·杰克逊","尼古拉斯·比德尔","罗杰·托尼"],place:"美国华盛顿、费城",state:"美利坚合众国",sources:["【杰克逊1832年7月10日否决咨文】原文","【《牛津美国史》第3卷《民主的兴起》】记否决的竞选后果与存款转移"],tags:["银行","否决","货币"]},related:["world--1825--e02", "world--1837--e01"]},
  {id:"world--1832--d01",track:"world",year:1832,yearApprox:false,dim:"disaster",weight:4,title:"霍乱席卷英法",summary:"1832年霍乱自北英格兰南推，伦敦与巴黎相继重疫。",detail:{background:"第二次霍乱大流行自恒河三角洲经俄国、北欧传入；1831年10月桑德兰出现英国首例，1832年1月苏格兰、2月英格兰北部与威尔士相继暴发。",process:"1832年3月底至4月巴黎开始流行，入秋后渐息，市卫生机构统计当年巴黎死亡约一万八千至两万人（不同口径差异明显）；伦敦自2月起发病，夏季高峰后累计死亡约五千三百人，英格兰与威尔士合计死亡约三万两千人（登记制度不全，学界以区间表述）。卫生当局以隔离、消毒与限制集会为主，「接触传染」与「瘴气」两派的争论同时激化。",impact:"疫情与1832年选举年叠加，巴黎6月因谣言与丧亲愤怒爆发暴动，英国则把供水、下水道与地方卫生机构议题推入议会，成为1848年《公共卫生法》与1850年代城市改造的起点；霍乱亦在北美与加勒比同步扩散。",figures:["埃德温·查德威克"],place:"英国伦敦、法国巴黎",state:"英国／法国",sources:["【1832年巴黎中央卫生委员会疫情统计公报】记本市死亡数","【《柳叶刀》1832年英格兰疫情通讯】记伦敦与各郡发病死亡"],tags:["霍乱","卫生","大流行"]},related:["world--1831--d01", "world--1832--p01"]},
  {id:"world--1832--f01",track:"world",year:1832,yearApprox:false,dim:"figure",weight:3,title:"歌德逝世与身后文本",summary:"《浮士德》第二部随其去世问世，魏玛古典主义落幕。",detail:{background:"歌德晚年同时整理《浮士德》第二部手稿与自传性著作，视其为毕生思想的总结；1831年后健康明显衰退。",process:"1832年3月22日在魏玛去世，终年82岁；同年其遗嘱执行人把《浮士德》第二部作为《歌德著作》续编出版，全剧距第一部完成近六十年。爱克曼整理的谈话录随后于1836年问世，「世界文学」概念即出自其中1827年的谈话。",impact:"歌德的去世把德国文学的经典地位固化为一门民族记忆工程，魏玛公国因他而获得超越邦国规模的文化象征；《浮士德》第二部的出版使19世纪后半叶的德语歌剧、哲学与诗学都必须绕过这一文本，也为1848年前后民族文化的政治挪用提供了资源。",figures:["约翰·沃尔夫冈·歌德","约翰·彼得·爱克曼"],place:"萨克森-魏玛-艾森纳赫魏玛",state:"德意志邦联／萨克森-魏玛-艾森纳赫",sources:["【歌德《浮士德》第二部（1832年身后出版）】","【爱克曼《歌德谈话录》（1836年）】记晚年自述与世界文学主张"],tags:["文学","魏玛","身后出版"]},related:["world--1831--c01"]},
  {id:"world--1833--e01",track:"world",year:1833,yearApprox:false,dim:"economy",weight:5,title:"英国废奴法通过",summary:"1833年法解放殖民地奴隶，并以学徒制与巨额补偿过渡。",detail:{background:"1831至1832年殖民地奴隶的起义（1831年牙买加「圣诞起义」最烈）与英国本土废奴请愿同时达到高峰，改革法通过后辉格政府获得立法空间。",process:"1833年8月28日御准：殖民地奴隶身份自1834年8月1日起改为「学徒」，种植园奴工六年、家务与店铺奴工四年，实际于1838年8月1日提前全部终止；法案拨付两千万英镑补偿（一千五百万为贷款、五百万为补助），约占当年英国政府支出的四成，并设专职保护人监督学徒契约。",impact:"英属加勒比种植园经济失去强制劳动基础，契约华工与「移民劳工」制度随之扩张；补偿金付给奴隶主而非被奴役者的结构成为后世赔偿争论的焦点，英国为该项贷款支付的利息直至2015年才全部清偿完毕。",figures:["托马斯·克拉克森","威伯福斯","格雷伯爵"],place:"英国伦敦与西印度群岛",state:"英国",sources:["【《1833年废奴法》正文】记学徒期限与补偿条款","【英国国家档案馆1833年奴隶补偿贷款档案】记贷款金额与2015年清偿"],tags:["废奴","补偿","加勒比"]},related:["world--1807--e01", "world--1833--i01", "world--1832--p02"]},
  {id:"world--1833--p01",track:"world",year:1833,yearApprox:false,dim:"politics",weight:3,title:"自由军攻入里斯本",summary:"佩德罗率军解围，米格尔派在葡萄牙内战中失守首都。",detail:{background:"1828年米格尔一世集权即位并废除1822年宪法，佩德罗一世在巴西退位后（1831年）以复位女儿玛丽亚二世为旗号组织远征，亚速尔岛成为基地。",process:"1832年7月远征军在明德洛登陆并占领波尔图，米格尔军围攻近一年；英国海军在河口维持「不干涉的威慑」，1833年7月24日佩德罗军自阿尔加维北上进入里斯本，米格尔军南撤，内战转入相持。",impact:"首都易手使自由派获得海关与外交承认的筹码，也使财政完全依赖英葡旧同盟与对巴西的债务；战争拖延与疟疾于1834年夺去佩德罗性命，其遗孤继位与宪政恢复由1834年协定正式确定。",figures:["佩德罗一世","米格尔一世","玛丽亚二世"],place:"葡萄牙里斯本、波尔图",state:"葡萄牙",sources:["【1833年葡萄牙摄政政府告军民文告（里斯本国家档案馆）】","【迪士尼《葡萄牙帝国史》第二卷（剑桥）】论内战与英葡调停"],tags:["内战","自由派","王位"]},related:["world--1831--p05", "world--1834--p01"]},
  {id:"world--1833--p02",track:"world",year:1833,yearApprox:false,dim:"politics",weight:3,title:"俄土签订温卡尔条约",summary:"八个月防御同盟使博斯普鲁斯对俄国单向开放，欧洲震怒。",detail:{background:"1833年5月埃及易卜拉欣帕夏兵临君士坦丁堡城下，奥斯曼政府向英法求援未果后转求俄国，6月俄军在博斯普鲁斯亚洲岸的温卡尔-伊斯凯莱西登陆；俄国外交素以打通海峡为要。",process:"1833年7月8日签约，公开条款为俄土和平与奥斯曼对俄让步，秘密附加条款约定八个月内两国防御同盟，奥斯曼承诺在俄国需要时开放达达尼尔海峡供俄军舰通行，且不得允许他国军舰进入。",impact:"条约有效期虽仅八个月（1833年10月起被各方斡旋削弱），但它第一次以书面形式把俄国军舰进入海峡的权利固定下来，英法以此为例推动1841年《伦敦公约》确立海峡和平时封闭惯例；奥斯曼则自此确立「借欧洲均势对抗俄国」的求生路线。",figures:["尼古拉一世","马哈茂德二世","穆罕默德·阿里"],place:"奥斯曼帝国博斯普鲁斯海峡",state:"俄罗斯帝国／奥斯曼帝国",sources:["【1833年7月8日《温卡尔-伊斯凯莱西条约》及其秘密附加条款】","【《剑桥俄国史》论1730至1855年俄国外交与海峡问题】记英法抗议与海峡问题"],tags:["海峡","奥斯曼","同盟"]},related:["world--1829--p02", "world--1826--e01"]},
  {id:"world--1833--i01",track:"world",year:1833,yearApprox:false,dim:"institution",weight:4,title:"英国首个工厂监督法",summary:"1833年法限定纺织厂童工时并首设中央视察员。",detail:{background:"1832年改革法后议会请愿潮高涨，沙夫茨伯里等乡绅与辉格议员合力推动对工厂劳动的立法调查。",process:"1833年8月法案规定：9岁以下禁止在羊毛、棉、麻与丝织厂做工，9至13岁每日至多9小时，13至18岁至多12小时且须夜间轮换，每日须受两小时初等教育；违法由治安法官处罚，并设领取薪俸的工厂视察员与年度视察报告制度。",impact:"这是英国第一次以独立官僚监察执行劳动限制，「视察员—年度报告—修法」的循环成为1844、1847与1850年工厂法的技术模板；但法案不含矿山与家庭作坊，且执法人数长期不足，实际效果被1842年矿山调查重新暴露。",figures:["安东尼·阿什利-库珀","迈克尔·萨德勒","约翰·桑德斯"],place:"英国英格兰与苏格兰",state:"英国",sources:["【《1833年工厂法》正文】记年龄分级工时与视察员设置","【霍布斯鲍姆《革命的年代：1789至1848》】论工厂立法与工人运动"],tags:["工厂法","童工","视察员"]},related:["world--1831--e01", "world--1834--e01"]},
  {id:"world--1833--p03",track:"world",year:1833,yearApprox:false,dim:"politics",weight:3,title:"公司丧失对华贸易垄断",summary:"1833年特许状法终止东印度公司商业职能，印中贸易向英商开放。",detail:{background:"1813年法案已开放印度贸易，公司仅保留对华茶叶与丝绸垄断；1830年后散商（港脚商人）与鸦片资本施压伦敦，自由贸易舆论与新获议席的工业城市形成合力。",process:"1833年8月《特许状法》规定公司自1834年4月起停止一切商业经营，仅保留受托治理印度的行政职能；同时对华贸易向英籍臣民全面开放，设商务总监替代公司大班，并把印度立法权集中于总督及其立法委员会（1834年成立以麦考利为主席的法律委员会）。",impact:"公司商馆体制的终结意味着中英贸易问题由「公司—行商」的私人协商转为政府外交与炮舰责任，商务总监义律的身份直接改变1839年冲突的性质；鸦片税收自此成为英印与后来海峡殖民地的财政支柱之一。",figures:["查尔斯·格兰特","威廉·本廷克","义律"],place:"英国伦敦、印度加尔各答、中国广州",state:"英国／英属印度",sources:["【《1833年特许状法》正文】记公司商业职能终止与对华开放条款","【《剑桥印度史》论1833年后的行政与立法改组】"],tags:["东印度公司","对华贸易","鸦片"]},related:["world--1819--e01", "world--1835--i01"]},
  {id:"world--1834--i01",track:"world",year:1834,yearApprox:false,dim:"institution",weight:4,title:"德意志关税同盟生效",summary:"1834年1月1日同盟税则施行，普鲁士主导的经济空间成形。",detail:{background:"普鲁士1818年废除境内关卡并设保护性对外税则，此后以减税协定把中小邦逐个纳入；1828至1833年与南德各邦、萨克森与汉诺威相继缔约。",process:"1834年1月1日起，普鲁士—南德集团与萨克森—图林根—汉诺威集团的税则同步生效，内部关税取消、共同对外税则与统一税线成立（1833年缔结的同盟条约规定期限与共同机构），人口约二千三百万，同盟议会设于柏林。",impact:"同盟首次实现「无政治统一的关税国家」，使德意志工业在英货压力下得到制度性庇护，同时以铁路、度量衡与专利的逐步统一为1871年政治统一预设了经济地理；奥地利因保护水平与产业结构不合而长期被排除在外。",figures:["弗里德里希·李斯特","克里斯蒂安·罗贝尔"],place:"德意志邦联柏林、各邦边境",state:"普鲁士王国／德意志关税同盟",sources:["【1833年德意志各邦关税同盟条约与1834年生效的同盟税则》】","【霍布斯鲍姆《革命的年代：1789至1848》】论关税同盟与德意志工业化"],tags:["关税同盟","普鲁士","保护关税"]},related:["world--1818--e01", "world--1819--p01"]},
  {id:"world--1834--e01",track:"world",year:1834,yearApprox:false,dim:"economy",weight:4,title:"英国新济贫法",summary:"1834年法以「劣等处置」重组救济，院外救济几近取消。",detail:{background:"1830年斯温骚乱后议会调查旧济贫法，委员会报告认为教区补贴制压低工资并助长「懒惰」，马尔萨斯人口论成为政策语言。",process:"1834年法案废止教区各自救济，强制联合济贫区并建济贫院，由三人常设济贫法委员会监督；救济原则定为「院内待遇必须低于最低独立劳动者的生活水准」，即所谓劣等处置与院舍测试，院外救济对能劳动者基本关闭。",impact:"新法确立了「以劳动市场的惩罚线设定社会救济上限」的现代福利制度反面范式，济贫院成为19世纪工人集体记忆中最深的怨恨来源（1837至1839年北部多次冲击济贫院事件）；同时其登记与统计体系为国民收入、健康与就业的官方量化奠定了档案基础。",figures:["埃德温·查德威克","纳骚·西尼尔","托马斯·马尔萨斯"],place:"英国英格兰与威尔士",state:"英国",sources:["【《1834年济贫法修正案》与济贫法委员会1834年报告】记劣等处置原则","【《不列颠百科全书》「新济贫法」条目】记济贫区联合与院舍测试"],tags:["济贫法","劳工","统计"]},related:["world--1831--e01", "world--1833--i01"]},
  {id:"world--1834--p01",track:"world",year:1834,yearApprox:false,dim:"politics",weight:3,title:"埃武拉蒙特协定结束葡内战",summary:"米格尔一世退位流亡，葡萄牙恢复宪政与摄政体制。",detail:{background:"1833年里斯本陷落后米格尔派退守南部，军队逃亡与财政崩溃使其无法继续作战；奥地利与教廷无力外援。",process:"1834年5月26日埃武拉蒙特协定签署：米格尔一世放弃王位并乘英国军舰流亡意大利，其母卡洛塔·若阿金娜王后同行；佩德罗一世已于同年5月病逝，幼女王玛丽亚二世继位，由萨尔达尼亚任摄政，1826年宪章恢复。",impact:"内战使葡萄牙在巴西承认独立后再失一个世代精英，财政长期依附英国；宪政虽恢复，但1834至1846年间选举权限于有产自由派，军阀与政党轮替政治由此定型，米格尔派则成为此后数十年南部保守叛乱的旗号。",figures:["米格尔一世","玛丽亚二世","萨尔达尼亚"],place:"葡萄牙埃武拉蒙特、里斯本",state:"葡萄牙",sources:["【1834年5月26日《埃武拉蒙特协定》正文】","【迪士尼《葡萄牙帝国史》第二卷（剑桥）】论内战结局与摄政体制"],tags:["内战","退位","宪政"]},related:["world--1833--p01", "world--1831--p05"]},
  {id:"world--1834--p02",track:"world",year:1834,yearApprox:false,dim:"politics",weight:3,title:"里昂工人第二次起义",summary:"1834年四月丝织工人巷战，遭镇压后工人运动转入秘密社团。",detail:{background:"1831年起义后复工条件未改，1834年2月罢工要求提高最低织价，七月法令解散工人互助社团并审判共和派记者，冲突转为政治性。",process:"1834年4月9日起克罗瓦-鲁斯等郊区筑垒巷战，政府调来正规军以炮火逐街清剿，四月下旬城陷；镇压造成士兵与平民合计逾千人死亡（当时官方与反对派统计差异极大，学界以区间表述），随后军事法庭判处数十人死刑并流放。",impact:"起义与1832年巴黎六月起义、1835年4月审判共同塑造了「工人阶级作为政治主体」的欧洲讨论，布朗基与巴贝斯1837年组织四季社并于1839年5月起义；这也使七月王朝的选举限制与集会法成为1848年革命的对象。",figures:["菲利普·布歇兹","戈德弗鲁瓦·卡瓦尼亚克","奥古斯特·布朗基"],place:"法国里昂",state:"法兰西王国",sources:["【1834年里昂军事法庭审判记录】记起诉罪名与量刑","【《新剑桥近代史》论法国工人运动与七月王朝的镇压】记两次丝织工人起义"],tags:["工人运动","巷战","七月王朝"]},related:["world--1831--p04", "world--1834--e01"]},
  {id:"world--1835--s01",track:"world",year:1835,yearApprox:false,dim:"science",weight:3,title:"小猎犬号抵达加拉帕戈斯",summary:"达尔文在群岛考察五周，地雀与龟类的地理差异动摇物种固定论。",detail:{background:"小猎犬号1831年12月启程测绘南美海岸，1835年9月15日至10月20日停靠群岛中数岛，随船无专业博物学家，采集由达尔文与船员完成。",process:"他在圣克鲁斯（查塔姆）岛观察火山地貌与巨龟，在圣萨尔瓦多（詹姆斯）岛等地收集地雀、嘲鸫与龟类标本；在查塔姆岛得知各岛龟壳形态可辨归属（此说出于随船的拜诺），回国后于1837年「转录本B」中首次写下物种可变的推断。",impact:"群岛经验与其后1836年澳洲与开普的类比共同构成1837至1844年物种推演的观察起点，但达尔文当时并未把样本按岛严格区分记录，这一细节在20世纪的达尔文年志研究中反复被校正；群岛此后成为「适应辐射」研究的经典场域。",figures:["查尔斯·达尔文","菲茨罗伊","詹姆斯·拜诺"],place:"加拉帕戈斯群岛（厄瓜多尔）",state:"英国（皇家海军测量船）",sources:["【达尔文《小猎犬号航海记》1839年初版加拉帕戈斯章】","【《达尔文书信集》（1985年起刊）】与其1837年物种笔记核对观念转变时点"],tags:["进化","考察","标本"]},related:["world--1831--x01", "world--1835--d01"]},
  {id:"world--1835--d01",track:"world",year:1835,yearApprox:false,dim:"disaster",weight:3,title:"智利康塞普西翁大地震",summary:"1835年2月沿海强震伴海啸与地形抬升，为地震学留下首个现场记录。",detail:{background:"康塞普西翁位于纳斯卡板块俯冲带，1751年与1822年均曾发生强震；1835年时城市正在1822年震后重建。",process:"1835年2月20日下午主震持续数分钟，随后海啸与余震持续一月以上，塔尔卡瓦诺与沿海港湾出现岸线变化；康塞普西翁与比尔维索几乎全毁，死亡人数各方记载自数百至数千不等（学界以区间表述），后世地震学目录据破裂范围估计震级约8级。",impact:"正在康塞普西翁与塔尔卡瓦诺一带的达尔文亲历主震，随后测量抬升的海蚀阶地并得出「大陆缓慢抬升」的结论，直接支撑其珊瑚环礁理论与1830年代均变论地质学；灾后的重建法规也首次以两层木构架限制石造高楼。",figures:["查尔斯·达尔文","菲茨罗伊"],place:"智利康塞普西翁、瓦尔帕莱索",state:"智利",sources:["【达尔文1835年2至3月智利地震地质笔记与书信】","【美国地质调查局历史强震事件清单】载1835年康塞普西翁震的震级估计区间"],tags:["地震","海啸","地质"]},related:["world--1835--s01"]},
  {id:"world--1835--i01",track:"world",year:1835,yearApprox:false,dim:"institution",weight:3,title:"麦考利公共教育决议",summary:"1835年决议确立英语为高教媒介，教育开支全面转向西方学科。",detail:{background:"英属印度内部东方学派与英国学派争执十余年，1823年设立印度印刷与公共教育部，1832至1833年总督委员会两次延宕政策决断。",process:"1835年2月2日法律委员麦考利提交《公共教育决议》，主张政府经费应用于传授欧洲与英国文学科学，以英语为教学媒介，贬斥梵语与阿拉伯语学术为「错误体系」；总督本廷克1835年3月7日批准，决议终止对东方书院的常规资助并改组加尔各答原有学院。",impact:"决议造就了19世纪下半叶以英语教育为渠道的印度知识阶层与文官应试群体，也奠定「渗透论」式文化政策的模板：以少数英语精英为中介向下扩散；其代价是本地语言学校体系与出版传统长期欠资，1854年伍德教育训令后建立的省制公办学校体系与民族语言运动皆是对此的回应。",figures:["托马斯·巴宾顿·麦考利","威廉·本廷克"],place:"英属印度加尔各答",state:"英国／英属印度",sources:["【麦考利1835年2月2日《公共教育决议》全文】","【1835年3月7日总督会议批准令（印度事务部档案）】"],tags:["英语教育","殖民","文官"]},related:["world--1833--p03", "world--1819--e01"]},
  {id:"world--1835--c01",track:"world",year:1835,yearApprox:false,dim:"culture",weight:4,title:"《论美国的民主》上卷出版",summary:"托克维尔以美国经验提出平等不可逆与多数暴政的危险。",detail:{background:"1831年托克维尔与博蒙以考察监狱制度为名赴美九个多月，遍访东部与西部、接触联邦党人余裔与贵格会；回国后受七月王朝史学界邀请撰写。",process:"1835年上卷在巴黎出版，论三色人种问题、联邦与法律、乡镇自由、结社与新闻、多数暴政；获法兰西学士院一等奖并迅速译成英德文。下卷至1840年出版，转向民主社会的心理与「温和专制」命题。",impact:"该书确立了政治社会学式的比较方法，其「平等与自由的张力」成为1848年后欧洲自由派反复援引的分析框架；1835至1840年间它同时被美国与法国读者挪用为政争工具，也首次把奴隶制与印第安人驱逐写入自由民主体制的结构性矛盾。",figures:["阿列克西·德·托克维尔","古斯塔夫·德·博蒙"],place:"法国巴黎、美国",state:"法兰西王国",sources:["【托克维尔《论美国的民主》上卷（1835年）序言与结论】","【《不列颠百科全书》「托克维尔」条目】记考察背景与两卷分册"],tags:["民主","平等","比较政治"]},related:["world--1832--p01", "world--1830--p01"]},
  {id:"world--1835--p01",track:"world",year:1835,yearApprox:false,dim:"politics",weight:3,title:"《新埃科塔条约》割让切罗基属地",summary:"少数派签名让出全部故土，迁移期限按条约强推。",detail:{background:"1830年《印第安人迁移法》后佐治亚州单方面延伸管辖并拍卖切罗基土地，1832至1835年联邦最高法院两案确认印第安部落为「国内依附民族」但无法阻止州行动。",process:"1835年12月29日在佐治亚州切罗基首都新埃科塔，以约翰·里奇兄弟为首的少数派约二十一名头人与联邦特使签订条约，以500万元并分配西部土地为条件割让佐治亚、田纳西、北卡与阿拉巴马的全部切罗基属地；部内民选政府反对并收集逾一万五千个签名请愿，参议院仍以一票多数批准（1836年5月）。",impact:"条约生效触发1838年强制集中与西迁，即所谓「泪痕之路」，迁移途中与集中营死亡人数各方统计差异大（学界一般以数千至上万区间表述）；1846年联邦以新条约为其部分补救并承认分裂派别的合法地位，但故土已永久丧失。",figures:["约翰·里奇","威廉·里奇","马丁·范布伦"],place:"美国佐治亚新埃科塔、俄克拉何马（印第安领地）",state:"美利坚合众国",sources:["【1835年12月29日《新埃科塔条约》正文与1836年参议院批准记录】","【切罗基民族1836年反条约请愿（美国国家档案馆印第安事务局卷）】"],tags:["迁移","条约","原住民"]},related:["world--1830--p04", "world--1838--d01"]},
  {id:"world--1836--p01",track:"world",year:1836,yearApprox:false,dim:"politics",weight:3,title:"得克萨斯宣告独立",summary:"阿拉莫失守后圣哈辛托一日决胜，墨西哥被迫承认分离。",detail:{background:"1835年墨西哥改行中央集权宪法并取消各省自治，移民的英籍垦民与墨西哥守军冲突；1835年10月冈萨雷斯事件后武装对峙升级为独立战争。",process:"1836年3月2日会议通过《独立宣言》；3月6日阿拉莫要塞陷落，守军约一百八十余人全部战死；4月21日休斯顿在圣哈辛托突袭，墨军阵亡六百余人、被俘数百，5月14日圣安纳在胁迫下签署《韦拉克鲁斯条约》承认独立。",impact:"得克萨斯共和国存续九年（1836至1845），墨西哥国会以签约受迫为由否定条约效力并坚持边界；并吞问题把新领土奴隶制争端推向联邦政争，1845年并吞直接触发1846年战争。",figures:["安东尼奥·洛佩斯·德·圣安纳","塞缪尔·休斯顿","威廉·特拉维斯"],place:"得克萨斯圣哈辛托、圣安东尼奥",state:"墨西哥／得克萨斯共和国",sources:["【1836年3月2日《得克萨斯独立宣言》正文】","【1836年5月14日《韦拉克鲁斯条约》与墨西哥国会1838年否定决议】"],tags:["独立","边界","奴隶制"]},related:["world--1821--p02", "world--1846--m01"]},
  {id:"world--1836--p02",track:"world",year:1836,yearApprox:false,dim:"politics",weight:3,title:"众院启用禁言规则",summary:"涉及奴隶制的请愿被一律拒绝受理，持续八年。",detail:{background:"1835年起废奴团体向众院递交要求结束哥伦比亚特区奴隶制与禁止州际奴隶贸易的请愿，南方议员主张必须拒绝受理以维护「和平」。",process:"1836年5月26日众院通过平特尼规则，此后每会期初以决议续行，规定一切涉及奴隶制的请愿「不予受理」；同期南方各州与联邦邮政扣押废奴印刷品，1835年10月查尔斯顿邮站当众拆毁邮件。",impact:"该规则把宪法请愿权程序性取消，前总统亚当斯以众议员身份连年辩论「受理即审查」的界限，1844年12月规则在领地扩张争议中被废除；废奴运动在此期间转向群众集会、出版与法庭诉讼。",figures:["威廉·平特尼","约翰·昆西·亚当斯","威廉·劳埃德·加里森"],place:"美国华盛顿、南卡罗来纳查尔斯顿",state:"美利坚合众国",sources:["【1836年众院关于奴隶制请愿的辩论记录】","【1844年12月3日众院废除该规则的表决记录】"],tags:["请愿权","奴隶制","程序"]},related:["world--1833--e01", "world--1832--p02"]},
  {id:"world--1837--s01",track:"world",year:1837,yearApprox:false,dim:"science",weight:4,title:"指针式电报取得专利",summary:"库克与惠斯通完成可运行电报，铁路通信时代开始。",detail:{background:"库克1836年见识德意志施泰因海尔的指针电报后回国寻找资金，惠斯通提供电磁学理论与线圈装置，二人1837年春建成四针与五针两套线路。",process:"1837年6月完成公开演示并于6月12日登记专利，以多根导线驱动指针字母盘、免译电码；1840年伦敦至布莱克沃尔约8公里铁路上全线敷设其电报并营业使用；惠斯通随后在1843年提出惠斯通电桥与双针差分收发法。",impact:"电报使信息传递首次脱离交通工具的速度上限，1843年国会委员会建议由国家建线，1846年伦敦至德特福德约82公里营业电报线通车，铁路调度与信号的电报化成为1840年代运输安全的关键，也为1850年代海底电缆与1865年国际电报公约提供了技术与制度模板。",figures:["威廉·福瑟吉尔·库克","查尔斯·惠斯通","塞缪尔·莫尔斯"],place:"英国伦敦",state:"英国",sources:["【库克与惠斯通1837年电报专利说明书（英国专利档案）】","【《新剑桥近代史》论电报与铁路通信的制度化】"],tags:["电报","专利","铁路"]},related:["world--1820--s01", "world--1831--s01"]},
  {id:"world--1837--p01",track:"world",year:1837,yearApprox:false,dim:"politics",weight:3,title:"维多利亚即位",summary:"威廉四世无嗣而终，十八岁的女王开启君主礼仪化时代。",detail:{background:"威廉四世合法子嗣早夭，1830年《摄政法》调整其弟肯特公爵一脉的继承安排；1837年6月20日国王去世，时任首相为墨尔本子爵。",process:"1837年6月20日维多利亚即位，1838年6月28日加冕，典礼首次向付费观众大规模开放；1839年5月皮尔因拒绝更换女王女官而放弃组阁，辉格党复任至1841年；1840年2月与阿尔伯特亲王成婚，此后亲王逐步介入王室事务与博览会筹备。",impact:"其在位期（1837至1901年）见证君主权力向「被咨询、被鼓励、被警告」的礼仪性角色转化，1867与1884年改革法把选民扩大到男性多数，1876年《印度帝号法》则以帝号统合殖民地象征体系；这一转型构成20世纪英国保留君主制的前提。",figures:["维多利亚女王","威廉四世","墨尔本子爵"],place:"英国伦敦、温莎",state:"英国",sources:["【1837年6月20日即位公告与枢密院顾问名单（英国国家档案馆）】","【《不列颠百科全书》「维多利亚」条目】"],tags:["王位继承","礼仪化","帝国"]},related:["world--1834--e01", "world--1839--m01"]},
  {id:"world--1837--p02",track:"world",year:1837,yearApprox:false,dim:"politics",weight:3,title:"上下加拿大武装叛乱",summary:"两地改革请愿失败后短暂起事，遭英军镇压。",detail:{background:"1791年宪法在两地设民选下院，但行政与拨款权掌握在总督与少数官僚集团手中；1830年代上下加拿大民选议会连年提出选举与责任政府改革，均被拒绝，1837年伦敦训令进一步收紧。",process:"1837年11月至12月，上加拿大麦肯齐一派在多伦多（时称约克）附近托朗斯酒馆据点被击溃，下加拿大爱国者在圣德尼（11月23日）与圣夏尔（11月25日）两度击败英军，12月初英军增援反攻后瓦解，领袖流亡美国；1838年秋跨境袭扰与再次起事同样失败，多人被绞刑或流放。",impact:"伦敦于1838年派达勒姆伯爵调查，其1839年报告建议合并两地并引入责任政府，1841年《联合法》生效、1848年责任政府确立；事件同时使英美关系因「卡罗琳号」被焚与边境志愿军而紧张，直至1842年条约划定东北边界。",figures:["威廉·里昂·麦肯齐","路易-约瑟夫·帕皮诺","达勒姆伯爵"],place:"英属北美上加拿大、下加拿大",state:"英国／英属北美",sources:["【1839年达勒姆《关于英属北美的事务报告》】","【1837至1838年两地军事审判记录】"],tags:["殖民地","责任政府","镇压"]},related:["world--1837--p01", "world--1841--i01"]},
  {id:"world--1837--e01",track:"world",year:1837,yearApprox:false,dim:"economy",weight:4,title:"美国1837年恐慌",summary:"银行暂停兑付引发五年萧条，西部投机与债务链断裂。",detail:{background:"1836年《存款分配令》把联邦盈余分散存入州银行、同年土地购买硬通货令收紧信贷，铁路与土地投机资金链开始断裂，1837年春伦敦资本回流加剧收缩。",process:"1837年5月10日纽约各银行暂停纸币兑付黄金，各州银行相继跟进，物价与工资长期低迷，1839年二次崩盘使中西部农场与州债券违约；联邦赤字持续，范布伦政府坚持独立国库制主张，1840年大选失利。",impact:"危机使美国在1837至1863年间没有中央银行式的最后贷款人，州银行票据成为流通主币；它同时把「硬通货—自由银行—联邦补贴」三条路线固化为此后二十年的党争主轴，1841年新《国家银行法》被哈里森两度否决，接任的泰勒又否决修正案，联邦层面最后贷款人的真空延续到1863年。",figures:["马丁·范布伦","托马斯·哈特·本顿","威廉·亨利·哈里森"],place:"美国纽约、费城、华盛顿",state:"美利坚合众国",sources:["【1837年5月纽约各银行暂停兑付公告与往来通信】","【《剑桥美国经济史》论1837年危机的信贷与物价后果】"],tags:["恐慌","银行","萧条"]},related:["world--1832--e01", "world--1825--e02"]},
  {id:"world--1837--f01",track:"world",year:1837,yearApprox:false,dim:"figure",weight:2,title:"普希金因决斗去世",summary:"与丹特士决斗两日后伤重而亡，终年三十七岁。",detail:{background:"1836年俄国书报审查与宫廷围绕普希金妻子的流言升级，荷兰公使养子丹特士连获挑战，尼古拉一世仅以书面劝解而未禁止。",process:"1837年2月8日（俄历1月27日）两人在圣彼得堡郊外决斗，普希金腹部中弹，两日后（俄历1月29日）去世；当局将其遗体移往普斯科夫省圣山修道院下葬，葬礼被限制为家庭仪式，悼念集会与悼念诗（莱蒙托夫之作）遭删改。",impact:"其去世使俄语文学失去民族语言的奠基者，《叶甫盖尼·奥涅金》全一卷正逢其辞世之年出版；此后四十年俄国文学的社会代言功能由诗人转移到小说家，而十二月党人余脉在审查体制下被彻底吸纳，1855年后才重新浮现。",figures:["亚历山大·普希金","若尔日·丹特士"],place:"俄罗斯帝国圣彼得堡",state:"俄罗斯帝国",sources:["【1837年2月决斗的警方与军医记录】","【普希金《叶甫盖尼·奥涅金》1837年初版全一卷】"],tags:["文学","决斗","审查"]},related:["world--1825--p02"]},
  {id:"world--1838--p01",track:"world",year:1838,yearApprox:false,dim:"politics",weight:5,title:"《人民宪章》发布",summary:"六点要求把工人选举权写成纲领，宪章运动由此得名。",detail:{background:"1832年改革法排斥工人选民的失望、1834年济贫法与1830年代农业衰退叠加，伦敦工匠与伯明翰政治联盟自1836年起联合起草请愿纲领。",process:"1838年6月由洛维特起草、苏格兰人阿奇提出六点框架并在伯明翰与格拉斯哥公开：成年男子普选、取消议员财产资格、秘密投票、年满二十一岁即可当选、按人口比例划分选区、议员支薪；同年秋冬各地成立宪章协会，1839年2月向议会递交第一份全国请愿。",impact:"三次大请愿（1839、1842、1848）均被下院否决，但其中数点先后实现：1872年秘密投票、1884年男子普选与按人口重划选区，议员支薪要到1911年才解决，唯每年改选的任期从未实行；运动确立了以群众签名请愿与宪定程序求变的工人政治路线，也促成1839年5月纽波特起义与「道义派」「武力派」分裂。",figures:["威廉·洛维特","费格斯·奥康纳","约翰·阿奇"],place:"英国伦敦、伯明翰、格拉斯哥",state:"英国",sources:["【1838年6月《人民宪章》原文六条】","【《不列颠百科全书》「宪章运动」条目】记协会组织与三次请愿"],tags:["宪章","普选","请愿"]},related:["world--1832--p01", "world--1819--p02", "world--1834--e01"]},
  {id:"world--1838--x01",track:"world",year:1838,yearApprox:false,dim:"explore",weight:3,title:"蒸汽船首次横渡大西洋",summary:"天狼星号与大西方号四日内先后抵达纽约，全程靠蒸汽。",detail:{background:"1819年萨凡纳号横渡主要仍靠风帆，1830年代明轮功率、铁壳与燃煤补给技术进步后，纯蒸汽横渡被证明可行，大西洋航线成为邮政与移民的争夺点。",process:"1838年4月「天狼星号」自爱尔兰金斯顿启航，途中烧家具与备用木料维持炉火，4月22日抵纽约；「大西方号」（布鲁内尔设计）4月23日抵达，单程约十七天，为首次全程蒸汽动力横渡；1840年丘纳德获英国邮政合同开通利物浦—哈利法克斯—波士顿定期班轮。",impact:"定期蒸汽邮船把跨大西洋通信从一到两个月压缩到两周左右，欧洲资本、报刊与移民潮由此并到同一时间轴；1845年螺旋桨与1850年代复合蒸汽机的改进进一步降低单位航程煤耗，1860年代后每年数十万人的跨洋迁移才具备经济条件。",figures:["伊桑巴德·金德姆·布鲁内尔","塞缪尔·丘纳德"],place:"北大西洋，科克至纽约",state:"英国／美利坚合众国",sources:["【1838年4月英美报刊与港口登记对两次抵达的报道】","【1840年丘纳德邮船合同文件（英国邮政总局档案）】"],tags:["蒸汽船","邮路","移民"]},related:["world--1819--x01", "world--1807--s01"]},
  {id:"world--1838--e01",track:"world",year:1838,yearApprox:false,dim:"economy",weight:3,title:"反谷物法同盟成立",summary:"曼彻斯特工厂主以院外动员挑战土地保护关税。",detail:{background:"1815与1828年谷物法维持国内粮价，工业资本抱怨工资成本与地租主导的议会结构；1836至1837年萧条与1838年歉收使面包价格问题激化。",process:"1838年11月曼彻斯特成立反谷物法协会、次年改称同盟，由布赖特与科布登领导；它以订阅费与地方支部、巡回演讲、廉价小册子和《同盟报》动员城市选民外的舆论，1842与1843年向议会递交大批请愿，1843年7月迫使下院成立谷物法调查委员会。",impact:"同盟是现代院外游说组织的原型，把关税从财政问题重构为「面包价格」的社会问题；其胜利即1846年谷物法废除，使英国转向单边自由贸易，1860年英法通商条约再把这一原则推向欧洲大陆。",figures:["理查德·科布登","约翰·布赖特","亚奇博尔德·普伦蒂斯"],place:"英国曼彻斯特、伦敦",state:"英国",sources:["【1838至1846年反谷物法同盟会议记录与年会报告】","【科布登1845至1846年关于谷物法的议会演讲记录】"],tags:["自由贸易","关税","游说"]},related:["world--1815--e01", "world--1846--e01"]},
  {id:"world--1838--d01",track:"world",year:1838,yearApprox:false,dim:"disaster",weight:3,title:"切罗基西迁「泪痕之路」",summary:"条约宽限期届满后强制集中，西迁途中大量死亡。",detail:{background:"1836年5月参院批准《新埃科塔条约》后，迁移宽限至1838年5月届满；东部分支拒绝迁移并在山地躲藏，佐治亚州要求联邦动用军队清退。",process:"1838年5至7月美军与州民兵把切罗基人集中到临时拘留营，随后分十三批西迁，陆路经田纳西、阿肯色至印第安领地，水路沿田纳西河与密西西比河转运；途中因霍乱、痢疾与冻饿死亡者，官方、部族与教会三方名册统计自数百至六千余不等，学界以区间表述。",impact:"强制迁移确立「以条约形式完成剥夺」的国内法先例，1846年新条约虽退还部分补偿并承认免役权，但故土流失不可逆转；切罗基在印第安领地重建部族政府、报纸与学院，1861至1865年又被迫卷入内战并再失属地。",figures:["约翰·罗斯","温菲尔德·斯科特"],place:"美国佐治亚至印第安领地",state:"美利坚合众国",sources:["【1838年5月10日温菲尔德·斯科特的迁移公告】","【1838至1839年切罗基迁移名册与教会记录】"],tags:["强制迁移","原住民","条约"]},related:["world--1835--p01", "world--1830--p04"]},
  {id:"world--1839--p01",track:"world",year:1839,yearApprox:false,dim:"politics",weight:5,title:"虎门销烟与中英开战",summary:"缴烟二百余万斤后冲突升级，粤海贸易中断。",detail:{background:"1836至1838年鸦片输入与白银外流加剧，道光帝1838年底任林则徐为钦差大臣赴广东查禁；1839年3月林则徐抵广州，令外商具结交烟并保证此后永不夹带。",process:"5至6月在虎门海滩以海水浸化法销毁缴获鸦片二万余箱、二百三十余万斤（据林则徐奏报）；7月林维喜案后义律拒绝移交英籍嫌犯并令英船拒绝具结，9月4日九龙海面交火，11月3日川岛海战后英军占大角、蛇头炮台，12月贸易中断。",impact:"冲突使中英关系从「公司—行商」的私人协商转为政府间交涉与炮舰责任，商务总监义律的身份正源于1833年特许状法；1840年2月英国任懿律、义律为正副全权，6月封锁珠江口，1842年条约的赔款、开埠与最惠国条款皆出自这两年的诉求清单。",figures:["林则徐","查理·义律","道光帝"],place:"中国广东广州、虎门",state:"清／英国",sources:["【《林文忠公政书》与1839年虎门销烟奏报】","【《剑桥中国晚清史》上卷论1839年冲突经过】"],tags:["禁烟","鸦片战争","通商"]},related:["world--1833--p03", "world--1842--p01", "cn--1839--p02", "cn--1840--p01"]},
  {id:"world--1839--s01",track:"world",year:1839,yearApprox:false,dim:"science",weight:5,title:"达盖尔摄影法公之于世",summary:"法国买断专利并公布银版法，图像复制脱离手工。",detail:{background:"涅普斯1820年代以沥青版制成最早的照片，1833年去世后达盖尔继续改良银版感光法；1838年他说服政府出面收买专利以求公开。",process:"1839年1月7日法兰西科学院与美术院联席会议宣布该方法：银版经碘蒸气感光、水银蒸气显影、浓食盐水中止显影；8月19日法国政府以终身年金买断专利并向全世界公布，阿拉戈的议会报告把它同时列为科学记录工具与艺术威胁；初期曝光需十余分钟，1840年后随快镜头与加速感光剂缩短。",impact:"肖像业在1840年代迅速扩散到城市中等阶层，天文、医学、考古与地理调查开始以影像为标准记录方式；它也使「影像作为证据」的认识论问题进入法律与新闻领域，并为1851年起博览会与纪实摄影的视觉文化奠基。",figures:["路易·雅克·曼德·达盖尔","约瑟夫·尼塞福尔·涅普斯","弗朗索瓦·阿拉戈"],place:"法国巴黎",state:"法兰西王国",sources:["【1839年《达盖尔摄影法的历史与说明》（含阿拉戈议会报告）】","【1839年8月19日法国政府公布专利的部令与年金记录】"],tags:["摄影","专利买断","科学记录"]},related:["world--1826--s01"]},
  {id:"world--1839--p02",track:"world",year:1839,yearApprox:false,dim:"politics",weight:4,title:"伦敦条约保障比利时中立",summary:"五强承认比利时独立并以条约担保其中立地位。",detail:{background:"1831年伦敦会议十八条被荷兰拒绝，1832年12月法军围攻安特卫普后荷兰仍拖延，比利时国界定与林堡、卢森堡归属悬而未决。",process:"1839年4月19日英、法、俄、奥、普五强与荷兰、比利时签二十四条条约：确认比利时独立与1831年边界，林堡东部与卢森堡东部归荷兰国王，斯海尔德河与默兹河通航自由，并规定比利时为「永久中立」，由签约各强共同担保。",impact:"条约把比利时的存在与中立写入欧洲公法，1870年与1914年两度被援引：1914年德国以该约为「一纸空文」为由借道比利时，英国则以破坏中立作为对德宣战的公开理由之一；条约对刚果的安排则把该地留给国王私人所有，至1885年柏林会议再定。",figures:["阿伯丁伯爵","利奥波德一世"],place:"英国伦敦、比利时布鲁塞尔",state:"欧洲五强／比利时王国",sources:["【1839年4月19日《伦敦条约》二十四条正文】","【《新剑桥近代史》论比利时中立与欧洲公法】"],tags:["中立","条约","均势"]},related:["world--1830--p03", "world--1831--p03", "world--1831--i01"]},
  {id:"world--1839--m01",track:"world",year:1839,yearApprox:false,dim:"military",weight:3,title:"英军入侵阿富汗",summary:"孟买与白沙瓦两路进军，8月占领喀布尔。",detail:{background:"多斯特·穆罕默德1837年取白沙瓦，俄国1837年使团抵喀布尔，英印总督奥克兰以「俄国南下」为据决定扶植流亡前王舒雅复位，1838年夏与兰季特·辛格及舒雅缔结三方之约。",process:"1839年4月「印度河军」两万余人自卡拉奇渡河并占领信德，1839年7月由开伯尔山口北上，8月7日进入喀布尔，多斯特·穆罕默德北逃后于1840年被俘；舒雅在英军驻防下即位，英印付年补助并控制其外交。",impact:"占领军军费与喀布尔驻军开支压垮英印财政，1841年11月喀布尔起义、1842年1月撤退途中几乎全军覆没（随军约一万六千人，仅布赖登军医等极少数抵达白沙瓦）；此役成为「前进政策」代价的经典案例，1878年第二次英阿战争卷土重来。",figures:["奥克兰伯爵","多斯特·穆罕默德·汗","威廉·布赖登"],place:"阿富汗喀布尔、开伯尔山口",state:"英国／英属印度／阿富汗",sources:["【1839年奥克兰总督与白沙瓦军政会议文件（印度事务部档案）】","【1842年关于喀布尔撤退的议会调查文件】"],tags:["入侵","大博弈","撤退"]},related:["world--1837--p01"]},
  {id:"world--1839--p03",track:"world",year:1839,yearApprox:false,dim:"politics",weight:3,title:"第一份宪章请愿被否",summary:"下院拒收全国签名请愿，纽波特起义随即失败。",detail:{background:"1839年2月宪章协会收集数十万至百余万签名（协会与官方计数相差悬殊）递交下院，辉格与保守两党均反对扩选。",process:"1839年7月12日下院以235票对46票决议拒绝受理请愿；同月伯明翰集会遭禁，奥康纳因煽动性文字被判十八个月监禁；11月3日蒙茅斯郡秘密集会决议行动，11月4日纽波特矿工武装占领邮局并与赶到的正规军、骑警交火，起义被击溃，随后大逮捕以叛国罪起诉数十人，数人判死刑后减为流放塔斯马尼亚。",impact:"起义失败使宪章运动在此后九年以请愿、罢工与合作社为主，「道义派」路线确立；同时它促成1840年济贫法与工厂问题的合流，也迫使两党把工人组织纳入政治计算，为1867年第二次改革法时工人选票的分化埋下伏笔。",figures:["费格斯·奥康纳","约翰·弗罗斯特"],place:"英国伦敦、威尔士纽波特",state:"英国",sources:["【1839年7月下院关于拒绝宪章请愿的辩论记录】","【1839至1840年蒙茅斯叛国案审判记录】"],tags:["宪章","起义","流放"]},related:["world--1838--p01", "world--1834--e01"]},
  {id:"world--1840--p01",track:"world",year:1840,yearApprox:false,dim:"politics",weight:4,title:"《怀唐伊条约》签署",summary:"英国与北毛利酋长订约，新西兰殖民权的法律依据成形。",detail:{background:"1832年起英国驻澳总督以船长名义干预新西兰海岸的毛利与垦民冲突，1839年新西兰公司拟在惠灵顿大规模购地设点，传教士与部分酋长请伦敦出面约束。",process:"1840年2月6日副总督霍布森在岛屿湾的怀唐伊与约四十名酋长签署条约，第一条把治权让与英王、第二条保障毛利土地与渔场的排他财产权、第三条给予毛利人英国臣民权利；英文本与毛利文本在「治权」概念上并不对应。1840年4至9月巡回副本征集约五百名酋长签名，另有数十名未签。",impact:"条约成为新西兰的建国文件与毛利权利争论的宪制枢纽，1845至1872年的毛利战争即以越界征收土地为起因之一；1975年设怀唐伊法庭、1985年修正案确立「条约原则」，其解释至今仍是新西兰国内政治的争点。",figures:["威廉·霍布森","霍内·黑凯","詹姆斯·巴斯比"],place:"新西兰怀唐伊（岛屿湾）",state:"英国／毛利部族",sources:["【1840年《怀唐伊条约》英文本与毛利文本对照】","【《不列颠百科全书》「怀唐伊条约」条目】记签名巡回与文本分歧"],tags:["条约","殖民","毛利"]},related:[]},
  {id:"world--1840--i01",track:"world",year:1840,yearApprox:false,dim:"institution",weight:3,title:"便士统一邮资实施",summary:"1840年国内邮资统一为一便士并首用邮票预付。",detail:{background:"1837年希尔的调查发现按里程与页数计费、由收件人付资的制度助长私递与拒收，曼彻斯特商会与议员推动立法。",process:"1839年8月议会通过《邮政经费法》，1840年1月10日实行统一国内邮资：半盎司以内一便士、由寄件人预付，1840年5月6日发行「黑便士」邮票作预付凭证；同期降低报纸邮资并扩大投递网，国内信件量由1839年约七千六百万件升至1842年约一亿六千八百万件。",impact:"邮政由牟利机构转为规模化的公共服务，统一预付邮资加邮票成为各国模板（1840年代瑞士、巴西、美国相继发行邮票）；通信成本骤降直接抬升识字率、家庭通信与商业契约、报刊流通的速度，也促使1847年起各国相互订立邮资协定，构成后来万国邮政联盟的基础。",figures:["罗兰·希尔"],place:"英国伦敦",state:"英国",sources:["【希尔1837年《邮政改革的性质与价值》】","【1839年《邮政经费法》与1840年1月10日财政部实施令】"],tags:["邮政","邮票","通信"]},related:["world--1837--s01", "world--1838--x01"]},
  {id:"world--1841--i01",track:"world",year:1841,yearApprox:false,dim:"institution",weight:3,title:"加拿大两省合并法",summary:"1841年上下加拿大合并为加拿大省，法裔地位成为争点。",detail:{background:"1839年达勒姆报告建议合并两地以解决财政并同化法裔，伦敦据此起草法案，魁北克方面强烈反对。",process:"法案1840年7月获御准、1841年1月10日生效：上下加拿大合并为加拿大省，设统一民选议会（两区各四十席），法语在立法与法院的地位受限，总督仍掌行政会议任命与否决权。1848年拉福丹—鲍德温政府依多数原则上任，责任政府惯例确立。",impact:"合并未能同化法裔，反而促成法语政治家与英语改革派的联盟并使加拿大省成为试验田；1841至1849年间首府多次迁移，1867年联邦制以「省权」而非「同化」重组双元结构，魁北克在联邦中的人口少数地位自此始。",figures:["达勒姆伯爵","路易斯-希波吕特·拉福丹","罗伯特·鲍德温"],place:"英属北美加拿大省",state:"英国／英属北美",sources:["【1840年《联合上加拿大与下加拿大法》正文】","【1848年加拿大省议会关于信任投票的辩论记录】"],tags:["合并","责任政府","法裔"]},related:["world--1837--p02"]},
  {id:"world--1842--p01",track:"world",year:1842,yearApprox:false,dim:"politics",weight:5,title:"《南京条约》订立",summary:"江宁签约割港开埠赔款，中英通商体制被改写。",detail:{background:"1840年6月懿律率远征军封锁珠江口并北取定海、抵天津外海，1841年《穿鼻草约》被双方否定后英国改取「直隶腹地施压」方略，1841至1842年英军先后占舟山、厦门、镇海与宁波，1842年7月至8月攻占乍浦、镇江并封锁长江。",process:"1842年8月29日中英在南京下关江面英舰上订立《江宁条约》正文十三款：赔款两千一百万银元分年支付、开放广州厦门福州宁波上海五口、割让香港岛、废除公行与行商担保责任、英籍臣民司法安排与协定关税。1843年7月《五口贸易章程》附约、10月中美《望厦条约》与1844年中法《黄埔条约》相继订约。",impact:"「赔款—开埠—最惠国」三要素构成此后不平等条约体系的原型，协定关税与领事裁判权长期制约清政府的财政与司法主权；条约虽止战，五口之外不得入内的限制与「入城问题」又成为1856至1860年第二次鸦片战争的争点。",figures:["璞鼎查","耆英","伊里布"],place:"中国江宁下关、上海",state:"清／英国",sources:["【1842年8月29日《江宁条约》中英对照正文十三款】","【《剑桥中国晚清史》上卷论条约款项与执行争议】"],tags:["条约","开埠","割地"]},related:["world--1839--p01", "world--1833--p03", "cn--1842--p01", "cn--1842--m01"]},
  {id:"world--1844--s01",track:"world",year:1844,yearApprox:false,dim:"science",weight:4,title:"莫尔斯电报线通车",summary:"华盛顿至巴尔的摩线路首次传送编码讯息。",detail:{background:"莫尔斯1832至1837年间形成点划码与中继继电器方案，1840年取得美国专利，1843年3月国会通过三万美元津贴资助试验线。",process:"1844年5月24日华盛顿至巴尔的摩约六十四公里架空电线通车，莫尔斯在国会会议厅发出由女性信使预先选定的圣经语句，四十四分钟后收到回文；线路以木杆架单线、继电器分段放大信号，1845年起由私营公司接续建线营业。",impact:"电报使报价、新闻与政令同步到分钟尺度，1846年美联社即由报社分摊电报费用而成立；1851年英吉利海峡电缆、1858年首次跨大西洋电缆把电报推向全球，1865年国际电报公约确立以法语为工作语言的规则，信息帝国时代由此开始。",figures:["塞缪尔·莫尔斯","阿尔弗雷德·维尔"],place:"美国华盛顿至巴尔的摩",state:"美利坚合众国",sources:["【1844年5月24日电报线的报文记录与公司账簿】","【1843年3月3日国会津贴法案（美国法律大全）】"],tags:["电报","编码","新闻"]},related:["world--1837--s01", "world--1840--i01"]},
  {id:"world--1845--d01",track:"world",year:1845,yearApprox:false,dim:"disaster",weight:5,title:"爱尔兰马铃薯饥荒开始",summary:"晚疫病连年毁薯，百万人死亡、百万人流亡。",detail:{background:"爱尔兰农业高度依赖马铃薯，1841年普查全岛约八一七万人，佃农地块零碎、余粮尽用于付租与出口；多数研究认为致病疫霉随北美种子在1840年代初中传入欧洲。",process:"1845年秋薯类大面积腐烂（通行估计损失约三分之一至一半），1846年几乎绝收；政府先以公共工程与玉米粉进口应对，1847年初撤销免费粥厂并依《济贫法》扩展院内救济，1847至1849年饥荒与斑疹伤寒、回归热叠加。死亡人数学界通行估计为1841至1851年间约一百万，同期出境移民约百万余，人口由1841年约八一七万降至1851年约六五五万（普查数）。",impact:"这是19世纪欧洲最严重的人口灾难之一，也是「饥荒在出口未断的联合王国内发生」这一政治指控的来源；它确立了持续百年的移民链，1860年代后芬尼亚兄弟会与美国爱尔兰裔选票政治、1879至1882年土地战争与购地法案均可溯于此。",figures:["约翰·拉塞尔","查尔斯·特雷维利安"],place:"爱尔兰（西部郡县最重）",state:"英国（爱尔兰）",sources:["【1841与1851年爱尔兰人口普查与郡县救济处登记】","【《不列颠百科全书》「爱尔兰大饥荒」条目】记疫病传入与政策步骤"],tags:["饥荒","疫病害","移民"]},related:["world--1834--e01", "world--1846--e01"]},
  {id:"world--1846--e01",track:"world",year:1846,yearApprox:false,dim:"economy",weight:4,title:"英国废除谷物法",summary:"皮尔以首相之位终止粮食保护关税，自由贸易确立为国策。",detail:{background:"1845年秋爱尔兰马铃薯绝收使粮价与进口需求陡升，皮尔认定必须减让关税，但内阁多数与乡村士绅坚持保护制。",process:"1845年12月皮尔辞职后复职，转向以特别法令开放粮食进口；1846年6月27日《进口法》与《糖税法》获御准，谷物法即时废止，六年期递减税率取代禁止性税率；6月29日保护派与辉格党联合否决《爱尔兰强制法》，皮尔当日辞职，保守党分裂为自由派与迪斯雷里派。",impact:"关税问题自此由财政议题转为分配议题，工业资本的政治影响力确立，城市人口与自由贸易成为保守党此后必须承接的遗产；爱尔兰地主的收入结构被永久削弱，而「废除谷物法=议会可自废其成员利益」的先例，被此后各国保护主义论者反复援引。",figures:["罗伯特·皮尔","本杰明·迪斯雷里","约瑟夫·休谟"],place:"英国伦敦",state:"英国",sources:["【1846年6月27日《进口法》正文】","【《议会辩论集》1846年5至6月卷】记表决与皮尔辞职"],tags:["自由贸易","废除","政党分裂"]},related:["world--1815--e01", "world--1845--d01"]},
  {id:"world--1846--m01",track:"world",year:1846,yearApprox:false,dim:"military",weight:4,title:"美墨战争爆发",summary:"格兰德河冲突后国会宣战，领土与奴隶制问题并起。",detail:{background:"1845年12月美国并吞得克萨斯，边界主张（纽埃西斯河与格兰德河）未决，同年11月斯莱尔使团被墨政府拒绝，波尔克以「昭昭天命」为纲。",process:"1846年4月泰勒率军进抵格兰德河北岸，5月8与9日在帕洛阿尔托、雷萨卡-德-拉-帕尔马交战；5月13日国会以墨方「侵入美国领土」为由通过宣战案，1846年6至8月基尔尼占圣菲、蒙特占加利福尼亚，12月波尔克咨文主张全面索取领土。",impact:"1847年3月斯科特在韦拉克鲁斯登陆、9月14日入墨西哥城；1848年2月《瓜达卢佩-伊达尔戈条约》以一千五百万美元购得今加州、内华达、犹他、亚利桑那大部与新墨西哥等地约一百三十余万平方公里，墨方损失约一半国土。战时提出的《威尔莫特但书》使领地奴隶制成为国会中心争点，1850年妥协与1854年堪萨斯法皆源于此。",figures:["詹姆斯·波尔克","扎卡里·泰勒","安东尼奥·洛佩斯·德·圣安纳"],place:"墨西哥北部、格兰德河",state:"美利坚合众国／墨西哥",sources:["【1846年5月13日美国国会对墨宣战联合决议】","【1848年2月2日《瓜达卢佩-伊达尔戈条约》第五款】"],tags:["战争","领土","奴隶制"]},related:["world--1836--p01", "world--1848--p01"]},
  {id:"world--1847--p01",track:"world",year:1847,yearApprox:false,dim:"politics",weight:3,title:"英国十小时工厂法",summary:"1847年限定纺织厂女工与少年日工十小时。",detail:{background:"1844年工厂法把「开始工作」写入定义并加重雇主责任，但十小时条款未获通过；沙夫茨伯里自1846年起在下院连提法案，「工厂派」与托利激进人道派结成联盟。",process:"1847年6月22日法案获御准，规定女工与十三至十八岁少年在纺织厂每日至多十小时、每周六十小时，且不得在晨六时至晚八时之外做工；十四岁以下儿童与成年男工不在本条之内，雇主随即以轮班制规避，须1850年《综合工厂法》统一用餐与工时、1853年扩及男少年方落实。",impact:"这是工时上限首次被写进英格兰工厂法，确立「国家可限制劳动契约」的原则，成为19世纪后期欧洲工时立法的起点（瑞士1877年、德意志1891年工厂条例）；对雇主而言它则是「契约自由可被多数政治推翻」的判例，自由市场论者此后以此案为戒。",figures:["沙夫茨伯里伯爵","理查德·奥斯特勒"],place:"英国英格兰纺织业区",state:"英国",sources:["【《1847年工厂法》正文工时条款】","【1850年《综合工厂法》与1853年修正案】记轮班规避与后续立法"],tags:["工厂法","工时","童工"]},related:["world--1833--i01", "world--1834--e01"]},
  {id:"world--1848--c01",track:"world",year:1848,yearApprox:false,dim:"culture",weight:5,title:"《共产党宣言》出版",summary:"同盟纲领以德文印行，阶级斗争史观进入政治实践。",detail:{background:"1847年6月与11月共产主义者同盟两次代表大会把「正义者同盟」改造为以科学论证为旗号的政党，并委托马克思与恩格斯起草纲领；恩格斯先拟《共产主义原理》问答稿。",process:"1848年2月在伦敦印成四十八页德文小册子，以「至今一切社会的历史都是阶级斗争的历史」开篇，论述资产阶级的革命作用与无产阶级的历史使命，提出推翻资产阶级统治、废除私有制的十条过渡措施，并以「全世界无产者，联合起来」收束；刊行数周后即逢巴黎二月革命。",impact:"文本在1848年革命失败后沉寂十余年，经1872年德文版序言（马克思、恩格斯指出纲领部分已不完全适用）与1888年恩格斯校订的英文版进入第二国际传播，此后成为二十世纪各国革命政党的共同模板；1920年陈望道中文全译本即以它为马克思主义系统入华的起点。",figures:["卡尔·马克思","弗里德里希·恩格斯","威廉·沃尔弗"],place:"英国伦敦",state:"共产主义者同盟（伦敦）",sources:["【《共产党宣言》1848年德文初版本】","【《马克思恩格斯全集》中文第二版相关卷次校勘说明】"],tags:["社会主义","纲领","阶级"]},related:["world--1831--f01", "world--1807--c01", "world--1848--p01"]},
  {id:"world--1848--p01",track:"world",year:1848,yearApprox:false,dim:"politics",weight:5,title:"法国二月革命与第二共和国",summary:"路易-菲利普退位，成年男子普选与社会共和诉求登场。",detail:{background:"1847年起「宴会运动」要求选举与议会改革（当时选民仅约二十四万人），1846至1847年农业歉收与工业危机推高失业，政府遂禁止预定于1848年2月22日的大型宴会。",process:"2月22至24日巴黎筑垒巷战，国民自卫军倒向革命，路易-菲利普退位并流亡英国；2月24日临时政府宣布共和，接受「劳动权」原则、设国家工场与十小时工作日、废除政治犯死刑与殖民地奴隶制（4月法令），3月5日按成年男子普选登记，4月23日选出制宪议会（投票约七百万人），11月4日颁布共和宪法并设直选总统。",impact:"成年男子普选在法国自此成为不可逆的制度，「社会共和国」的要求则在1848年6月工人起义被镇压后破裂（死亡数各方统计自一千五百至三千余不等，学界以区间表述）；秩序恐慌使路易·拿破仑以逾七百五十万票于12月当选总统，1851年12月政变与1852年帝制即由此出。",figures:["路易-菲利普","阿尔方斯·德·拉马丁","艾蒂安·卡贝"],place:"法国巴黎",state:"法兰西第二共和国",sources:["【1848年2月25至26日临时政府关于共和、劳动权与国家工场的法令】","【1848年4月23日选举令与投票统计（法国国家档案馆）】"],tags:["革命","普选","共和"]},related:["world--1830--p01", "world--1848--p02", "world--1848--c01"]},
  {id:"world--1848--p02",track:"world",year:1848,yearApprox:false,dim:"politics",weight:4,title:"维也纳与柏林三月革命",summary:"梅特涅出逃、普王让步，德意志与奥地利问题同时爆发。",detail:{background:"1848年2月巴黎革命的消息经电报与流亡者传至维也纳与德意志各邦，自由派已连年请愿要求出版自由、陪审审判与民族代表机构。",process:"3月13日维也纳学生与工人与军队巷战，梅特涅次日化装出逃伦敦，1848年12月费迪南一世退位；3月18日柏林巷战持续一昼夜，国王于3月21日撤出军队、承诺宪法与德意志事务，并为死难者举行送葬游行；3至5月巴登、巴伐利亚、萨克森相继改组内阁，5月18日法兰克福国民议会在圣保罗教堂开幕。",impact:"「三月革命」把民族统一与宪政两个目标同时推上台面，却也让自由派、工人派、中央集权派与联邦派的分歧暴露于同一议会；1849年巴登与德累斯顿起义被镇压后普鲁士进入「新时期」，奥地利于1851年恢复集权，而未完成的「小德意志」方案留待1866与1871年以战争方式解决。",figures:["克莱门斯·梅特涅","弗里德里希·威廉四世","路德夫·卡姆普豪森"],place:"奥地利维也纳、普鲁士柏林",state:"奥地利帝国／普鲁士王国",sources:["【1848年3月13至15日维也纳请愿书与梅特涅免职令】","【1848年3月18至21日柏林军队撤退公告与国王文告】"],tags:["三月革命","民族","宪政"]},related:["world--1819--p01", "world--1848--p01", "world--1830--p01"]},
  {id:"world--1857--m01",track:"world",year:1857,yearApprox:false,dim:"military",weight:4,title:"印度民族大起义",summary:"米鲁特兵变扩展为北印大规模反公司武装，两年后被镇压。",detail:{background:"东印度公司兼并与奥德、推行新式恩菲尔德步枪，印籍士兵的晋升限制与宗教积怨同时到点。",process:"1857年5月10日米鲁特兵变，起义军连夜驰往德里拥立莫卧儿末帝巴哈杜尔沙二世；坎普尔、勒克瑙、章西相继响应，英军反攻两年后于1858年5月夺回德里。",impact:"1858年《印度政府法》终止公司政权、改由英国君主直接统治，女王11月诏书承诺尊重土邦条约权利；镇压中的屠戮与报复使印度的政治记忆长期分裂。",figures:["巴哈杜尔沙二世","章西女王拉克什米·巴伊","科林·坎贝尔","达尔豪西"],place:"印度米鲁特、德里、坎普尔、勒克瑙",state:"英属印度／莫卧儿、土邦",sources:["【1858年8月2日《印度政府法》关于移交公司领地的条款】","【1858年11月1日维多利亚女王诏书承诺尊重土邦条约权利】"],tags:["兵变","殖民统治","政权移交"]},related:["world--1803--m01", "world--1833--p03"]},
  {id:"world--1859--s01",track:"world",year:1859,yearApprox:false,dim:"science",weight:5,title:"《物种起源》出版",summary:"达尔文以自然选择解释物种分化，初版当日售罄。",detail:{background:"达尔文自1831至1836年的小猎犬号航行积累生物地理与化石证据，1844年写成理论纲要，1858年又收到华莱士的相似手稿。",process:"1858年7月1日林奈学会宣读达尔文与华莱士论文；1859年11月24日默里出版《物种起源》，初版一千二百五十册当日售罄，以自然选择说明适应与物种分化。",impact:"共同祖先与选择机制把形态、分布与化石记录纳入同一说明框架，成为此后生物学主线，也引发关于人类起源与科学教育的长期争论。",figures:["查尔斯·达尔文","阿尔弗雷德·华莱士","查尔斯·莱尔","约瑟夫·道尔顿·胡克"],place:"英国伦敦、唐恩",state:"英国／林奈学会",sources:["【1859年初版《物种起源》序言与第十四章理论小结】","【1858年7月1日林奈学会宣读论文的会刊目录】"],tags:["进化论","自然选择","科学出版"]},related:["world--1831--x01"]},
  {id:"world--1860--s01",track:"world",year:1860,yearApprox:false,dim:"science",weight:3,title:"卡尔斯鲁厄化学会议",summary:"首届国际科学会议未能定论，康尼查罗小册终结原子量之争。",detail:{background:"原子量与当量两套算法并存，各国化学家写不出共同的分子式，凯库勒等人在比利时倡议召开国际聚会。",process:"1860年3月5至7日在巴登卡尔斯鲁厄开会，约140名化学家出席，为首次国际科学会议；会中未得结论，康尼查罗的支持者在会间散发其《化学理论要点》小册，重述阿伏加德罗分子假说与据气体密度定原子量之法。",impact:"1860年代中期后原子量表趋于统一，门捷列夫1869年周期律得以建立；会议本身亦成为索尔维会议等国际科学机制的先例。",figures:["奥古斯特·凯库勒","斯坦尼斯劳·康尼查罗","德米特里·门捷列夫"],place:"巴登大公国卡尔斯鲁厄",state:"欧洲化学界",sources:["【1860年卡尔斯鲁厄会议出席名册与会议记录】","【康尼查罗1860年《化学理论要点》（Sunto）】"],tags:["科学会议","原子量","分子论"]},related:["world--1811--s01", "world--1808--s01"]},
  {id:"world--1871--p01",track:"world",year:1871,yearApprox:false,dim:"politics",weight:5,title:"德意志帝国宣告成立",summary:"威廉一世在凡尔赛称帝，维也纳安排实际终结。",detail:{background:"1866年普奥战争后北德意志联邦成立，南德四邦入关税同盟与秘密军事条约；西班牙王位候选与埃姆斯电报把普法推向开战。",process:"1870年9月色当会战法军主力被围、拿破仑三世被俘；1871年1月18日威廉一世在凡尔赛宫镜厅宣告为德皇，巴伐利亚国王路德维希二世先行呈请；5月10日《法兰克福和约》割阿尔萨斯—洛林、赔款五十亿法郎。",impact:"中欧出现人口与工业实力最强的民族国家，1815年维也纳体系的实际后果就此终结；法国的复仇情绪与两省争议延续至1914年，俾斯麦此后以孤立法国为联盟体系主轴。",figures:["威廉一世","奥托·冯·俾斯麦","老毛奇","拿破仑三世"],place:"法国凡尔赛、法兰克福",state:"德意志帝国／法兰西第三共和国",sources:["【1871年5月10日《法兰克福和约》割地与赔款条款】","【1870年12月3日巴伐利亚国王呈请书与宣告程序记录】"],tags:["统一","和约","欧洲均势"]},related:["world--1806--p02", "world--1815--p01"]},
  {id:"world--1899--p01",track:"world",year:1899,yearApprox:false,dim:"politics",weight:3,title:"第二次布尔战争爆发",summary:"英国与德兰士瓦、奥兰治开战，游击战与集中营随之而来。",detail:{background:"德兰士瓦兰德外侨选举权争议与1896年詹森突袭使英布破裂，1899年10月9日布尔方最后通牒到期。",process:"10月11日英国宣战；布尔军围困莱迪史密斯，12月10至15日英军在斯托姆贝赫、马格斯方丹、科尔索三战皆北；1900年2月起罗伯茨与基钦纳反攻，3月占布隆方丹、6月占比勒陀利亚，战事转入游击阶段并广设收容营。",impact:"1902年5月31日《弗林尼京和约》结束战争；营中布尔平民死亡约两万六千人、黑人死者以万计，福西特委员会的调查迫使英方改善条件，战后重建与1910年南非联邦改写了南部非洲政治结构。",figures:["保罗·克鲁格","弗雷德里克·罗伯茨","霍雷肖·基钦纳","米勒森特·福西特"],place:"南非德兰士瓦、奥兰治、纳塔尔",state:"英国／德兰士瓦、奥兰治",sources:["【1902年5月31日《弗林尼京和约》条款】","【1902至1903年妇女与儿童状况委员会（福西特委员会）集中营死亡统计报告】"],tags:["殖民战争","收容营","和约"]},related:["world--1816--p02", "world--1899--p02"]},
  {id:"world--1899--p02",track:"world",year:1899,yearApprox:false,dim:"politics",weight:3,title:"第一次海牙和平会议",summary:"26国缔约设常设仲裁法院，裁军与强制仲裁落空。",detail:{background:"1898年8月尼古拉二世以外交照会发起国际会议，俄方名义为限缩军备，多数与会国更关心争端程序与战争法规。",process:"1899年5月18日至7月29日26国代表在海牙开会，通过《和平解决国际争端公约》并设立常设仲裁法院，另缔《陆战法规与惯例公约》及禁止膨胀性弹、禁止毒质弹、禁止自气球投弹三份宣言；裁军案未形成决议。",impact:"常设仲裁法院自1902年起运转，海牙陆战法规成为1907年第二次会议与此后战争法讨论的前案；裁军与强制仲裁的落空暴露出集体安全的程序缺口。",figures:["尼古拉二世","弗里德里希·冯·马尔滕斯","弗雷德里克·贝耶尔"],place:"荷兰海牙",state:"与会26国",sources:["【1899年7月29日海牙各公约与三份宣言文本】","【会议记录显示限缩军备议题未列入决议】"],tags:["国际法","仲裁","军备限制"]},related:["world--1815--p01", "world--1899--p01"]},
  {id:"world--1905--p01",track:"world",year:1905,yearApprox:false,dim:"politics",weight:3,title:"挪威脱离瑞挪联盟",summary:"以公民投票与国际承认和平结束八十余年的共主联盟。",detail:{background:"1814年联盟之下挪威保留宪法与自治，1890年代起的独立领事馆之争使双方僵持；1905年5月瑞典议会通过解散联盟法案，挪威内阁辞职被国王拒绝。",process:"1905年8月13日挪威公民投票，约三十六万八千票赞成、一百八十四票反对脱离；10月26日瑞典签署承认照会；11月第二次投票选定丹麦的卡尔王子为王，1906年即位称哈康七世。",impact:"共主联盟以投票与国际承认的方式和平解体，成为二十世纪分离问题的先例；挪威自此掌握独立外交，并确立议会制君主的运作惯例。",figures:["哈康七世","米哈埃尔·巴埃鲁姆","克里斯蒂安·米希尔特","奥斯卡二世"],place:"挪威克里斯蒂安尼亚、瑞典斯德哥尔摩",state:"挪威／瑞典—挪威联盟",sources:["【1905年8月13日挪威独立公投官方计票结果】","【1905年10月26日瑞典承认挪威分离的照会与条约】"],tags:["联盟解体","公投","民族自决"]},related:["world--1814--p03", "world--1814--p04"]},
];
